def get_db_connection():
    try:
        # Add timeout and connection settings to prevent lock issues
        connection_config = DB_CONFIG.copy()
        connection_config.update({
            'connect_timeout': 60,
            'read_timeout': 60,
            'write_timeout': 60,
            'autocommit': True  # Enable autocommit to prevent lock issues
        })
        connection = pymysql.connect(**connection_config)
        return connection
    except Exception as e:
        print(f"Database connection error: {str(e)}")
        print(f"Connection details: host={DB_CONFIG['host']}, user={DB_CONFIG['user']}, database={DB_CONFIG['database']}")
        raise e

def get_db_connection_no_db():
    try:
        # Add timeout and connection settings to prevent lock issues
        connection_config = DB_CONFIG_NO_DB.copy()
        connection_config.update({
            'connect_timeout': 60,
            'read_timeout': 60,
            'write_timeout': 60,
            'autocommit': True  # Enable autocommit to prevent lock issues
        })
        connection = pymysql.connect(**connection_config)
        return connection
    except Exception as e:
        print(f"Database connection error (no db): {str(e)}")
        print(f"Connection details: host={DB_CONFIG_NO_DB['host']}, user={DB_CONFIG_NO_DB['user']}")
        raise e

def hash_password(password):
    """Hash password using SHA-256"""
    return hashlib.sha256(password.encode()).hexdigest()

def generate_employee_code():
    """Generate a unique 6-digit employee code"""
    return str(secrets.randbelow(900000) + 100000)

def generate_pig_tag_id(pig_type):
    """Generate a unique tag ID for pigs based on type.
    Skips any ID already used in `pigs`. For L-tags, also skips IDs used in `litters.litter_id`
    (same L### namespace).
    """
    prefix_map = {
        'grown_pig': 'P',
        'piglet': 'S',
        'litter': 'L',
        'batch': 'B',
    }
    prefix = prefix_map.get(pig_type, 'P')

    def _id_taken(c, tid):
        c.execute("SELECT id FROM pigs WHERE tag_id = %s LIMIT 1", (tid,))
        if c.fetchone():
            return True
        if prefix == 'L':
            c.execute("SELECT id FROM litters WHERE litter_id = %s LIMIT 1", (tid,))
            if c.fetchone():
                return True
        return False

    try:
        conn = get_db_connection()
        cursor = conn.cursor()

        cursor.execute(
            """
            SELECT MAX(CAST(SUBSTRING(tag_id, 2) AS UNSIGNED)) as max_num
            FROM pigs
            WHERE tag_id LIKE %s
            """,
            (f"{prefix}%",),
        )
        max_pigs = (cursor.fetchone() or {}).get('max_num') or 0
        next_num = max_pigs

        if prefix == 'L':
            cursor.execute(
                """
                SELECT MAX(CAST(SUBSTRING(litter_id, 2) AS UNSIGNED)) as max_num
                FROM litters
                WHERE litter_id LIKE 'L%'
                """
            )
            max_litters = (cursor.fetchone() or {}).get('max_num') or 0
            next_num = max(next_num, max_litters)

        next_num = next_num + 1
        for _ in range(10000):
            tag_id = f"{prefix}{next_num:03d}"
            if not _id_taken(cursor, tag_id):
                cursor.close()
                conn.close()
                return tag_id
            next_num += 1

        cursor.close()
        conn.close()
        return f"{prefix}{next_num:03d}"
    except Exception as e:
        print(f"Error generating tag ID: {e}")
        import traceback
        traceback.print_exc()
        return f"{prefix}001"

def generate_litter_id():
    """Generate a unique sequential litter ID (L001, L002, etc.)"""
    try:
        conn = get_db_connection()
        cursor = conn.cursor()
        
        # Get the next available litter number
        cursor.execute("""
            SELECT MAX(CAST(SUBSTRING(litter_id, 2) AS UNSIGNED)) as max_num 
            FROM litters 
            WHERE litter_id LIKE 'L%'
        """)
        
        result = cursor.fetchone()
        next_num = (result['max_num'] or 0) + 1
        
        # Format as L + 3 digits (e.g., L001, L002, etc.)
        litter_id = f"L{next_num:03d}"
        
        # Double-check that this ID doesn't already exist
        cursor.execute("SELECT id FROM litters WHERE litter_id = %s", (litter_id,))
        if cursor.fetchone():
            # If it exists, try the next number
            next_num += 1
            litter_id = f"L{next_num:03d}"
        
        cursor.close()
        conn.close()
        
        print(f"Generated litter ID: {litter_id}")
        return litter_id
        
    except Exception as e:
        print(f"Error generating litter ID: {e}")
        import traceback
        traceback.print_exc()
        # Fallback: start from L001 if database query fails
        return f"L001"

def ensure_farrowing_activity_templates_table(cursor):
    """Ensure farrowing activity templates table exists and has defaults."""
    cursor.execute("""
        CREATE TABLE IF NOT EXISTS farrowing_activity_templates (
            id INT AUTO_INCREMENT PRIMARY KEY,
            due_day INT NOT NULL,
            activity_name VARCHAR(150) NOT NULL,
            is_active TINYINT(1) DEFAULT 1,
            created_by INT NULL,
            created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
            updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
        )
    """)

    cursor.execute("SELECT COUNT(*) AS cnt FROM farrowing_activity_templates")
    row = cursor.fetchone() or {}
    if int(row.get('cnt') or 0) == 0:
        # Defaults are intentionally combined by day (single row per day)
        defaults = [
            (1, 'Clear airways, ensure colostrum intake; Provide heat lamps; Remove afterbirth'),
            (2, 'Iron injections; Ear notching/tagging'),
            (3, 'Tail docking; Castration (males)'),
            (14, 'Start creep feed'),
            (21, 'Weaning')
        ]
        for due_day, activity_name in defaults:
            cursor.execute(
                "INSERT INTO farrowing_activity_templates (due_day, activity_name, is_active) VALUES (%s, %s, 1)",
                (due_day, activity_name)
            )

def combine_same_day_farrowing_templates(cursor):
    """Merge template rows so each due_day has one combined activity row."""
    ensure_farrowing_activity_templates_table(cursor)
    cursor.execute("""
        SELECT id, due_day, activity_name, is_active
        FROM farrowing_activity_templates
        ORDER BY due_day ASC, id ASC
    """)
    rows = cursor.fetchall() or []
    by_day = {}
    for r in rows:
        day = int(r['due_day'])
        by_day.setdefault(day, []).append(r)

    for day, group in by_day.items():
        if len(group) <= 1:
            continue

        parts = []
        is_active = 0
        for g in group:
            if g.get('is_active'):
                is_active = 1
            name = (g.get('activity_name') or '').strip()
            if name:
                # Split previously combined entries and de-duplicate while preserving order
                for p in [x.strip() for x in name.split(';') if x.strip()]:
                    if p not in parts:
                        parts.append(p)

        combined_name = '; '.join(parts)
        keeper = group[0]
        cursor.execute("""
            UPDATE farrowing_activity_templates
            SET activity_name = %s, is_active = %s, updated_at = NOW()
            WHERE id = %s
        """, (combined_name, is_active, keeper['id']))

        for g in group[1:]:
            cursor.execute("DELETE FROM farrowing_activity_templates WHERE id = %s", (g['id'],))

def _farrowing_date_to_sql(farrowing_date):
    if farrowing_date is None:
        return None
    if hasattr(farrowing_date, 'strftime'):
        return farrowing_date.strftime('%Y-%m-%d')
    s = str(farrowing_date).strip()
    return s[:10] if s else None

def resync_farrowing_activity_due_dates_for_record(cursor, farrowing_record_id, farrowing_date):
    """Recompute each activity's due_date from the canonical farrowing date + due_day."""
    fd = _farrowing_date_to_sql(farrowing_date)
    if not fd or not farrowing_record_id:
        return
    cursor.execute("""
        UPDATE farrowing_activities
        SET due_date = DATE_ADD(%s, INTERVAL due_day DAY)
        WHERE farrowing_record_id = %s
    """, (fd, farrowing_record_id))

def _coerce_farrowing_date(farrowing_date):
    """Return a date object from farrowing_date (date, datetime, or YYYY-MM-DD string)."""
    if farrowing_date is None:
        return None
    if isinstance(farrowing_date, datetime):
        return farrowing_date.date()
    if hasattr(farrowing_date, 'year') and hasattr(farrowing_date, 'month'):
        return farrowing_date
    fd = _farrowing_date_to_sql(farrowing_date)
    if not fd:
        return None
    return datetime.strptime(fd, '%Y-%m-%d').date()


def _farrowing_litter_age_days(cursor, farrowing_record_id, farrowing_date=None):
    """Days since farrowing for schedule applicability checks."""
    farrowing_date_obj = _coerce_farrowing_date(farrowing_date)
    if farrowing_date_obj is None and farrowing_record_id:
        cursor.execute(
            "SELECT farrowing_date FROM farrowing_records WHERE id = %s",
            (farrowing_record_id,),
        )
        row = cursor.fetchone()
        farrowing_date_obj = _coerce_farrowing_date(row.get('farrowing_date')) if row else None
    if not farrowing_date_obj:
        return None
    return (datetime.now().date() - farrowing_date_obj).days


def _farrowing_template_day_waived(litter_age_days, due_day):
    """True when the litter passed this schedule day and no activity row exists yet."""
    if litter_age_days is None:
        return False
    try:
        return litter_age_days >= int(due_day)
    except (TypeError, ValueError):
        return False


def sync_farrowing_activities_from_templates(cursor, farrowing_record_id, farrowing_date=None):
    """Align litter activities with Farrowing Activity Settings templates.

    - Future days: create or update open (incomplete) rows.
    - Past days missing a row: backfill a completed row (settings added after litter passed that day).
    - Past incomplete rows: left for the user to complete (overdue).
    - Completed rows are never rewritten.
    """
    if not farrowing_record_id:
        return
    farrowing_date_obj = _coerce_farrowing_date(farrowing_date)
    if farrowing_date_obj is None:
        cursor.execute(
            "SELECT farrowing_date FROM farrowing_records WHERE id = %s",
            (farrowing_record_id,),
        )
        row = cursor.fetchone()
        if not row:
            return
        farrowing_date_obj = _coerce_farrowing_date(row.get('farrowing_date'))
    if not farrowing_date_obj:
        return

    litter_age_days = _farrowing_litter_age_days(
        cursor, farrowing_record_id, farrowing_date_obj
    )

    def day_not_yet_attained(due_day):
        if litter_age_days is None:
            return True
        try:
            return litter_age_days < int(due_day)
        except (TypeError, ValueError):
            return False

    combine_same_day_farrowing_templates(cursor)
    cursor.execute("""
        SELECT due_day, activity_name
        FROM farrowing_activity_templates
        WHERE is_active = 1
        ORDER BY due_day ASC, id ASC
    """)
    template_by_day = {
        int(t['due_day']): (t.get('activity_name') or '').strip()
        for t in (cursor.fetchall() or [])
    }

    cursor.execute("""
        SELECT id, due_day, completed
        FROM farrowing_activities
        WHERE farrowing_record_id = %s
    """, (farrowing_record_id,))
    existing = cursor.fetchall() or []
    existing_by_day = {int(a['due_day']): a for a in existing}
    template_days = set(template_by_day.keys())
    touched = False
    retro_note = (
        'Auto-recorded: schedule day already passed when template was applied'
    )

    for due_day, activity_name in template_by_day.items():
        if not activity_name:
            continue
        due_date = farrowing_date_obj + timedelta(days=due_day)
        if due_day in existing_by_day:
            act = existing_by_day[due_day]
            if _activity_row_is_completed(act):
                continue
            if day_not_yet_attained(due_day):
                cursor.execute("""
                    UPDATE farrowing_activities
                    SET activity_name = %s, due_date = %s
                    WHERE id = %s
                """, (activity_name, due_date, act['id']))
                touched = True
            continue

        if day_not_yet_attained(due_day):
            cursor.execute("""
                INSERT INTO farrowing_activities (
                    farrowing_record_id, activity_name, due_day, due_date
                ) VALUES (%s, %s, %s, %s)
            """, (farrowing_record_id, activity_name, due_day, due_date))
            touched = True
        else:
            cursor.execute("""
                INSERT INTO farrowing_activities (
                    farrowing_record_id, activity_name, due_day, due_date,
                    completed, completed_date, notes
                ) VALUES (%s, %s, %s, %s, TRUE, %s, %s)
            """, (
                farrowing_record_id,
                activity_name,
                due_day,
                due_date,
                due_date,
                retro_note,
            ))
            touched = True

    for act in existing:
        if _activity_row_is_completed(act):
            continue
        day = int(act['due_day'])
        if not day_not_yet_attained(day):
            continue
        if day not in template_days:
            cursor.execute(
                "DELETE FROM farrowing_activities WHERE id = %s",
                (act['id'],),
            )
            touched = True

    if touched:
        resync_farrowing_activity_due_dates_for_record(
            cursor, farrowing_record_id, farrowing_date_obj
        )


def sync_unweaned_farrowing_activities_from_templates(cursor):
    """Refresh activity schedules for all litters still on the unweaned list."""
    cursor.execute("""
        SELECT DISTINCT fr.id, fr.farrowing_date
        FROM farrowing_records fr
        INNER JOIN litters l ON l.farrowing_record_id = fr.id
        WHERE l.status = 'unweaned'
    """)
    for row in cursor.fetchall() or []:
        sync_farrowing_activities_from_templates(
            cursor, row['id'], row.get('farrowing_date')
        )


def resync_farrowing_activity_due_dates_for_breeding(cursor, breeding_id, farrowing_date):
    """Recompute due dates for all activities tied to this breeding's farrowing record(s)."""
    fd = _farrowing_date_to_sql(farrowing_date)
    if not fd or not breeding_id:
        return
    cursor.execute("""
        UPDATE farrowing_activities fa
        JOIN farrowing_records fr ON fr.id = fa.farrowing_record_id
        SET fa.due_date = DATE_ADD(%s, INTERVAL fa.due_day DAY)
        WHERE fr.breeding_id = %s
    """, (fd, breeding_id))

def calculate_expected_weight(animal_id=None, litter_id=None, weighing_date=None):
    """Calculate expected weight based on age and weight categories"""
    conn = None
    cursor = None
    try:
        conn = get_db_connection()
        cursor = conn.cursor()
        
        # Get weight categories
        cursor.execute("""
            SELECT start_age, end_age, category_name, min_weight, max_weight, daily_gain
            FROM weight_categories
            ORDER BY start_age
        """)
        categories = cursor.fetchall()
        
        if not categories:
            return None
        
        # Get animal age
        age_days = None
        if animal_id:
            cursor.execute("SELECT birth_date FROM pigs WHERE id = %s", (animal_id,))
            result = cursor.fetchone()
            if result and result['birth_date']:
                age_days = (weighing_date - result['birth_date']).days
        elif litter_id:
            cursor.execute("SELECT farrowing_date FROM litters WHERE id = %s", (litter_id,))
            result = cursor.fetchone()
            if result and result['farrowing_date']:
                age_days = (weighing_date - result['farrowing_date']).days
        
        if age_days is None or age_days < 0:
            return None

        return _litter_expected_kg_for_age(age_days, categories)
        
    except Exception as e:
        print(f"Error calculating expected weight: {str(e)}")
        return None
    finally:
        if cursor:
            try:
                cursor.close()
            except Exception:
                pass
        if conn:
            try:
                conn.close()
            except Exception:
                pass


def _litter_expected_kg_for_age(age_days, categories):
    """
    Expected body weight (kg) for a piglet at age_days from farrowing, from weight_categories.
    Matches register-farrowing UI: newborns (age 0) use the lowest category when no row covers day 0.
    """
    if age_days is None or age_days < 0 or not categories:
        return None
    for c in categories:
        sa = int(c['start_age'])
        ea = int(c['end_age'])
        if sa <= age_days <= ea:
            days_in = age_days - sa
            return round(float(c['min_weight']) + days_in * float(c['daily_gain'] or 0), 2)
    min_start = min(int(c['start_age']) for c in categories)
    if age_days < min_start:
        c0 = next((x for x in categories if int(x['start_age']) == min_start), None)
        if c0:
            days_in = max(0, age_days - int(c0['start_age']))
            return round(float(c0['min_weight']) + days_in * float(c0['daily_gain'] or 0), 2)
    return None


def _as_date(d):
    if d is None:
        return None
    if isinstance(d, datetime):
        return d.date()
    if isinstance(d, date):
        return d
    return d


def _migration_001_sync_columns(cursor):
    """Ensure all expected columns exist (safe for local and hosted). Adds only if missing."""
    ec = db_migrations.ensure_column
    # Pigs
    ec(cursor, 'pigs', 'name', 'VARCHAR(100) NULL', after_column='tag_id')
    ec(cursor, 'pigs', 'gender', "ENUM('male', 'female') NULL", after_column='name')
    ec(cursor, 'pigs', 'birth_date', 'DATE NULL', after_column='gender')
    ec(cursor, 'pigs', 'pig_source', "ENUM('born', 'purchased') NOT NULL DEFAULT 'born'", after_column='pig_type')
    ec(cursor, 'pigs', 'breeding_status', "ENUM('young', 'available', 'served', 'pregnant') DEFAULT 'young'", after_column='purpose')
    ec(cursor, 'pigs', 'is_edited', 'BOOLEAN DEFAULT FALSE', after_column='updated_at')
    # Weight records
    ec(cursor, 'weight_records', 'litter_id', 'INT NULL', after_column='animal_id')
    ec(cursor, 'weight_records', 'expected_weight', 'DECIMAL(8,2) NULL', after_column='weight')
    ec(cursor, 'weight_records', 'weight_type', "ENUM('actual', 'expected') DEFAULT 'actual'", after_column='expected_weight')
    # Feeds
    ec(cursor, 'feeds', 'animal_type', "VARCHAR(20) NOT NULL DEFAULT 'pig'")
    # Feed stock
    ec(cursor, 'feed_stock', 'cost', 'DECIMAL(12,2) DEFAULT NULL')
    # Farrowing records
    ec(cursor, 'farrowing_records', 'dead_piglets', 'INT DEFAULT 0')
    ec(cursor, 'farrowing_records', 'weak_piglets', 'INT DEFAULT 0')
    ec(cursor, 'farrowing_records', 'notes', 'TEXT')
    ec(cursor, 'farrowing_records', 'updated_at', 'TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP')
    # Farrowing edit history (older hosted DBs may miss this column)
    if db_migrations.ensure_table_exists(cursor, 'farrowing_records_edit_history'):
        ec(cursor, 'farrowing_records_edit_history', 'field_name', 'VARCHAR(50) NOT NULL', after_column='record_id')
    # Farrowing activities
    ec(cursor, 'farrowing_activities', 'weaning_weight', 'DECIMAL(5,2) NULL')
    ec(cursor, 'farrowing_activities', 'weaning_date', 'DATETIME NULL')
    ec(cursor, 'farrowing_activities', 'completed_by', 'INT NULL')
    ec(cursor, 'farrowing_activities', 'updated_at', 'TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP')
    # Chicken production
    ec(cursor, 'chicken_production', 'updated_at', 'TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP')
    ec(cursor, 'chicken_production', 'created_by', 'INT NULL')
    # Feed settings (optional JSON column used in some flows)
    try:
        ec(cursor, 'feed_settings', 'feeding_times', 'JSON NULL')
    except Exception:
        pass

    # Slaughter / death / sale records: allow pig_type = batch (batch groups live in `pigs` like grown_pig)
    for tbl in ('slaughter_records', 'dead_pigs', 'sale_records'):
        if not db_migrations.ensure_table_exists(cursor, tbl):
            continue
        try:
            cursor.execute(
                f"ALTER TABLE {tbl} MODIFY COLUMN pig_type "
                "ENUM('grown_pig', 'litter', 'batch') NOT NULL"
            )
        except Exception as e:
            print(f"Note: {tbl} pig_type enum (batch) may already be applied: {e}")


def _migration_002_cow_breeding_ai(cursor):
    """Allow artificial insemination: nullable sire on breeding/calf, method + AI breed on cow_breeding."""
    if not db_migrations.ensure_table_exists(cursor, 'cow_breeding'):
        return
    ec = db_migrations.ensure_column
    ec(cursor, 'cow_breeding', 'breeding_method', "ENUM('natural', 'ai') NOT NULL DEFAULT 'natural'", after_column='sire_id')
    ec(cursor, 'cow_breeding', 'ai_breed', 'VARCHAR(255) NULL', after_column='breeding_method')
    cursor.execute("""
        SELECT IS_NULLABLE FROM INFORMATION_SCHEMA.COLUMNS
        WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'cow_breeding' AND COLUMN_NAME = 'sire_id'
    """)
    row = cursor.fetchone()
    if row and row.get('IS_NULLABLE') == 'NO':
        cursor.execute("ALTER TABLE cow_breeding MODIFY COLUMN sire_id INT NULL")
    if db_migrations.ensure_table_exists(cursor, 'calves'):
        cursor.execute("""
            SELECT IS_NULLABLE FROM INFORMATION_SCHEMA.COLUMNS
            WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'calves' AND COLUMN_NAME = 'sire_id'
        """)
        row = cursor.fetchone()
        if row and row.get('IS_NULLABLE') == 'NO':
            cursor.execute("ALTER TABLE calves MODIFY COLUMN sire_id INT NULL")


