def log_activity(employee_id, action, description, table_name=None, record_id=None):
    """Log employee activity"""
    try:
        conn = get_db_connection()
        cursor = conn.cursor()
        cursor.execute("""
            INSERT INTO activity_log (employee_id, action, description, table_name, record_id)
            VALUES (%s, %s, %s, %s, %s)
        """, (employee_id, action, description, table_name, record_id))
        # No need to commit since autocommit is enabled
        cursor.close()
        conn.close()
    except Exception as e:
        print(f"Error logging activity: {e}")
        # Don't raise the error to prevent breaking the main functionality

def update_pig_ages(cursor):
    """Update pig ages and breeding status based on current date"""
    try:
        # Get all pigs with birth dates
        cursor.execute("""
            SELECT id, birth_date, pig_type, purpose, breeding_status 
            FROM pigs 
            WHERE birth_date IS NOT NULL AND status = 'active'
        """)
        pigs = cursor.fetchall()
        
        updated_count = 0
        breeding_status_updates = 0
        
        for pig in pigs:
            try:
                # Calculate current age
                birth_dt = pig['birth_date']
                # Convert to date if it's datetime
                if isinstance(birth_dt, datetime):
                    birth_dt = birth_dt.date()
                current_age = (datetime.now().date() - birth_dt).days
                
                # Update age
                cursor.execute("UPDATE pigs SET age_days = %s WHERE id = %s", (current_age, pig['id']))
                
                # Update breeding status for grown pigs with breeding purpose.
                # Only promote young -> available based on age. NEVER overwrite
                # lifecycle states (served / pregnant / farrowed); those are owned
                # by the breeding/farrowing workflow and must not be reset here.
                if pig['pig_type'] == 'grown_pig' and pig['purpose'] == 'breeding':
                    current_status = pig['breeding_status']
                    if current_status == 'young' and current_age >= 200:
                        cursor.execute("""
                            UPDATE pigs
                            SET breeding_status = 'available'
                            WHERE id = %s
                        """, (pig['id'],))
                        breeding_status_updates += 1
                    elif current_status is None and current_age < 200:
                        # Initialize missing status for young breeding pigs only.
                        cursor.execute("""
                            UPDATE pigs
                            SET breeding_status = 'young'
                            WHERE id = %s
                        """, (pig['id'],))
                        breeding_status_updates += 1
                
                updated_count += 1
                
            except Exception as pig_error:
                print(f"Error updating pig {pig.get('id', 'unknown')}: {pig_error}")
                continue  # Continue with next pig instead of failing completely
        
        print(f"Updated ages for {updated_count} pigs, {breeding_status_updates} breeding status changes")
        return updated_count
        
    except Exception as e:
        print(f"Error updating pig ages: {e}")
        # Don't raise the error to prevent breaking login
        return 0

def get_role_dashboard_url(role):
    """Get the appropriate dashboard URL based on employee role"""
    role_urls = {
        'administrator': '/admin/dashboard',
        'manager': '/manager/dashboard',
        'employee': '/employee/dashboard',
        'vet': '/vet/dashboard',
        'it': '/it/dashboard'
    }
    return role_urls.get(role, '/employee/dashboard')


def _dashboard_department_link(department, animal_type, role):
    """Target page for admin dashboard department notification rows."""
    prefix = "/manager" if role == "manager" else "/admin"
    d = (department or "").strip()
    a = (animal_type or "").strip()
    if d == "Breeding" and a == "Pigs":
        return f"{prefix}/farm/breeding-records"
    if d == "Breeding" and a == "Cows":
        return f"{prefix}/farm/cow-breeding"
    if d == "Health" and a == "Pigs":
        return f"{prefix}/farm/pig-management"
    if d == "Health" and a == "Cows":
        return f"{prefix}/farm/cow-health"
    if d == "Medical" and a == "Pigs":
        return f"{prefix}/farm/pig-management"
    if d == "Medical" and a == "Cows":
        return f"{prefix}/farm/cow-management"
    if a == "Chickens":
        return f"{prefix}/farm/chicken-management"
    return f"{prefix}/dashboard"


def _enrich_dashboard_notifications(rows, role):
    out = []
    for row in rows or []:
        r = dict(row) if not isinstance(row, dict) else row.copy()
        r["link_url"] = _dashboard_department_link(
            r.get("department"), r.get("animal_type"), role
        )
        out.append(r)
    return out


DEFAULT_COMPANY_LOGO_STATIC = 'images/default-company-logo.svg'
ALLOWED_COMPANY_LOGO_EXTENSIONS = frozenset({'png', 'jpg', 'jpeg', 'webp', 'gif', 'svg'})


def get_company_branding():
    """Company name, contact, and logo URL for all templates (uses url_for; needs request context)."""
    defaults_name = 'Farm A'
    defaults_tag = 'Farm Management'
    safe_logo = url_for('static', filename=DEFAULT_COMPANY_LOGO_STATIC)
    fallback = {
        'company_name': defaults_name,
        'company_tagline': defaults_tag,
        'email': '',
        'phone': '',
        'location': '',
        'logo_path': None,
        'logo_url': safe_logo,
    }
    try:
        conn = get_db_connection()
        cursor = conn.cursor()
        cursor.execute("""
            SELECT company_name, company_tagline, email, phone, location, logo_path
            FROM company_settings WHERE id = 1
        """)
        row = cursor.fetchone()
        cursor.close()
        conn.close()
        if not row:
            return fallback
        lp = row.get('logo_path')
        if lp and isinstance(lp, str) and lp.strip() and '..' not in lp:
            logo_url = url_for('static', filename=lp.strip())
        else:
            logo_url = safe_logo
        return {
            'company_name': (row.get('company_name') or '').strip() or defaults_name,
            'company_tagline': (row.get('company_tagline') or '').strip() or defaults_tag,
            'email': (row.get('email') or '').strip(),
            'phone': (row.get('phone') or '').strip(),
            'location': (row.get('location') or '').strip(),
            'logo_path': lp.strip() if lp else None,
            'logo_url': logo_url,
        }
    except Exception as ex:
        print(f'get_company_branding: {ex}')
        return fallback


@app.context_processor
def inject_role_url():
    """Inject a helper function to generate role-based URLs"""
    def role_url(path):
        """Generate URL based on user role - converts /admin/ to /manager/ for managers"""
        if 'employee_role' in session:
            role = session.get('employee_role', 'administrator')
            if role == 'manager' and path.startswith('/admin/'):
                return path.replace('/admin/', '/manager/', 1)
        return path
    def pig_farm_base():
        """Role-aware base path for farm pig module pages."""
        if session.get('employee_role') == 'manager':
            return '/manager/farm/'
        return '/admin/farm/'

    def pig_breeding_management_url():
        """Canonical pig breeding management hub URL."""
        return pig_farm_base() + 'breeding-management'

    def pig_breeding_register_url():
        """Single entry point for registering a new pig breeding record."""
        return pig_breeding_management_url() + '?openRegister=1'

    return dict(
        role_url=role_url,
        pig_farm_base=pig_farm_base,
        pig_breeding_management_url=pig_breeding_management_url,
        pig_breeding_register_url=pig_breeding_register_url,
        app_version_label=get_git_version_label(),
        current_user_profile_image=get_current_employee_profile_image(),
        build_profile_image_url=build_profile_image_url,
        company_branding=get_company_branding(),
    )

