@app.route('/manager/farm/weight-analytics')
def manager_farm_weight_analytics():
    if 'employee_id' not in session or session.get('employee_role') not in ['administrator', 'manager']:
        return redirect(url_for('employee_login'))
    user_data = {
        'id': session['employee_id'], 'name': session['employee_name'],
        'role': session['employee_role'], 'status': session['employee_status'],
        'email': f"{session['employee_name'].lower().replace(' ', '.')}@farm.com"
    }
    try:
        conn = get_db_connection()
        cursor = conn.cursor()
        cursor.execute("""
            SELECT l.*, p.tag_id as sow_tag_id, p.breed as sow_breed, f.farm_name as farm_name
            FROM litters l LEFT JOIN pigs p ON l.sow_id = p.id LEFT JOIN farms f ON p.farm_id = f.id
            ORDER BY l.farrowing_date DESC
        """)
        litters = cursor.fetchall()
        cursor.execute("""
            SELECT p.*, f.farm_name, CASE WHEN p.birth_date IS NOT NULL THEN DATEDIFF(CURDATE(), p.birth_date) ELSE NULL END as age_days
            FROM pigs p LEFT JOIN farms f ON p.farm_id = f.id ORDER BY p.created_at DESC
        """)
        pigs = cursor.fetchall()
        cursor.close()
        conn.close()
        return render_template('admin_farm_weight_analytics.html', user=user_data, litters=litters, pigs=pigs)
    except Exception as e:
        print(f"Error loading data: {str(e)}")
        return render_template('admin_farm_weight_analytics.html', user=user_data, litters=[], pigs=[])

