        # Get all chickens grouped by type
        cursor.execute("""
            SELECT 
                chicken_id,
                batch_name,
                chicken_type,
                breed_name,
                gender,
                hatch_date,
                age_days,
                source,
                coop_number,
                quantity,
                current_status,
                registration_date
            FROM chickens 
            WHERE current_status = 'active'
            ORDER BY chicken_type, batch_name, chicken_id
        """)
