@app.route('/admin/farm/chicken-weight-standard', methods=['POST'])
def add_chicken_weight_standard():
    if 'employee_id' not in session or session.get('employee_role') not in ['administrator', 'manager']:
        return jsonify({'success': False, 'message': 'Unauthorized access'})
    
    try:
        category = request.form.get('category')
        start_age = request.form.get('start_age')
        end_age = request.form.get('end_age')
        weight_gain_per_day = request.form.get('weight_gain_per_day')
        description = request.form.get('description', '')
        
        if not category or not start_age or not end_age or not weight_gain_per_day:
            return jsonify({'success': False, 'message': 'Category, start age, end age, and weight gain per day are required'})
        
        start_age = int(start_age)
        end_age = int(end_age)
        weight_gain_per_day = float(weight_gain_per_day)
        
        if start_age >= end_age:
            return jsonify({'success': False, 'message': 'Start age must be less than end age'})
        
        conn = get_db_connection()
        cursor = conn.cursor()
        
        # Check if table exists and has old schema, then alter it
        cursor.execute("""
            SELECT COLUMN_NAME FROM INFORMATION_SCHEMA.COLUMNS 
            WHERE TABLE_SCHEMA = DATABASE() 
            AND TABLE_NAME = 'chicken_weight_standards'
        """)
        existing_columns = [row['COLUMN_NAME'] for row in cursor.fetchall()]
        
        # Create or alter chicken_weight_standards table
        if not existing_columns:
            # Create new table with new schema
            cursor.execute("""
                CREATE TABLE IF NOT EXISTS chicken_weight_standards (
                    id INT AUTO_INCREMENT PRIMARY KEY,
                    category ENUM('broiler', 'kienyeji', 'layer') NOT NULL,
                    start_age INT NOT NULL,
                    end_age INT NOT NULL,
                    weight_gain_per_day DECIMAL(8,4) NOT NULL COMMENT 'Weight gain in kg per day',
                    description TEXT,
                    created_by INT NOT NULL,
                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
                    INDEX idx_category (category),
                    INDEX idx_start_age (start_age),
                    INDEX idx_end_age (end_age),
                    UNIQUE KEY unique_category_age_range (category, start_age, end_age)
                ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
            """)
        else:
            # Alter existing table to add new columns if they don't exist
            if 'start_age' not in existing_columns:
                try:
                    cursor.execute("ALTER TABLE chicken_weight_standards ADD COLUMN start_age INT AFTER category")
                    conn.commit()
                except Exception as e:
                    print(f"Warning: Could not add start_age column: {str(e)}")
            
            if 'end_age' not in existing_columns:
                try:
                    cursor.execute("ALTER TABLE chicken_weight_standards ADD COLUMN end_age INT AFTER start_age")
                    conn.commit()
                except Exception as e:
                    print(f"Warning: Could not add end_age column: {str(e)}")
            
            if 'weight_gain_per_day' not in existing_columns:
                try:
                    cursor.execute("ALTER TABLE chicken_weight_standards ADD COLUMN weight_gain_per_day DECIMAL(8,4) AFTER end_age")
                    conn.commit()
                except Exception as e:
                    print(f"Warning: Could not add weight_gain_per_day column: {str(e)}")
            
            # If old columns exist but new ones don't, we need to handle migration
            if 'age_days' in existing_columns and 'start_age' not in existing_columns:
                # Migrate data: set start_age and end_age to age_days
                try:
                    cursor.execute("""
                        UPDATE chicken_weight_standards 
                        SET start_age = age_days, end_age = age_days 
                        WHERE start_age IS NULL OR end_age IS NULL
                    """)
                    conn.commit()
                except Exception as e:
                    print(f"Warning: Could not migrate age_days data: {str(e)}")
            
            if 'expected_weight' in existing_columns and 'weight_gain_per_day' not in existing_columns:
                # For old data, we can't automatically convert expected_weight to weight_gain_per_day
                # Set a default or leave it NULL (will need manual update)
                try:
                    cursor.execute("""
                        UPDATE chicken_weight_standards 
                        SET weight_gain_per_day = 0.050 
                        WHERE weight_gain_per_day IS NULL
                    """)
                    conn.commit()
                except Exception as e:
                    print(f"Warning: Could not set default weight_gain_per_day: {str(e)}")
            
            # Drop old unique constraint if it exists
            try:
                cursor.execute("ALTER TABLE chicken_weight_standards DROP INDEX unique_category_age")
                conn.commit()
            except Exception as e:
                print(f"Info: unique_category_age index does not exist or already dropped: {str(e)}")
            
            # Add new unique constraint if it doesn't exist
            try:
                cursor.execute("ALTER TABLE chicken_weight_standards ADD UNIQUE KEY unique_category_age_range (category, start_age, end_age)")
                conn.commit()
            except Exception as e:
                print(f"Info: unique_category_age_range constraint may already exist: {str(e)}")
        
        # Refresh column list after potential ALTER TABLE operations
        cursor.execute("""
            SELECT COLUMN_NAME FROM INFORMATION_SCHEMA.COLUMNS 
            WHERE TABLE_SCHEMA = DATABASE() 
            AND TABLE_NAME = 'chicken_weight_standards'
        """)
        final_columns = [row['COLUMN_NAME'] for row in cursor.fetchall()]
        
        # Check if weight standard already exists for this category and age range
        # Handle both old and new schema
        if 'start_age' in final_columns and 'end_age' in final_columns:
            cursor.execute("""
                SELECT id FROM chicken_weight_standards 
                WHERE category = %s AND start_age = %s AND end_age = %s
            """, (category, start_age, end_age))
        else:
            # Fallback to old schema check
            cursor.execute("""
                SELECT id FROM chicken_weight_standards 
                WHERE category = %s AND age_days = %s
            """, (category, start_age))
        
        existing = cursor.fetchone()
        if existing:
            return jsonify({'success': False, 'message': f'Weight standard already exists for {category} from {start_age} to {end_age} days'})
        
        # Check for overlapping age ranges (only if new columns exist)
        if 'start_age' in final_columns and 'end_age' in final_columns:
            cursor.execute("""
                SELECT id, start_age, end_age FROM chicken_weight_standards 
                WHERE category = %s AND (
                    (start_age <= %s AND end_age >= %s) OR
                    (start_age <= %s AND end_age >= %s) OR
                    (start_age >= %s AND end_age <= %s)
                )
            """, (category, start_age, start_age, end_age, end_age, start_age, end_age))
            
            overlapping = cursor.fetchone()
            if overlapping:
                return jsonify({'success': False, 'message': f'Weight standard overlaps with existing range for {category}'})
        
        # Insert new weight standard
        if 'start_age' in final_columns and 'end_age' in final_columns and 'weight_gain_per_day' in final_columns:
            # Use new schema
            cursor.execute("""
                INSERT INTO chicken_weight_standards (category, start_age, end_age, weight_gain_per_day, description, created_by)
                VALUES (%s, %s, %s, %s, %s, %s)
            """, (category, start_age, end_age, weight_gain_per_day, description, session['employee_id']))
        else:
            # Fallback to old schema (shouldn't happen if migration worked, but handle gracefully)
            return jsonify({
                'success': False, 
                'message': 'Database schema migration failed. Please contact administrator.'
            })
        
        conn.commit()
        cursor.close()
        conn.close()
        
        return jsonify({
            'success': True, 
            'message': f'Weight standard added successfully for {category} from {start_age} to {end_age} days!'
        })
        
    except ValueError as e:
        print(f"Validation error adding weight standard: {str(e)}")
        return jsonify({
            'success': False, 
            'message': f'Invalid input: {str(e)}'
        })
    except Exception as e:
        import traceback
        error_trace = traceback.format_exc()
        print(f"Error adding weight standard: {str(e)}")
        print(f"Traceback: {error_trace}")
        return jsonify({
            'success': False, 
            'message': f'Error adding weight standard: {str(e)}'
        })

@app.route('/admin/farm/chicken-weight-standard/<int:weight_standard_id>', methods=['PUT'])
def update_chicken_weight_standard(weight_standard_id):
    if 'employee_id' not in session or session.get('employee_role') not in ['administrator', 'manager']:
        return jsonify({'success': False, 'message': 'Unauthorized access'})
    
    try:
        category = request.form.get('category')
        start_age = request.form.get('start_age')
        end_age = request.form.get('end_age')
        weight_gain_per_day = request.form.get('weight_gain_per_day')
        description = request.form.get('description', '')
        
        if not category or not start_age or not end_age or not weight_gain_per_day:
            return jsonify({'success': False, 'message': 'Category, start age, end age, and weight gain per day are required'})
        
        start_age = int(start_age)
        end_age = int(end_age)
        weight_gain_per_day = float(weight_gain_per_day)
        
        if start_age >= end_age:
            return jsonify({'success': False, 'message': 'Start age must be less than end age'})
        
        conn = get_db_connection()
        cursor = conn.cursor()
        
        # Check if weight standard exists
        cursor.execute("""
            SELECT id FROM chicken_weight_standards WHERE id = %s
        """, (weight_standard_id,))
        
        if not cursor.fetchone():
            return jsonify({'success': False, 'message': 'Weight standard not found'})
        
        # Check if another weight standard already exists for this category and age range (excluding current)
        cursor.execute("""
            SELECT id FROM chicken_weight_standards 
            WHERE category = %s AND start_age = %s AND end_age = %s AND id != %s
        """, (category, start_age, end_age, weight_standard_id))
        
        existing = cursor.fetchone()
        if existing:
            return jsonify({'success': False, 'message': f'Weight standard already exists for {category} from {start_age} to {end_age} days'})
        
        # Check for overlapping age ranges (excluding current)
        cursor.execute("""
            SELECT id, start_age, end_age FROM chicken_weight_standards 
            WHERE category = %s AND id != %s AND (
                (start_age <= %s AND end_age >= %s) OR
                (start_age <= %s AND end_age >= %s) OR
                (start_age >= %s AND end_age <= %s)
            )
        """, (category, weight_standard_id, start_age, start_age, end_age, end_age, start_age, end_age))
        
        overlapping = cursor.fetchone()
        if overlapping:
            return jsonify({'success': False, 'message': f'Weight standard overlaps with existing range for {category}'})
        
        # Update weight standard
        cursor.execute("""
            UPDATE chicken_weight_standards 
            SET category = %s, start_age = %s, end_age = %s, weight_gain_per_day = %s, description = %s
            WHERE id = %s
        """, (category, start_age, end_age, weight_gain_per_day, description, weight_standard_id))
        
        conn.commit()
        cursor.close()
        conn.close()
        
        return jsonify({
            'success': True, 
            'message': f'Weight standard updated successfully for {category} from {start_age} to {end_age} days!'
        })
        
    except Exception as e:
        print(f"Error updating weight standard: {str(e)}")
        return jsonify({
            'success': False, 
            'message': f'Error updating weight standard: {str(e)}'
        })

