@app.route('/api/cow-feeding/cows', methods=['GET'])
def get_cows_for_feeding():
    """List active cows for feeding (id, ear_tag, name, age_days for feed settings matching)."""
    if 'employee_id' not in session:
        return jsonify({'success': False, 'message': 'Unauthorized'}), 401
    try:
        conn = get_db_connection()
        cursor = conn.cursor()
        cursor.execute("""
            SELECT id, ear_tag, name, breed, gender, status, birth_date, age_days,
                   COALESCE(age_days, DATEDIFF(CURDATE(), birth_date)) AS age_days_computed
            FROM cows
            WHERE status = 'active'
            ORDER BY ear_tag ASC
        """)
        rows = cursor.fetchall()
        cursor.close()
        conn.close()
        cows = []
        for r in rows:
            age_days = None
            if r.get('age_days_computed') is not None:
                try:
                    age_days = int(r['age_days_computed'])
                except (TypeError, ValueError):
                    pass
            cows.append({
                'id': r['id'],
                'ear_tag': r['ear_tag'],
                'name': r['name'] or r['ear_tag'],
                'breed': r['breed'],
                'gender': r['gender'],
                'age_days': age_days
            })
        return jsonify({'success': True, 'cows': cows})
    except Exception as e:
        return jsonify({'success': False, 'message': str(e)}), 500


@app.route('/api/cow-feeding/records', methods=['GET'])
def get_cow_feeding_records():
    """List cow feeding records (cow, feed, amount_kg, feeding_datetime, recorded_by). Optional: date, date_from, date_to for daily/range filter."""
    if 'employee_id' not in session:
        return jsonify({'success': False, 'message': 'Unauthorized'}), 401
    try:
        limit = min(request.args.get('limit', 100, type=int), 500)
        date = request.args.get('date')  # single day YYYY-MM-DD
        date_from = request.args.get('date_from')
        date_to = request.args.get('date_to')
        where_clause = "WHERE 1=1"
        params = []
        if date:
            where_clause += " AND DATE(cfr.feeding_datetime) = %s"
            params.append(date)
        if date_from:
            where_clause += " AND DATE(cfr.feeding_datetime) >= %s"
            params.append(date_from)
        if date_to:
            where_clause += " AND DATE(cfr.feeding_datetime) <= %s"
            params.append(date_to)
        params.append(limit)
        conn = get_db_connection()
        cursor = conn.cursor()
        cursor.execute("""
            SELECT
                cfr.id, cfr.cow_id, cfr.feed_id, cfr.amount_kg, cfr.feeding_datetime, cfr.notes,
                c.ear_tag, c.name as cow_name,
                f.feed_name, f.feed_type,
                e.full_name as created_by_name
            FROM cow_feeding_records cfr
            JOIN cows c ON cfr.cow_id = c.id
            JOIN feeds f ON cfr.feed_id = f.id
            JOIN employees e ON cfr.created_by = e.id
            """ + where_clause + """
            ORDER BY cfr.feeding_datetime DESC
            LIMIT %s
        """, params)
        rows = cursor.fetchall()
        cursor.close()
        conn.close()
        records = []
        for r in rows:
            records.append({
                'id': r['id'],
                'cow_id': r['cow_id'],
                'cow_ear_tag': r['ear_tag'],
                'cow_name': r['cow_name'] or r['ear_tag'],
                'feed_id': r['feed_id'],
                'feed_name': r['feed_name'],
                'feed_type': r['feed_type'],
                'amount_kg': float(r['amount_kg']),
                'feeding_datetime': r['feeding_datetime'].strftime('%Y-%m-%d %H:%M') if r['feeding_datetime'] else None,
                'notes': r['notes'],
                'created_by_name': r['created_by_name']
            })
        return jsonify({'success': True, 'records': records})
    except Exception as e:
        import traceback
        traceback.print_exc()
        return jsonify({'success': False, 'message': str(e)}), 500


@app.route('/api/cow-feeding/daily-summary', methods=['GET'])
def get_cow_feeding_daily_summary():
    """Get feeding summary for a single day: total_kg, records_count, cows_fed_count, by_feed breakdown. Query param: date=YYYY-MM-DD (default today)."""
    if 'employee_id' not in session:
        return jsonify({'success': False, 'message': 'Unauthorized'}), 401
    try:
        from datetime import date as date_type
        date_str = request.args.get('date')
        if date_str:
            try:
                target_date = date_type.fromisoformat(date_str)
            except ValueError:
                target_date = date_type.today()
        else:
            target_date = date_type.today()
        date_str = target_date.isoformat()
        conn = get_db_connection()
        cursor = conn.cursor()
        cursor.execute("""
            SELECT
                COALESCE(SUM(cfr.amount_kg), 0) as total_kg,
                COUNT(*) as records_count,
                COUNT(DISTINCT cfr.cow_id) as cows_fed_count
            FROM cow_feeding_records cfr
            WHERE DATE(cfr.feeding_datetime) = %s
        """, (date_str,))
        row = cursor.fetchone()
        total_kg = float(row['total_kg'] or 0)
        records_count = row['records_count'] or 0
        cows_fed_count = row['cows_fed_count'] or 0
        cursor.execute("""
            SELECT
                f.feed_name,
                f.feed_type,
                SUM(cfr.amount_kg) as total_kg,
                COUNT(DISTINCT cfr.cow_id) as cow_count
            FROM cow_feeding_records cfr
            JOIN feeds f ON cfr.feed_id = f.id
            WHERE DATE(cfr.feeding_datetime) = %s
            GROUP BY cfr.feed_id, f.feed_name, f.feed_type
            ORDER BY total_kg DESC
        """, (date_str,))
        by_feed = []
        for r in cursor.fetchall():
            by_feed.append({
                'feed_name': r['feed_name'],
                'feed_type': r['feed_type'],
                'total_kg': float(r['total_kg'] or 0),
                'cow_count': r['cow_count'] or 0
            })
        cursor.close()
        conn.close()
        return jsonify({
            'success': True,
            'date': date_str,
            'total_kg': round(total_kg, 2),
            'records_count': records_count,
            'cows_fed_count': cows_fed_count,
            'by_feed': by_feed
        })
    except Exception as e:
        import traceback
        traceback.print_exc()
        return jsonify({'success': False, 'message': str(e)}), 500


@app.route('/api/cow-feeding/analytics', methods=['GET'])
def get_cow_feeding_analytics():
    """Feeding record analytics: total_kg, records_count, by_feed, daily_totals (last 30 days). Optional: date_from, date_to."""
    if 'employee_id' not in session:
        return jsonify({'success': False, 'message': 'Unauthorized'}), 401
    try:
        date_from = request.args.get('date_from')
        date_to = request.args.get('date_to')
        conn = get_db_connection()
        cursor = conn.cursor()
        where = "WHERE 1=1"
        params = []
        if date_from:
            where += " AND DATE(cfr.feeding_datetime) >= %s"
            params.append(date_from)
        if date_to:
            where += " AND DATE(cfr.feeding_datetime) <= %s"
            params.append(date_to)
        cursor.execute("""
            SELECT
                COALESCE(SUM(cfr.amount_kg), 0) as total_kg,
                COUNT(*) as records_count,
                COUNT(DISTINCT cfr.cow_id) as cows_fed_count
            FROM cow_feeding_records cfr
            """ + where, params)
        row = cursor.fetchone()
        total_kg = float(row['total_kg'] or 0)
        records_count = row['records_count'] or 0
        cows_fed_count = row['cows_fed_count'] or 0
        cursor.execute("""
            SELECT
                f.id as feed_id,
                f.feed_name,
                SUM(cfr.amount_kg) as total_kg,
                COUNT(*) as record_count,
                COUNT(DISTINCT cfr.cow_id) as cow_count
            FROM cow_feeding_records cfr
            JOIN feeds f ON cfr.feed_id = f.id
            """ + where + """
            GROUP BY cfr.feed_id, f.id, f.feed_name
            ORDER BY total_kg DESC
        """, params)
        by_feed = []
        for r in cursor.fetchall():
            by_feed.append({
                'feed_id': r['feed_id'],
                'feed_name': r['feed_name'],
                'total_kg': round(float(r['total_kg'] or 0), 2),
                'record_count': r['record_count'] or 0,
                'cow_count': r['cow_count'] or 0
            })
        daily_params = []
        daily_where = "WHERE cfr.feeding_datetime >= DATE_SUB(CURDATE(), INTERVAL 30 DAY)"
        if date_from:
            daily_where += " AND DATE(cfr.feeding_datetime) >= %s"
            daily_params.append(date_from)
        if date_to:
            daily_where += " AND DATE(cfr.feeding_datetime) <= %s"
            daily_params.append(date_to)
        cursor.execute("""
            SELECT DATE(cfr.feeding_datetime) as d, SUM(cfr.amount_kg) as total_kg, COUNT(*) as cnt
            FROM cow_feeding_records cfr
            """ + daily_where + """
            GROUP BY DATE(cfr.feeding_datetime)
            ORDER BY d ASC
        """, daily_params)
        daily = []
        for r in cursor.fetchall():
            daily.append({
                'date': r['d'].isoformat() if r['d'] else None,
                'total_kg': round(float(r['total_kg'] or 0), 2),
                'record_count': r['cnt'] or 0
            })
        cursor.close()
        conn.close()
        return jsonify({
            'success': True,
            'total_kg': round(total_kg, 2),
            'records_count': records_count,
            'cows_fed_count': cows_fed_count,
            'by_feed': by_feed,
            'daily_totals': daily
        })
    except Exception as e:
        import traceback
        traceback.print_exc()
        return jsonify({'success': False, 'message': str(e)}), 500


def _default_farm_id(cursor):
    """Prefer active farm named 'Farm A' (case-insensitive), else lowest active farm id."""
    cursor.execute(
        """
        SELECT id FROM farms
        WHERE status = 'active' AND LOWER(TRIM(farm_name)) = 'farm a'
        LIMIT 1
        """
    )
    row = cursor.fetchone()
    if row:
        return row["id"]
    cursor.execute("SELECT id FROM farms WHERE status = 'active' ORDER BY id ASC LIMIT 1")
    row = cursor.fetchone()
    return row["id"] if row else 1


def _scoped_farm_id(cursor):
    """Single-site deployment: all reads/writes use the default farm; ignore client farm_id."""
    return _default_farm_id(cursor)


def _strip_farm_fields(row):
    """Omit farm-identifying keys from API payloads (single-site UI; DB columns may remain)."""
    if not row:
        return row
    d = dict(row)
    for k in (
        "farm_id",
        "farm_name",
        "farm_location",
        "sow_farm_id",
        "sow_farm_name",
    ):
        d.pop(k, None)
    return d


@app.route('/api/cow-feeding/record', methods=['POST'])
def record_cow_feeding():
    """Record feeding for one or more cows. entries: list of {cow_id, feed_id, amount_kg}. Deducts stock per feed and saves per-cow records."""
    if 'employee_id' not in session:
        return jsonify({'success': False, 'message': 'Unauthorized'}), 401
    try:
        # Accept both JSON fetch and normal form posts
        if request.is_json:
            data = request.get_json(silent=True) or {}
        else:
            data = request.form.to_dict() or {}
        entries = data.get('entries', [])  # list of {cow_id, feed_id, amount_kg} (feed_id per cow)
        feeding_datetime = data.get('feeding_datetime')
        notes = data.get('notes', '')
        if not entries:
            return jsonify({'success': False, 'message': 'entries (cow_id, feed_id, amount_kg) required'}), 400
        from datetime import datetime
        from collections import defaultdict
        now = datetime.now()
        if feeding_datetime:
            try:
                if isinstance(feeding_datetime, str) and 'T' in feeding_datetime:
                    feeding_datetime = datetime.fromisoformat(feeding_datetime.replace('Z', '+00:00')).replace(tzinfo=None)
                else:
                    feeding_datetime = datetime.strptime(feeding_datetime[:19], '%Y-%m-%d %H:%M:%S')
            except Exception:
                feeding_datetime = now
        else:
            feeding_datetime = now
        valid_entries = []
        for e in entries:
            cid = e.get('cow_id')
            fid = e.get('feed_id')
            amt = float(e.get('amount_kg', 0) or 0)
            if cid and fid and amt > 0:
                valid_entries.append({'cow_id': cid, 'feed_id': int(fid), 'amount_kg': amt, 'cow_ear_tag': e.get('cow_ear_tag')})
        if not valid_entries:
            return jsonify({'success': False, 'message': 'At least one entry with cow_id, feed_id and amount_kg > 0 required'}), 400
        conn = get_db_connection()
        cursor = conn.cursor()
        farm_id = _default_farm_id(cursor)
        transaction_date = feeding_datetime.date()
        feed_stock_ids = {}  # feed_id -> feed_stock_id for this batch
        by_feed = defaultdict(list)
        for e in valid_entries:
            by_feed[e['feed_id']].append(e)
        for feed_id, group in by_feed.items():
            cursor.execute("SELECT id, feed_name, unit_of_measure FROM feeds WHERE id = %s AND status = 'active'", (feed_id,))
            feed = cursor.fetchone()
            if not feed:
                continue
            total_kg = sum(x['amount_kg'] for x in group)
            unit = feed['unit_of_measure'] or 'kg'
            quantity = total_kg
            if unit == 'g':
                quantity = total_kg * 1000
            elif unit == 'ton':
                quantity = total_kg / 1000
            elif unit == 'bag':
                quantity = total_kg / 50
            cow_summary = [f"{x.get('cow_ear_tag') or x['cow_id']} {x['amount_kg']}kg" for x in group]
            notes_stock = 'Cow feeding: ' + ', '.join(cow_summary) if cow_summary else notes or 'Cow feeding'
            cursor.execute("""
                INSERT INTO feed_stock (feed_id, farm_id, transaction_type, quantity, unit_of_measure, transaction_date, notes, created_by)
                VALUES (%s, %s, 'stock_out', %s, %s, %s, %s, %s)
            """, (feed_id, farm_id, quantity, unit, transaction_date, notes_stock, session['employee_id']))
            feed_stock_ids[feed_id] = cursor.lastrowid
        for e in valid_entries:
            cid = e['cow_id']
            feed_id = e['feed_id']
            amt = e['amount_kg']
            feed_stock_id = feed_stock_ids.get(feed_id)
            if not feed_stock_id:
                continue
            cursor.execute("SELECT id, ear_tag FROM cows WHERE id = %s AND status = 'active'", (cid,))
            cow = cursor.fetchone()
            if not cow:
                continue
            cursor.execute("""
                INSERT INTO cow_feeding_records (cow_id, feed_id, farm_id, amount_kg, feeding_datetime, notes, feed_stock_id, created_by)
                VALUES (%s, %s, %s, %s, %s, %s, %s, %s)
            """, (cid, feed_id, farm_id, amt, feeding_datetime, notes, feed_stock_id, session['employee_id']))
        total_kg = sum(e['amount_kg'] for e in valid_entries)
        conn.commit()
        cursor.close()
        conn.close()
        return jsonify({
            'success': True,
            'message': f'Recorded feeding for {len(valid_entries)} cow(s), total {total_kg:.2f} kg. Stock updated.',
            'total_kg': total_kg
        })
    except Exception as e:
        import traceback
        traceback.print_exc()
        return jsonify({'success': False, 'message': str(e)}), 500


@app.route('/api/cow-feeding/upcoming', methods=['GET'])
def get_cow_feeding_upcoming():
    """Get upcoming feeding times from feed_settings (animal_type=cow) and cow count."""
    if 'employee_id' not in session:
        return jsonify({'success': False, 'message': 'Unauthorized'}), 401
    try:
        import json
        conn = get_db_connection()
        cursor = conn.cursor()
        cursor.execute("SELECT COUNT(*) as total FROM cows WHERE status = 'active'")
        cow_count = (cursor.fetchone() or {}).get('total') or 0
        cursor.execute("""
            SELECT id, age_group_name, feed_type, feeding_times_per_day, feeding_times, feed_amount_grams
            FROM feed_settings
            WHERE status = 'active' AND animal_type = 'cow'
        """)
        settings = cursor.fetchall()
        now = __import__('datetime').datetime.now()
        current_minutes = now.hour * 60 + now.minute
        upcoming = []
        for s in settings:
            times = []
            if s.get('feeding_times'):
                try:
                    times = json.loads(s['feeding_times']) if isinstance(s['feeding_times'], str) else (s['feeding_times'] or [])
                except Exception:
                    times = []
            if not times:
                continue
            for t in times:
                if not t:
                    continue
                try:
                    parts = str(t).split(':')
                    h, m = int(parts[0]), int(parts[1]) if len(parts) > 1 else 0
                    slot_minutes = h * 60 + m
                    diff = slot_minutes - current_minutes
                    if diff < 0:
                        diff += 24 * 60
                    upcoming.append({
                        'time': f"{h:02d}:{m:02d}",
                        'minutes_from_now': diff,
                        'age_group': s['age_group_name'],
                        'feed_id': int(s['feed_type']) if s.get('feed_type') and str(s['feed_type']).isdigit() else None
                    })
                except Exception:
                    continue
        upcoming.sort(key=lambda x: x['minutes_from_now'])
        cursor.close()
        conn.close()
        return jsonify({'success': True, 'upcoming': upcoming[:10], 'cow_count': cow_count})
    except Exception as e:
        return jsonify({'success': False, 'message': str(e)}), 500


# ----- Pig feeding APIs (mirror of cow feeding) -----
@app.route('/api/pig-feeding/pigs', methods=['GET'])
def get_pigs_for_feeding():
    """List active pigs for feeding (id, tag_id, age_days for feed settings matching)."""
    if 'employee_id' not in session:
        return jsonify({'success': False, 'message': 'Unauthorized'}), 401
    try:
        conn = get_db_connection()
        cursor = conn.cursor()
        cursor.execute("""
            SELECT id, tag_id, breed, gender, status, birth_date, age_days,
                   COALESCE(age_days, DATEDIFF(CURDATE(), birth_date)) AS age_days_computed
            FROM pigs
            WHERE status = 'active'
            ORDER BY tag_id ASC
        """)
        rows = cursor.fetchall()
        cursor.close()
        conn.close()
        pigs = []
        for r in rows:
            age_days = None
            if r.get('age_days_computed') is not None:
                try:
                    age_days = int(r['age_days_computed'])
                except (TypeError, ValueError):
                    pass
            pigs.append({
                'id': r['id'],
                'tag_id': r['tag_id'],
                'name': r['tag_id'],
                'breed': r['breed'],
                'gender': r['gender'],
                'age_days': age_days
            })
        return jsonify({'success': True, 'pigs': pigs})
    except Exception as e:
        return jsonify({'success': False, 'message': str(e)}), 500


@app.route('/api/pig-feeding/records', methods=['GET'])
def get_pig_feeding_records():
    """List pig feeding records. Optional: date, date_from, date_to."""
    if 'employee_id' not in session:
        return jsonify({'success': False, 'message': 'Unauthorized'}), 401
    try:
        limit = min(request.args.get('limit', 100, type=int), 500)
        date = request.args.get('date')
        date_from = request.args.get('date_from')
        date_to = request.args.get('date_to')
        where_clause = "WHERE 1=1"
        params = []
        if date:
            where_clause += " AND DATE(pfr.feeding_datetime) = %s"
            params.append(date)
        if date_from:
            where_clause += " AND DATE(pfr.feeding_datetime) >= %s"
            params.append(date_from)
        if date_to:
            where_clause += " AND DATE(pfr.feeding_datetime) <= %s"
            params.append(date_to)
        params.append(limit)
        conn = get_db_connection()
        cursor = conn.cursor()
        cursor.execute("""
            SELECT pfr.id, pfr.pig_id, pfr.feed_id, pfr.amount_kg, pfr.feeding_datetime, pfr.notes,
                p.tag_id, f.feed_name, f.feed_type, e.full_name as created_by_name
            FROM pig_feeding_records pfr
            JOIN pigs p ON pfr.pig_id = p.id
            JOIN feeds f ON pfr.feed_id = f.id
            JOIN employees e ON pfr.created_by = e.id
            """ + where_clause + """
            ORDER BY pfr.feeding_datetime DESC
            LIMIT %s
        """, params)
        rows = cursor.fetchall()
        cursor.close()
        conn.close()
        records = []
        for r in rows:
            records.append({
                'id': r['id'], 'pig_id': r['pig_id'], 'pig_tag_id': r['tag_id'], 'pig_name': r['tag_id'],
                'feed_id': r['feed_id'], 'feed_name': r['feed_name'], 'feed_type': r['feed_type'],
                'amount_kg': float(r['amount_kg']),
                'feeding_datetime': r['feeding_datetime'].strftime('%Y-%m-%d %H:%M') if r['feeding_datetime'] else None,
                'notes': r['notes'], 'created_by_name': r['created_by_name']
            })
        return jsonify({'success': True, 'records': records})
    except Exception as e:
        import traceback
        traceback.print_exc()
        return jsonify({'success': False, 'message': str(e)}), 500


@app.route('/api/pig-feeding/daily-summary', methods=['GET'])
def get_pig_feeding_daily_summary():
    """Daily feeding summary for pigs. Query param: date=YYYY-MM-DD (default today)."""
    if 'employee_id' not in session:
        return jsonify({'success': False, 'message': 'Unauthorized'}), 401
    try:
        from datetime import date as date_type
        date_str = request.args.get('date')
        if date_str:
            try:
                target_date = date_type.fromisoformat(date_str)
            except ValueError:
                target_date = date_type.today()
        else:
            target_date = date_type.today()
        date_str = target_date.isoformat()
        conn = get_db_connection()
        cursor = conn.cursor()
        cursor.execute("""
            SELECT COALESCE(SUM(pfr.amount_kg), 0) as total_kg, COUNT(*) as records_count,
                COUNT(DISTINCT pfr.pig_id) as pigs_fed_count
            FROM pig_feeding_records pfr WHERE DATE(pfr.feeding_datetime) = %s
        """, (date_str,))
        row = cursor.fetchone()
        total_kg = float(row['total_kg'] or 0)
        records_count = row['records_count'] or 0
        pigs_fed_count = row['pigs_fed_count'] or 0
        cursor.execute("""
            SELECT f.feed_name, f.feed_type, SUM(pfr.amount_kg) as total_kg, COUNT(DISTINCT pfr.pig_id) as pig_count
            FROM pig_feeding_records pfr JOIN feeds f ON pfr.feed_id = f.id
            WHERE DATE(pfr.feeding_datetime) = %s
            GROUP BY pfr.feed_id, f.feed_name, f.feed_type ORDER BY total_kg DESC
        """, (date_str,))
        by_feed = [{'feed_name': r['feed_name'], 'feed_type': r['feed_type'], 'total_kg': float(r['total_kg'] or 0), 'pig_count': r['pig_count'] or 0} for r in cursor.fetchall()]
        cursor.close()
        conn.close()
        return jsonify({'success': True, 'date': date_str, 'total_kg': round(total_kg, 2), 'records_count': records_count, 'pigs_fed_count': pigs_fed_count, 'by_feed': by_feed})
    except Exception as e:
        import traceback
        traceback.print_exc()
        return jsonify({'success': False, 'message': str(e)}), 500


@app.route('/api/pig-feeding/analytics', methods=['GET'])
def get_pig_feeding_analytics():
    """Pig feeding record analytics. Optional: date_from, date_to."""
    if 'employee_id' not in session:
        return jsonify({'success': False, 'message': 'Unauthorized'}), 401
    try:
        date_from = request.args.get('date_from')
        date_to = request.args.get('date_to')
        conn = get_db_connection()
        cursor = conn.cursor()
        farm_id = _scoped_farm_id(cursor)
        where = "WHERE 1=1"
        params = []
        if date_from:
            where += " AND DATE(pfr.feeding_datetime) >= %s"
            params.append(date_from)
        if date_to:
            where += " AND DATE(pfr.feeding_datetime) <= %s"
            params.append(date_to)
        where += " AND pfr.farm_id = %s"
        params.append(farm_id)
        cursor.execute("""
            SELECT COALESCE(SUM(pfr.amount_kg), 0) as total_kg, COUNT(*) as records_count, COUNT(DISTINCT pfr.pig_id) as pigs_fed_count
            FROM pig_feeding_records pfr """ + where, params)
        row = cursor.fetchone()
        total_kg = float(row['total_kg'] or 0)
        records_count = row['records_count'] or 0
        pigs_fed_count = row['pigs_fed_count'] or 0
        cursor.execute("""
            SELECT f.id as feed_id, f.feed_name, SUM(pfr.amount_kg) as total_kg, COUNT(*) as record_count, COUNT(DISTINCT pfr.pig_id) as pig_count
            FROM pig_feeding_records pfr JOIN feeds f ON pfr.feed_id = f.id """ + where + """
            GROUP BY pfr.feed_id, f.id, f.feed_name ORDER BY total_kg DESC
        """, params)
        by_feed = [{'feed_id': r['feed_id'], 'feed_name': r['feed_name'], 'total_kg': round(float(r['total_kg'] or 0), 2), 'record_count': r['record_count'] or 0, 'pig_count': r['pig_count'] or 0} for r in cursor.fetchall()]
        # Daily series: if a range is set, use only that range; else last 30 days
        if date_from and date_to:
            daily_where = "WHERE DATE(pfr.feeding_datetime) >= %s AND DATE(pfr.feeding_datetime) <= %s"
            daily_params = [date_from, date_to]
        elif date_from:
            daily_where = "WHERE DATE(pfr.feeding_datetime) >= %s"
            daily_params = [date_from]
        elif date_to:
            daily_where = "WHERE DATE(pfr.feeding_datetime) <= %s"
            daily_params = [date_to]
        else:
            daily_where = "WHERE pfr.feeding_datetime >= DATE_SUB(CURDATE(), INTERVAL 30 DAY)"
            daily_params = []
        daily_where += " AND pfr.farm_id = %s" if "WHERE" in daily_where else " WHERE pfr.farm_id = %s"
        daily_params.append(farm_id)
        cursor.execute("""
            SELECT DATE(pfr.feeding_datetime) as d, SUM(pfr.amount_kg) as total_kg, COUNT(*) as cnt
            FROM pig_feeding_records pfr """ + daily_where + """ GROUP BY DATE(pfr.feeding_datetime) ORDER BY d ASC
        """, daily_params)
        daily = [{'date': r['d'].isoformat() if r['d'] else None, 'total_kg': round(float(r['total_kg'] or 0), 2), 'record_count': r['cnt'] or 0} for r in cursor.fetchall()]
        cursor.close()
        conn.close()
        return jsonify({'success': True, 'total_kg': round(total_kg, 2), 'records_count': records_count, 'pigs_fed_count': pigs_fed_count, 'by_feed': by_feed, 'daily_totals': daily})
    except Exception as e:
        import traceback
        traceback.print_exc()
        return jsonify({'success': False, 'message': str(e)}), 500


def _analytics_as_of_date_from_request():
    """Reference calendar date for feed requirements / animal list (day, month, or range end). Defaults to today."""
    import calendar
    as_of = date.today()
    date_str = request.args.get('date')
    month_str = request.args.get('month')
    end_date = request.args.get('end_date')
    if date_str:
        try:
            return date.fromisoformat(date_str[:10])
        except ValueError:
            return as_of
    if month_str:
        try:
            parts = [p for p in month_str.split('-') if p]
            if len(parts) >= 2:
                y, m = int(parts[0]), int(parts[1])
                last = calendar.monthrange(y, m)[1]
                return date(y, m, last)
        except (ValueError, TypeError, IndexError):
            return as_of
    if end_date:
        try:
            return date.fromisoformat(end_date[:10])
        except ValueError:
            return as_of
    return as_of


@app.route('/api/pig-feeding/consumption-forecast', methods=['GET'])
def get_pig_feeding_consumption_forecast():
    """Projected pig feed consumption for a given range, based on feed_settings.

    Query params (one of):
      - range_type=day   + date=YYYY-MM-DD
      - range_type=period + date_from=YYYY-MM-DD & date_to=YYYY-MM-DD
      - range_type=month + month=YYYY-MM  (or year & month_num)
      - range_type=year  + year=YYYY

    Output:
      {
        success, range_type, date_from, date_to, days,
        animals_total,
        total_kg,
        by_feed:     [{feed_id?, feed_name, feed_type, total_kg, animal_count}],
        by_category: [{age_group_name, feed_type, feed_name, animal_count, daily_kg, total_kg}],
        by_day:      [{date, total_kg}]
      }
    """
    if 'employee_id' not in session:
        return jsonify({'success': False, 'message': 'Unauthorized'}), 401

    from datetime import date as date_type, timedelta
    import calendar as _cal

    def _parse_iso(v):
        try:
            return date_type.fromisoformat(v)
        except Exception:
            return None

    range_type = (request.args.get('range_type') or 'day').lower()
    today = date_type.today()

    if range_type == 'day':
        d = _parse_iso(request.args.get('date') or '') or today
        date_from = d
        date_to = d
    elif range_type == 'period':
        date_from = _parse_iso(request.args.get('date_from') or '') or today
        date_to   = _parse_iso(request.args.get('date_to')   or '') or date_from
        if date_to < date_from:
            date_from, date_to = date_to, date_from
    elif range_type == 'month':
        m = request.args.get('month') or today.strftime('%Y-%m')
        try:
            year, month = [int(p) for p in m.split('-')[:2]]
        except Exception:
            year, month = today.year, today.month
        last_day = _cal.monthrange(year, month)[1]
        date_from = date_type(year, month, 1)
        date_to   = date_type(year, month, last_day)
    elif range_type == 'year':
        try:
            year = int(request.args.get('year') or today.year)
        except Exception:
            year = today.year
        date_from = date_type(year, 1, 1)
        date_to   = date_type(year, 12, 31)
    else:
        return jsonify({'success': False, 'message': 'Invalid range_type'}), 400

    # Safety cap: never project more than ~2 years of daily ticks (saves compute).
    if (date_to - date_from).days > 366 * 2:
        date_to = date_from + timedelta(days=366 * 2)

    try:
        conn = get_db_connection()
        cursor = conn.cursor()

        # Active pigs with either birth_date or purchase_date for age computation.
        cursor.execute("""
            SELECT id, tag_id, breed, gender, birth_date, purchase_date, pig_source
            FROM pigs
            WHERE status = 'active'
        """)
        pigs = cursor.fetchall() or []

        # Pig feed settings, ordered by age range.
        cursor.execute("""
            SELECT id, age_group_name, start_age_days, end_age_days,
                   feed_amount_grams, feeding_times_per_day, feed_type
            FROM feed_settings
            WHERE status = 'active' AND animal_type = 'pig'
            ORDER BY start_age_days ASC
        """)
        settings = cursor.fetchall() or []

        # Feeds list (to map feed_type setting -> feed name/id).
        cursor.execute("""
            SELECT id, feed_name, feed_type, animal_type
            FROM feeds
            WHERE (animal_type = 'pig' OR animal_type = 'all')
        """)
        feeds = cursor.fetchall() or []
        cursor.close()
        conn.close()

        # Build feed lookup: accept the setting's feed_type as either a feed id
        # (stored as string) or a feed name / feed_type keyword.
        feed_by_id   = {int(f['id']): f for f in feeds}
        feed_by_name = {str(f.get('feed_name') or '').strip().lower(): f for f in feeds}
        feed_by_type = {str(f.get('feed_type') or '').strip().lower(): f for f in feeds}

        def _resolve_feed(ft):
            if ft is None:
                return None
            raw = str(ft).strip()
            if not raw:
                return None
            # Try integer id first.
            try:
                fid = int(raw)
                if fid in feed_by_id:
                    return feed_by_id[fid]
            except ValueError:
                pass
            low = raw.lower()
            return feed_by_name.get(low) or feed_by_type.get(low)

        # Compute the age-for-a-date for each pig lazily.
        def _origin(pig):
            if (pig.get('pig_source') or '').lower() == 'purchased' and pig.get('purchase_date'):
                return pig['purchase_date']
            return pig.get('birth_date') or pig.get('purchase_date')

        def _match_setting(age_days):
            if age_days is None:
                return None
            for s in settings:
                try:
                    start = int(s['start_age_days']); end = int(s['end_age_days'])
                except Exception:
                    continue
                if start <= age_days <= end:
                    return s
            return None

        days = (date_to - date_from).days + 1

        # Accumulators
        by_feed = {}       # feed_name -> {feed_id, feed_name, feed_type, total_kg, animals:set}
        by_category = {}   # setting_id -> {age_group_name, feed_name, feed_type, animals:set, daily_kg, total_kg}
        by_day_map = {d: 0.0 for d in (date_from + timedelta(days=i) for i in range(days))}

        animals_counted = set()

        for pig in pigs:
            origin = _origin(pig)
            if not origin:
                continue
            for i in range(days):
                day = date_from + timedelta(days=i)
                if day < origin:
                    continue
                age_days = (day - origin).days
                setting = _match_setting(age_days)
                if not setting:
                    continue
                try:
                    grams = float(setting.get('feed_amount_grams') or 0)
                    times = int(setting.get('feeding_times_per_day') or 0)
                except Exception:
                    continue
                if grams <= 0 or times <= 0:
                    continue
                daily_kg = grams * times / 1000.0

                # Resolve feed (for display + breakdown)
                feed_row = _resolve_feed(setting.get('feed_type'))
                feed_name = (feed_row or {}).get('feed_name') or (setting.get('feed_type') or 'Unassigned feed')
                feed_type = (feed_row or {}).get('feed_type') or None
                feed_id   = (feed_row or {}).get('id')

                # Accumulate totals
                by_day_map[day] = by_day_map.get(day, 0.0) + daily_kg

                bf = by_feed.setdefault(feed_name, {
                    'feed_id': feed_id, 'feed_name': feed_name, 'feed_type': feed_type,
                    'total_kg': 0.0, '_animals': set()
                })
                bf['total_kg'] += daily_kg
                bf['_animals'].add(pig['id'])

                cat_key = setting['id']
                bc = by_category.setdefault(cat_key, {
                    'age_group_name': setting.get('age_group_name') or 'Category',
                    'start_age_days': setting.get('start_age_days'),
                    'end_age_days': setting.get('end_age_days'),
                    'feed_name': feed_name, 'feed_type': feed_type,
                    'daily_kg': daily_kg, 'total_kg': 0.0, '_animals': set()
                })
                bc['total_kg'] += daily_kg
                bc['_animals'].add(pig['id'])
                animals_counted.add(pig['id'])

        by_feed_list = sorted(
            [{
                'feed_id': v['feed_id'], 'feed_name': v['feed_name'], 'feed_type': v['feed_type'],
                'total_kg': round(v['total_kg'], 2), 'animal_count': len(v['_animals'])
            } for v in by_feed.values()],
            key=lambda x: -x['total_kg']
        )
        by_category_list = sorted(
            [{
                'age_group_name': v['age_group_name'],
                'start_age_days': v['start_age_days'],
                'end_age_days': v['end_age_days'],
                'feed_name': v['feed_name'], 'feed_type': v['feed_type'],
                'animal_count': len(v['_animals']),
                'daily_kg': round(v['daily_kg'], 3),
                'total_kg': round(v['total_kg'], 2)
            } for v in by_category.values()],
            key=lambda x: (x.get('start_age_days') or 0)
        )
        by_day_list = [{'date': d.isoformat(), 'total_kg': round(kg, 2)} for d, kg in by_day_map.items()]
        total_kg = round(sum(v['total_kg'] for v in by_feed.values()), 2)

        return jsonify({
            'success': True,
            'range_type': range_type,
            'date_from': date_from.isoformat(),
            'date_to': date_to.isoformat(),
            'days': days,
            'animals_total': len(animals_counted),
            'active_pigs': len(pigs),
            'total_kg': total_kg,
            'by_feed': by_feed_list,
            'by_category': by_category_list,
            'by_day': by_day_list
        })
    except Exception as e:
        import traceback
        traceback.print_exc()
        return jsonify({'success': False, 'message': str(e)}), 500


@app.route('/api/pig-feeding/record', methods=['POST'])
def record_pig_feeding():
    """Record feeding for one or more pigs. entries: list of {pig_id, feed_id, amount_kg}."""
    if 'employee_id' not in session:
        return jsonify({'success': False, 'message': 'Unauthorized'}), 401
    try:
        # Accept both JSON fetch and normal form posts
        if request.is_json:
            data = request.get_json(silent=True) or {}
        else:
            data = request.form.to_dict() or {}
        entries = data.get('entries', [])
        feeding_datetime = data.get('feeding_datetime')
        notes = data.get('notes', '')
        if not entries:
            return jsonify({'success': False, 'message': 'entries (pig_id, feed_id, amount_kg) required'}), 400
        from datetime import datetime
        from collections import defaultdict
        now = datetime.now()
        if feeding_datetime:
            try:
                if isinstance(feeding_datetime, str) and 'T' in feeding_datetime:
                    feeding_datetime = datetime.fromisoformat(feeding_datetime.replace('Z', '+00:00')).replace(tzinfo=None)
                else:
                    feeding_datetime = datetime.strptime(str(feeding_datetime)[:19], '%Y-%m-%d %H:%M:%S')
            except Exception:
                feeding_datetime = now
        else:
            feeding_datetime = now
        valid_entries = []
        for e in entries:
            pid = e.get('pig_id')
            fid = e.get('feed_id')
            amt = float(e.get('amount_kg', 0) or 0)
            if pid and fid and amt > 0:
                valid_entries.append({'pig_id': pid, 'feed_id': int(fid), 'amount_kg': amt, 'pig_tag_id': e.get('pig_tag_id') or e.get('tag_id')})
        if not valid_entries:
            return jsonify({'success': False, 'message': 'At least one entry with pig_id, feed_id and amount_kg > 0 required'}), 400
        conn = get_db_connection()
        cursor = conn.cursor()
        farm_id = _default_farm_id(cursor)
        transaction_date = feeding_datetime.date()
        feed_stock_ids = {}
        by_feed = defaultdict(list)
        for e in valid_entries:
            by_feed[e['feed_id']].append(e)
        for feed_id, group in by_feed.items():
            cursor.execute("SELECT id, feed_name, unit_of_measure FROM feeds WHERE id = %s AND status = 'active'", (feed_id,))
            feed = cursor.fetchone()
            if not feed:
                continue
            total_kg = sum(x['amount_kg'] for x in group)
            unit = feed['unit_of_measure'] or 'kg'
            quantity = total_kg
            if unit == 'g':
                quantity = total_kg * 1000
            elif unit == 'ton':
                quantity = total_kg / 1000
            elif unit == 'bag':
                quantity = total_kg / 50
            pig_summary = [f"{x.get('pig_tag_id') or x['pig_id']} {x['amount_kg']}kg" for x in group]
            notes_stock = 'Pig feeding: ' + ', '.join(pig_summary) if pig_summary else notes or 'Pig feeding'
            cursor.execute("""
                INSERT INTO feed_stock (feed_id, farm_id, transaction_type, quantity, unit_of_measure, transaction_date, notes, created_by)
                VALUES (%s, %s, 'stock_out', %s, %s, %s, %s, %s)
            """, (feed_id, farm_id, quantity, unit, transaction_date, notes_stock, session['employee_id']))
            feed_stock_ids[feed_id] = cursor.lastrowid
        for e in valid_entries:
            pid = e['pig_id']
            feed_id = e['feed_id']
            amt = e['amount_kg']
            feed_stock_id = feed_stock_ids.get(feed_id)
            if not feed_stock_id:
                continue
            cursor.execute("SELECT id, tag_id FROM pigs WHERE id = %s AND status = 'active'", (pid,))
            pig = cursor.fetchone()
            if not pig:
                continue
            cursor.execute("""
                INSERT INTO pig_feeding_records (pig_id, feed_id, farm_id, amount_kg, feeding_datetime, notes, feed_stock_id, created_by)
                VALUES (%s, %s, %s, %s, %s, %s, %s, %s)
            """, (pid, feed_id, farm_id, amt, feeding_datetime, notes, feed_stock_id, session['employee_id']))
        total_kg = sum(e['amount_kg'] for e in valid_entries)
        conn.commit()
        cursor.close()
        conn.close()
        return jsonify({'success': True, 'message': f'Recorded feeding for {len(valid_entries)} pig(s), total {total_kg:.2f} kg. Stock updated.', 'total_kg': total_kg})
    except Exception as e:
        import traceback
        traceback.print_exc()
        return jsonify({'success': False, 'message': str(e)}), 500


# ----- Chicken feeding APIs -----
@app.route('/api/chicken-feeding/chickens', methods=['GET'])
def get_chickens_for_feeding():
    """List active chickens for feeding (id, chicken_id, age_days)."""
    if 'employee_id' not in session:
        return jsonify({'success': False, 'message': 'Unauthorized'}), 401
    try:
        conn = get_db_connection()
        cursor = conn.cursor()
        cursor.execute("""
            SELECT id, chicken_id, batch_name, chicken_type, breed_name, gender, hatch_date, age_days
            FROM chickens
            WHERE current_status = 'active'
            ORDER BY chicken_id ASC
        """)
        rows = cursor.fetchall()
        cursor.close()
        conn.close()
        chickens = []
        for r in rows:
            age_days = None
            if r.get('age_days') is not None:
                try:
                    age_days = int(r['age_days'])
                except (TypeError, ValueError):
                    pass
            chickens.append({
                'id': r['id'],
                'chicken_id': r['chicken_id'],
                'name': r['chicken_id'],
                'batch_name': r['batch_name'],
                'chicken_type': r['chicken_type'],
                'breed_name': r['breed_name'],
                'gender': r['gender'],
                'age_days': age_days
            })
        return jsonify({'success': True, 'chickens': chickens})
    except Exception as e:
        return jsonify({'success': False, 'message': str(e)}), 500


@app.route('/api/chicken-feeding/records', methods=['GET'])
def get_chicken_feeding_records():
    """List chicken feeding records. Optional: date, date_from, date_to."""
    if 'employee_id' not in session:
        return jsonify({'success': False, 'message': 'Unauthorized'}), 401
    try:
        limit = min(request.args.get('limit', 100, type=int), 500)
        date = request.args.get('date')
        date_from = request.args.get('date_from')
        date_to = request.args.get('date_to')
        where_clause = "WHERE 1=1"
        params = []
        if date:
            where_clause += " AND DATE(cfr.feeding_datetime) = %s"
            params.append(date)
        if date_from:
            where_clause += " AND DATE(cfr.feeding_datetime) >= %s"
            params.append(date_from)
        if date_to:
            where_clause += " AND DATE(cfr.feeding_datetime) <= %s"
            params.append(date_to)
        params.append(limit)
        conn = get_db_connection()
        cursor = conn.cursor()
        cursor.execute("""
            SELECT cfr.id, cfr.chicken_id, cfr.feed_id, cfr.amount_kg, cfr.feeding_datetime, cfr.notes,
                c.chicken_id as bird_id, c.batch_name, f.feed_name, f.feed_type, e.full_name as created_by_name
            FROM chicken_feeding_records cfr
            JOIN chickens c ON cfr.chicken_id = c.id
            JOIN feeds f ON cfr.feed_id = f.id
            JOIN employees e ON cfr.created_by = e.id
            """ + where_clause + """
            ORDER BY cfr.feeding_datetime DESC
            LIMIT %s
        """, params)
        rows = cursor.fetchall()
        cursor.close()
        conn.close()
        records = []
        for r in rows:
            records.append({
                'id': r['id'], 'chicken_id': r['chicken_id'], 'chicken_display': r['bird_id'] or str(r['chicken_id']), 'chicken_name': r['bird_id'] or str(r['chicken_id']),
                'feed_id': r['feed_id'], 'feed_name': r['feed_name'], 'feed_type': r['feed_type'],
                'amount_kg': float(r['amount_kg']),
                'feeding_datetime': r['feeding_datetime'].strftime('%Y-%m-%d %H:%M') if r['feeding_datetime'] else None,
                'notes': r['notes'], 'created_by_name': r['created_by_name']
            })
        return jsonify({'success': True, 'records': records})
    except Exception as e:
        import traceback
        traceback.print_exc()
        return jsonify({'success': False, 'message': str(e)}), 500


@app.route('/api/chicken-feeding/daily-summary', methods=['GET'])
def get_chicken_feeding_daily_summary():
    """Daily feeding summary for chickens. Query param: date=YYYY-MM-DD (default today)."""
    if 'employee_id' not in session:
        return jsonify({'success': False, 'message': 'Unauthorized'}), 401
    try:
        from datetime import date as date_type
        date_str = request.args.get('date')
        if date_str:
            try:
                target_date = date_type.fromisoformat(date_str)
            except ValueError:
                target_date = date_type.today()
        else:
            target_date = date_type.today()
        date_str = target_date.isoformat()
        conn = get_db_connection()
        cursor = conn.cursor()
        cursor.execute("""
            SELECT COALESCE(SUM(cfr.amount_kg), 0) as total_kg, COUNT(*) as records_count,
                COUNT(DISTINCT cfr.chicken_id) as chickens_fed_count
            FROM chicken_feeding_records cfr WHERE DATE(cfr.feeding_datetime) = %s
        """, (date_str,))
        row = cursor.fetchone()
        total_kg = float(row['total_kg'] or 0)
        records_count = row['records_count'] or 0
        chickens_fed_count = row['chickens_fed_count'] or 0
        cursor.execute("""
            SELECT f.feed_name, f.feed_type, SUM(cfr.amount_kg) as total_kg, COUNT(DISTINCT cfr.chicken_id) as chicken_count
            FROM chicken_feeding_records cfr JOIN feeds f ON cfr.feed_id = f.id
            WHERE DATE(cfr.feeding_datetime) = %s
            GROUP BY cfr.feed_id, f.feed_name, f.feed_type ORDER BY total_kg DESC
        """, (date_str,))
        by_feed = [{'feed_name': r['feed_name'], 'feed_type': r['feed_type'], 'total_kg': float(r['total_kg'] or 0), 'chicken_count': r['chicken_count'] or 0} for r in cursor.fetchall()]
        cursor.close()
        conn.close()
        return jsonify({'success': True, 'date': date_str, 'total_kg': round(total_kg, 2), 'records_count': records_count, 'chickens_fed_count': chickens_fed_count, 'by_feed': by_feed})
    except Exception as e:
        import traceback
        traceback.print_exc()
        return jsonify({'success': False, 'message': str(e)}), 500


@app.route('/api/chicken-feeding/analytics', methods=['GET'])
def get_chicken_feeding_analytics():
    """Chicken feeding record analytics. Optional: date_from, date_to."""
    if 'employee_id' not in session:
        return jsonify({'success': False, 'message': 'Unauthorized'}), 401
    try:
        date_from = request.args.get('date_from')
        date_to = request.args.get('date_to')
        conn = get_db_connection()
        cursor = conn.cursor()
        where = "WHERE 1=1"
        params = []
        if date_from:
            where += " AND DATE(cfr.feeding_datetime) >= %s"
            params.append(date_from)
        if date_to:
            where += " AND DATE(cfr.feeding_datetime) <= %s"
            params.append(date_to)
        cursor.execute("""
            SELECT COALESCE(SUM(cfr.amount_kg), 0) as total_kg, COUNT(*) as records_count, COUNT(DISTINCT cfr.chicken_id) as chickens_fed_count
            FROM chicken_feeding_records cfr """ + where, params)
        row = cursor.fetchone()
        total_kg = float(row['total_kg'] or 0)
        records_count = row['records_count'] or 0
        chickens_fed_count = row['chickens_fed_count'] or 0
        cursor.execute("""
            SELECT f.id as feed_id, f.feed_name, SUM(cfr.amount_kg) as total_kg, COUNT(*) as record_count, COUNT(DISTINCT cfr.chicken_id) as chicken_count
            FROM chicken_feeding_records cfr JOIN feeds f ON cfr.feed_id = f.id """ + where + """
            GROUP BY cfr.feed_id, f.id, f.feed_name ORDER BY total_kg DESC
        """, params)
        by_feed = [{'feed_id': r['feed_id'], 'feed_name': r['feed_name'], 'total_kg': round(float(r['total_kg'] or 0), 2), 'record_count': r['record_count'] or 0, 'chicken_count': r['chicken_count'] or 0} for r in cursor.fetchall()]
        daily_where = "WHERE cfr.feeding_datetime >= DATE_SUB(CURDATE(), INTERVAL 30 DAY)"
        daily_params = []
        if date_from:
            daily_where += " AND DATE(cfr.feeding_datetime) >= %s"
            daily_params.append(date_from)
        if date_to:
            daily_where += " AND DATE(cfr.feeding_datetime) <= %s"
            daily_params.append(date_to)
        cursor.execute("""
            SELECT DATE(cfr.feeding_datetime) as d, SUM(cfr.amount_kg) as total_kg, COUNT(*) as cnt
            FROM chicken_feeding_records cfr """ + daily_where + """ GROUP BY DATE(cfr.feeding_datetime) ORDER BY d ASC
        """, daily_params)
        daily = [{'date': r['d'].isoformat() if r['d'] else None, 'total_kg': round(float(r['total_kg'] or 0), 2), 'record_count': r['cnt'] or 0} for r in cursor.fetchall()]
        cursor.close()
        conn.close()
        return jsonify({'success': True, 'total_kg': round(total_kg, 2), 'records_count': records_count, 'chickens_fed_count': chickens_fed_count, 'by_feed': by_feed, 'daily_totals': daily})
    except Exception as e:
        import traceback
        traceback.print_exc()
        return jsonify({'success': False, 'message': str(e)}), 500


@app.route('/api/chicken-feeding/record', methods=['POST'])
def record_chicken_feeding():
    """Record feeding for one or more chickens. entries: list of {chicken_id, feed_id, amount_kg} (chicken_id = chickens.id)."""
    if 'employee_id' not in session:
        return jsonify({'success': False, 'message': 'Unauthorized'}), 401
    try:
        # Accept both JSON fetch and normal form posts
        if request.is_json:
            data = request.get_json(silent=True) or {}
        else:
            data = request.form.to_dict() or {}
        entries = data.get('entries', [])
        feeding_datetime = data.get('feeding_datetime')
        notes = data.get('notes', '')
        if not entries:
            return jsonify({'success': False, 'message': 'entries (chicken_id, feed_id, amount_kg) required'}), 400
        from datetime import datetime
        from collections import defaultdict
        now = datetime.now()
        if feeding_datetime:
            try:
                if isinstance(feeding_datetime, str) and 'T' in feeding_datetime:
                    feeding_datetime = datetime.fromisoformat(feeding_datetime.replace('Z', '+00:00')).replace(tzinfo=None)
                else:
                    feeding_datetime = datetime.strptime(str(feeding_datetime)[:19], '%Y-%m-%d %H:%M:%S')
            except Exception:
                feeding_datetime = now
        else:
            feeding_datetime = now
        valid_entries = []
        for e in entries:
            cid = e.get('chicken_id')  # chickens.id
            fid = e.get('feed_id')
            amt = float(e.get('amount_kg', 0) or 0)
            if cid and fid and amt > 0:
                valid_entries.append({'chicken_id': cid, 'feed_id': int(fid), 'amount_kg': amt, 'chicken_display': e.get('chicken_display') or e.get('chicken_id')})
        if not valid_entries:
            return jsonify({'success': False, 'message': 'At least one entry with chicken_id, feed_id and amount_kg > 0 required'}), 400
        conn = get_db_connection()
        cursor = conn.cursor()
        farm_id = _default_farm_id(cursor)
        transaction_date = feeding_datetime.date()
        feed_stock_ids = {}
        by_feed = defaultdict(list)
        for e in valid_entries:
            by_feed[e['feed_id']].append(e)
        for feed_id, group in by_feed.items():
            cursor.execute("SELECT id, feed_name, unit_of_measure FROM feeds WHERE id = %s AND status = 'active'", (feed_id,))
            feed = cursor.fetchone()
            if not feed:
                continue
            total_kg = sum(x['amount_kg'] for x in group)
            unit = feed['unit_of_measure'] or 'kg'
            quantity = total_kg
            if unit == 'g':
                quantity = total_kg * 1000
            elif unit == 'ton':
                quantity = total_kg / 1000
            elif unit == 'bag':
                quantity = total_kg / 50
            chicken_summary = [f"{x.get('chicken_display') or x['chicken_id']} {x['amount_kg']}kg" for x in group]
            notes_stock = 'Chicken feeding: ' + ', '.join(chicken_summary) if chicken_summary else notes or 'Chicken feeding'
            cursor.execute("""
                INSERT INTO feed_stock (feed_id, farm_id, transaction_type, quantity, unit_of_measure, transaction_date, notes, created_by)
                VALUES (%s, %s, 'stock_out', %s, %s, %s, %s, %s)
            """, (feed_id, farm_id, quantity, unit, transaction_date, notes_stock, session['employee_id']))
            feed_stock_ids[feed_id] = cursor.lastrowid
        for e in valid_entries:
            cid = e['chicken_id']
            feed_id = e['feed_id']
            amt = e['amount_kg']
            feed_stock_id = feed_stock_ids.get(feed_id)
            if not feed_stock_id:
                continue
            cursor.execute("SELECT id, chicken_id FROM chickens WHERE id = %s AND current_status = 'active'", (cid,))
            chicken = cursor.fetchone()
            if not chicken:
                continue
            cursor.execute("""
                INSERT INTO chicken_feeding_records (chicken_id, feed_id, farm_id, amount_kg, feeding_datetime, notes, feed_stock_id, created_by)
                VALUES (%s, %s, %s, %s, %s, %s, %s, %s)
            """, (cid, feed_id, farm_id, amt, feeding_datetime, notes, feed_stock_id, session['employee_id']))
        total_kg = sum(e['amount_kg'] for e in valid_entries)
        conn.commit()
        cursor.close()
        conn.close()
        return jsonify({'success': True, 'message': f'Recorded feeding for {len(valid_entries)} chicken(s), total {total_kg:.2f} kg. Stock updated.', 'total_kg': total_kg})
    except Exception as e:
        import traceback
        traceback.print_exc()
        return jsonify({'success': False, 'message': str(e)}), 500


