@app.route('/api/feed/register', methods=['POST'])
def register_feed():
    """Register a new feed type"""
    if 'employee_id' not in session:
        return jsonify({'success': False, 'message': 'Unauthorized'}), 401
    
    try:
        # Accept both JSON (fetch) and form-encoded submissions (native form post)
        if request.is_json:
            data = request.get_json(silent=True) or {}
        else:
            data = request.form.to_dict() or {}
        
        # Validate required fields
        feed_name = data.get('feed_name', '').strip()
        feed_type = data.get('feed_type', '').strip()
        unit_of_measure = data.get('unit_of_measure', '').strip()
        animal_type = (data.get('animal_type') or '').strip().lower()
        notes = data.get('notes', '').strip()
        
        if not feed_name:
            return jsonify({'success': False, 'message': 'Feed name is required'})
        
        if not feed_type:
            return jsonify({'success': False, 'message': 'Feed type is required'})
        
        if not unit_of_measure:
            return jsonify({'success': False, 'message': 'Unit of measure is required'})
        
        if animal_type not in ('pig', 'cow', 'chicken'):
            return jsonify({'success': False, 'message': 'Animal type is required. Select Pig, Cow, or Chicken.'})
        
        # Normalize feed_type so users can add custom types
        feed_type = feed_type.lower().strip().replace(' ', '_')
        if not feed_type:
            return jsonify({'success': False, 'message': 'Feed type is required'})
        if len(feed_type) > 100:
            return jsonify({'success': False, 'message': 'Feed type is too long (max 100 characters)'})
        
        # Validate unit_of_measure enum
        valid_units = ['kg', 'g', 'ton', 'bag', 'liter', 'ml']
        if unit_of_measure not in valid_units:
            return jsonify({'success': False, 'message': 'Invalid unit of measure'})
        
        conn = get_db_connection()
        cursor = conn.cursor()
        
        # Check if feed name already exists for this animal type
        cursor.execute(
            "SELECT id FROM feeds WHERE feed_name = %s AND status = 'active' AND COALESCE(animal_type, 'pig') = %s",
            (feed_name, animal_type)
        )
        if cursor.fetchone():
            cursor.close()
            conn.close()
            return jsonify({'success': False, 'message': f'A feed with this name already exists for {animal_type.title()}.'})
        
        # Insert new feed (linked to animal type)
        cursor.execute("""
            INSERT INTO feeds (feed_name, feed_type, unit_of_measure, animal_type, notes, created_by)
            VALUES (%s, %s, %s, %s, %s, %s)
        """, (feed_name, feed_type, unit_of_measure, animal_type, notes if notes else None, session['employee_id']))
        
        feed_id = cursor.lastrowid
        
        # Log activity
        log_activity(session['employee_id'], 'FEED_REGISTRATION',
                    f'New feed "{feed_name}" registered for {animal_type} (Type: {feed_type}, Unit: {unit_of_measure})')
        
        conn.commit()
        cursor.close()
        conn.close()
        
        return jsonify({
            'success': True,
            'message': 'Feed registered successfully',
            'feed_id': feed_id
        })
        
    except Exception as e:
        print(f"Error registering feed: {str(e)}")
        return jsonify({'success': False, 'message': f'Failed to register feed: {str(e)}'}), 500


@app.route('/api/feed/update', methods=['POST', 'PUT'])
def update_feed():
    """Update an existing feed (feed_id required)."""
    if 'employee_id' not in session:
        return jsonify({'success': False, 'message': 'Unauthorized'}), 401
    try:
        # Accept both JSON (fetch) and form-encoded submissions (native form post)
        if request.is_json:
            data = request.get_json(silent=True) or {}
        else:
            data = request.form.to_dict() or {}
        feed_id = data.get('feed_id') or data.get('id')
        if not feed_id:
            return jsonify({'success': False, 'message': 'Feed ID is required'})
        try:
            feed_id = int(feed_id)
        except (TypeError, ValueError):
            return jsonify({'success': False, 'message': 'Invalid feed ID'})
        feed_name = (data.get('feed_name') or '').strip()
        feed_type = (data.get('feed_type') or '').strip()
        unit_of_measure = (data.get('unit_of_measure') or '').strip()
        animal_type = (data.get('animal_type') or '').strip().lower()
        notes = (data.get('notes') or '').strip()
        if not feed_name:
            return jsonify({'success': False, 'message': 'Feed name is required'})
        if not feed_type:
            return jsonify({'success': False, 'message': 'Feed type is required'})
        if not unit_of_measure:
            return jsonify({'success': False, 'message': 'Unit of measure is required'})
        if animal_type and animal_type not in ('pig', 'cow', 'chicken'):
            animal_type = None
        feed_type = feed_type.lower().strip().replace(' ', '_')
        if not feed_type:
            return jsonify({'success': False, 'message': 'Feed type is required'})
        if len(feed_type) > 100:
            return jsonify({'success': False, 'message': 'Feed type is too long (max 100 characters)'})
        valid_units = ['kg', 'g', 'ton', 'bag', 'liter', 'ml']
        if unit_of_measure not in valid_units:
            return jsonify({'success': False, 'message': 'Invalid unit of measure'})
        conn = get_db_connection()
        cursor = conn.cursor()
        cursor.execute("SELECT id, feed_name, animal_type FROM feeds WHERE id = %s AND status = 'active'", (feed_id,))
        row = cursor.fetchone()
        if not row:
            cursor.close()
            conn.close()
            return jsonify({'success': False, 'message': 'Feed not found or inactive'})
        at = animal_type or (row.get('animal_type') or 'pig')
        cursor.execute(
            "SELECT id FROM feeds WHERE feed_name = %s AND status = 'active' AND id != %s AND COALESCE(animal_type, 'pig') = %s",
            (feed_name, feed_id, at)
        )
        if cursor.fetchone():
            cursor.close()
            conn.close()
            return jsonify({'success': False, 'message': f'A feed with this name already exists for {at.title()}.'})
        cursor.execute("""
            UPDATE feeds SET feed_name = %s, feed_type = %s, unit_of_measure = %s, notes = %s
            WHERE id = %s AND status = 'active'
        """, (feed_name, feed_type, unit_of_measure, notes if notes else None, feed_id))
        if animal_type:
            try:
                cursor.execute("UPDATE feeds SET animal_type = %s WHERE id = %s AND status = 'active'", (animal_type, feed_id))
            except Exception:
                pass
        log_activity(session['employee_id'], 'FEED_UPDATE', f'Feed "{feed_name}" (id={feed_id}) updated')
        conn.commit()
        cursor.close()
        conn.close()
        return jsonify({'success': True, 'message': 'Feed updated successfully'})
    except Exception as e:
        print(f"Error updating feed: {str(e)}")
        return jsonify({'success': False, 'message': str(e)}), 500


@app.route('/api/feed/delete', methods=['POST', 'DELETE'])
def delete_feed():
    """Hard-delete a feed and related records."""
    if 'employee_id' not in session:
        return jsonify({'success': False, 'message': 'Unauthorized'}), 401
    try:
        # Accept both JSON and form-encoded payloads
        if request.is_json:
            data = request.get_json(silent=True) or {}
        else:
            data = request.form.to_dict() or {}
        feed_id = data.get('feed_id') or data.get('id')
        if not feed_id:
            return jsonify({'success': False, 'message': 'Feed ID is required'})
        try:
            feed_id = int(feed_id)
        except (TypeError, ValueError):
            return jsonify({'success': False, 'message': 'Invalid feed ID'})
        conn = get_db_connection()
        cursor = conn.cursor()
        cursor.execute("SELECT id, feed_name, status FROM feeds WHERE id = %s", (feed_id,))
        row = cursor.fetchone()
        if not row:
            cursor.close()
            conn.close()
            return jsonify({'success': False, 'message': 'Feed not found'})

        # Remove dependent rows first to satisfy FK constraints, then delete from feeds.
        cursor.execute("DELETE FROM pig_feeding_records WHERE feed_id = %s", (feed_id,))
        cursor.execute("DELETE FROM cow_feeding_records WHERE feed_id = %s", (feed_id,))
        cursor.execute("DELETE FROM chicken_feeding_records WHERE feed_id = %s", (feed_id,))
        cursor.execute("DELETE FROM feed_stock WHERE feed_id = %s", (feed_id,))
        cursor.execute("DELETE FROM feeds WHERE id = %s", (feed_id,))

        log_activity(session['employee_id'], 'FEED_DELETE', f'Feed "{row["feed_name"]}" (id={feed_id}) permanently deleted')
        conn.commit()
        cursor.close()
        conn.close()
        return jsonify({'success': True, 'message': 'Feed deleted permanently'})
    except Exception as e:
        print(f"Error deleting feed: {str(e)}")
        return jsonify({'success': False, 'message': str(e)}), 500


@app.route('/api/feed/list', methods=['GET'])
def get_feeds_list():
    """Get list of feeds. Optional: animal_type=pig|cow|chicken, include_inactive=1."""
    if 'employee_id' not in session:
        return jsonify({'success': False, 'message': 'Unauthorized'}), 401
    
    try:
        animal_type = request.args.get('animal_type', '').strip().lower()
        include_inactive = request.args.get('include_inactive', '').strip().lower() in ('1', 'true', 'yes')
        if animal_type and animal_type not in ('pig', 'cow', 'chicken'):
            animal_type = None
        
        conn = get_db_connection()
        cursor = conn.cursor()
        
        sql = """
            SELECT id, feed_name, feed_type, unit_of_measure, notes, status, created_at,
                   COALESCE(animal_type, 'pig') as animal_type
            FROM feeds
            WHERE 1=1
        """
        params = []
        if not include_inactive:
            sql += " AND status = 'active'"
        if animal_type:
            sql += " AND animal_type = %s"
            params.append(animal_type)
        sql += " ORDER BY feed_name ASC"
        cursor.execute(sql, params or None)
        
        feeds = []
        for row in cursor.fetchall():
            feeds.append({
                'id': row['id'],
                'feed_name': row['feed_name'],
                'feed_type': row['feed_type'],
                'unit_of_measure': row['unit_of_measure'],
                'animal_type': row.get('animal_type') or 'pig',
                'notes': row['notes'],
                'status': row['status'],
                'created_at': row['created_at'].strftime('%Y-%m-%d') if row['created_at'] else None
            })
        
        cursor.close()
        conn.close()
        
        return jsonify({'success': True, 'feeds': feeds})
        
    except Exception as e:
        print(f"Error fetching feeds: {str(e)}")
        import traceback
        traceback.print_exc()
        return jsonify({'success': False, 'message': f'Failed to fetch feeds: {str(e)}'}), 500

@app.route('/api/feed/list-with-stock', methods=['GET'])
def get_feeds_with_stock():
    """Get feeds with current stock (in kg). Optional: animal_type=pig|cow|chicken; include_inactive=1 for all registered feeds."""
    if 'employee_id' not in session:
        return jsonify({'success': False, 'message': 'Unauthorized'}), 401
    try:
        animal_type = request.args.get('animal_type', '').strip().lower()
        if animal_type and animal_type not in ('pig', 'cow', 'chicken'):
            animal_type = None
        include_inactive = request.args.get('include_inactive', '').strip().lower() in ('1', 'true', 'yes')
        
        conn = get_db_connection()
        cursor = conn.cursor()
        # Ensure feed_stock exists
        cursor.execute("""
            CREATE TABLE IF NOT EXISTS feed_stock (
                id INT AUTO_INCREMENT PRIMARY KEY,
                feed_id INT NOT NULL,
                farm_id INT NOT NULL,
                transaction_type ENUM('stock_in', 'stock_out') NOT NULL,
                quantity DECIMAL(10,2) NOT NULL,
                unit_of_measure ENUM('kg', 'g', 'ton', 'bag', 'liter', 'ml') NOT NULL,
                transaction_date DATE NOT NULL,
                cost DECIMAL(12,2) DEFAULT NULL,
                supplier VARCHAR(255),
                notes TEXT,
                created_by INT NOT NULL,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
                INDEX idx_feed_id (feed_id),
                INDEX idx_farm_id (farm_id),
                INDEX idx_transaction_date (transaction_date)
            )
        """)
        # Registered feeds (active only, or all if include_inactive)
        feeds_sql = """
            SELECT id, feed_name, feed_type, unit_of_measure, notes, status, created_at,
                   COALESCE(animal_type, 'pig') as animal_type
            FROM feeds
            WHERE 1=1
        """
        feeds_params = []
        if not include_inactive:
            feeds_sql += " AND status = 'active'"
        if animal_type:
            feeds_sql += " AND animal_type = %s"
            feeds_params.append(animal_type)
        feeds_sql += " ORDER BY feed_name ASC"
        cursor.execute(feeds_sql, feeds_params or None)
        feeds_rows = cursor.fetchall()
        # Current stock per feed (kg) — all transactions, any feed (inactive feeds may still have stock history)
        cursor.execute("""
            SELECT
                fs.feed_id,
                fs.transaction_type,
                SUM(CASE
                    WHEN fs.unit_of_measure = 'kg' THEN fs.quantity
                    WHEN fs.unit_of_measure = 'g' THEN fs.quantity / 1000
                    WHEN fs.unit_of_measure = 'ton' THEN fs.quantity * 1000
                    WHEN fs.unit_of_measure = 'bag' THEN fs.quantity * 50
                    ELSE fs.quantity
                END) as quantity_kg
            FROM feed_stock fs
            GROUP BY fs.feed_id, fs.transaction_type
        """)
        stock_rows = cursor.fetchall()
        stock_by_feed = {}
        for row in stock_rows:
            fid = row['feed_id']
            qty = float(row['quantity_kg'] or 0)
            if fid not in stock_by_feed:
                stock_by_feed[fid] = 0.0
            if row['transaction_type'] == 'stock_in':
                stock_by_feed[fid] += qty
            else:
                stock_by_feed[fid] -= qty
        feeds = []
        for row in feeds_rows:
            fid = row['id']
            feeds.append({
                'id': row['id'],
                'feed_name': row['feed_name'],
                'feed_type': row['feed_type'],
                'unit_of_measure': row['unit_of_measure'],
                'animal_type': row.get('animal_type') or 'pig',
                'notes': row['notes'],
                'status': row.get('status') or 'active',
                'current_stock_kg': round(stock_by_feed.get(fid, 0), 2),
                'created_at': row['created_at'].strftime('%Y-%m-%d') if row['created_at'] else None
            })
        cursor.close()
        conn.close()
        return jsonify({'success': True, 'feeds': feeds})
    except Exception as e:
        print(f"Error fetching feeds with stock: {str(e)}")
        import traceback
        traceback.print_exc()
        return jsonify({'success': False, 'message': str(e)}), 500

