@app.route('/api/feed/stock/transaction', methods=['POST'])
def feed_stock_transaction():
    """Record stock in or stock out transaction"""
    if 'employee_id' not in session:
        return jsonify({'success': False, 'message': 'Unauthorized'}), 401
    
    try:
        data = request.get_json()
        
        # Validate required fields (farm is always the active default site)
        feed_id = data.get('feed_id')
        transaction_type = data.get('transaction_type')
        quantity = data.get('quantity')
        unit_of_measure = data.get('unit_of_measure')
        transaction_date = data.get('transaction_date')
        cost = data.get('cost')
        supplier = data.get('supplier', '').strip()
        notes = data.get('notes', '').strip()
        
        if not feed_id or not transaction_type or not quantity or not unit_of_measure or not transaction_date:
            return jsonify({'success': False, 'message': 'All required fields must be filled'})
        
        # Cost is required for stock_in transactions
        if transaction_type == 'stock_in':
            if cost is None or cost == '':
                return jsonify({'success': False, 'message': 'Feed cost is required for stock in transactions'})
            try:
                cost = float(cost)
                if cost < 0:
                    return jsonify({'success': False, 'message': 'Cost must be greater than or equal to 0'})
            except (ValueError, TypeError):
                return jsonify({'success': False, 'message': 'Invalid cost value'})
        else:
            cost = None  # Stock out doesn't have cost
        
        if transaction_type not in ['stock_in', 'stock_out']:
            return jsonify({'success': False, 'message': 'Invalid transaction type'})
        
        try:
            quantity = float(quantity)
            if quantity <= 0:
                return jsonify({'success': False, 'message': 'Quantity must be greater than 0'})
        except (ValueError, TypeError):
            return jsonify({'success': False, 'message': 'Invalid quantity value'})
        
        valid_units = ['kg', 'g', 'ton', 'bag', 'liter', 'ml']
        if unit_of_measure not in valid_units:
            return jsonify({'success': False, 'message': 'Invalid unit of measure'})
        
        conn = get_db_connection()
        cursor = conn.cursor()
        farm_id = _scoped_farm_id(cursor)
        
        # Verify feed exists
        cursor.execute("SELECT id, feed_name, unit_of_measure FROM feeds WHERE id = %s AND status = 'active'", (feed_id,))
        feed = cursor.fetchone()
        if not feed:
            cursor.close()
            conn.close()
            return jsonify({'success': False, 'message': 'Feed not found or inactive'})
        
        # Verify farm exists
        cursor.execute("SELECT id, farm_name FROM farms WHERE id = %s AND status = 'active'", (farm_id,))
        farm = cursor.fetchone()
        if not farm:
            cursor.close()
            conn.close()
            return jsonify({'success': False, 'message': 'Farm not found or inactive'})
        
        # Convert supplier to uppercase if provided
        if supplier:
            supplier = supplier.upper().strip()
        
        # Insert stock transaction with audit trail
        cursor.execute("""
            INSERT INTO feed_stock (feed_id, farm_id, transaction_type, quantity, unit_of_measure, transaction_date, cost, supplier, notes, created_by)
            VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s)
        """, (feed_id, farm_id, transaction_type, quantity, unit_of_measure, transaction_date, cost if transaction_type == 'stock_in' else None, supplier if supplier else None, notes if notes else None, session['employee_id']))
        
        transaction_id = cursor.lastrowid
        
        # Get employee name for audit log
        cursor.execute("SELECT full_name FROM employees WHERE id = %s", (session['employee_id'],))
        employee = cursor.fetchone()
        employee_name = employee['full_name'] if employee else 'Unknown'
        
        # Log activity with detailed audit information
        action_type = 'FEED_STOCK_IN' if transaction_type == 'stock_in' else 'FEED_STOCK_OUT'
        feed_name = feed['feed_name'] if isinstance(feed, dict) else feed[1] if feed else 'Unknown'
        farm_name = farm['farm_name'] if isinstance(farm, dict) else farm[1] if farm else 'Unknown'
        log_activity(session['employee_id'], action_type, 
                    f'{transaction_type.replace("_", " ").title()}: {quantity} {unit_of_measure} of {feed_name} at {farm_name} by {employee_name} on {transaction_date}')
        
        conn.commit()
        cursor.close()
        conn.close()
        
        return jsonify({
            'success': True,
            'message': f'Stock {transaction_type.replace("_", " ")} recorded successfully',
            'transaction_id': transaction_id
        })
        
    except Exception as e:
        print(f"Error recording stock transaction: {str(e)}")
        return jsonify({'success': False, 'message': f'Failed to record transaction: {str(e)}'}), 500

@app.route('/api/feed/stock/transactions', methods=['GET'])
def get_feed_stock_transactions():
    """Get feed stock transactions. Optional animal_type=pig|cow|chicken to show only that animal's feeds."""
    if 'employee_id' not in session:
        return jsonify({'success': False, 'message': 'Unauthorized'}), 401
    
    try:
        limit = request.args.get('limit', 20, type=int)
        date = request.args.get('date')
        month = request.args.get('month')
        start_date = request.args.get('start_date')
        end_date = request.args.get('end_date')
        transaction_type = request.args.get('transaction_type')  # 'stock_in' or 'stock_out' to filter
        animal_type = (request.args.get('animal_type') or '').strip().lower()
        if animal_type and animal_type not in ('pig', 'cow', 'chicken'):
            animal_type = None
        limit = min(limit, 500)
        
        conn = get_db_connection()
        cursor = conn.cursor()
        farm_id = _scoped_farm_id(cursor)
        
        # Build WHERE clause for date, farm, and animal filtering
        where_clause = "WHERE 1=1"
        params = []
        
        if date:
            where_clause += " AND DATE(fs.transaction_date) = %s"
            params.append(date)
        elif month:
            where_clause += " AND DATE_FORMAT(fs.transaction_date, '%Y-%m') = %s"
            params.append(month)
        elif start_date and end_date:
            where_clause += " AND DATE(fs.transaction_date) BETWEEN %s AND %s"
            params.extend([start_date, end_date])
        
        where_clause += " AND fs.farm_id = %s"
        params.append(farm_id)
        
        if transaction_type in ('stock_in', 'stock_out'):
            where_clause += " AND fs.transaction_type = %s"
            params.append(transaction_type)
        
        if animal_type:
            where_clause += " AND COALESCE(f.animal_type, 'pig') = %s"
            params.append(animal_type)
        
        params.append(limit)
        
        cursor.execute(f"""
            SELECT 
                fs.id,
                fs.feed_id,
                fs.farm_id,
                fs.transaction_type,
                fs.quantity,
                fs.unit_of_measure,
                fs.transaction_date,
                fs.cost,
                fs.supplier,
                fs.notes,
                fs.created_at,
                fs.updated_at,
                f.feed_name,
                f.feed_type,
                fm.farm_name,
                fm.farm_location,
                e.full_name as created_by_name,
                e.employee_code as created_by_code,
                e.role as created_by_role
            FROM feed_stock fs
            INNER JOIN feeds f ON fs.feed_id = f.id
            INNER JOIN farms fm ON fs.farm_id = fm.id
            INNER JOIN employees e ON fs.created_by = e.id
            {where_clause}
            ORDER BY fs.created_at DESC
            LIMIT %s
        """, params)
        
        transactions = []
        for row in cursor.fetchall():
            transactions.append({
                'id': row['id'],
                'feed_id': row['feed_id'],
                'transaction_type': row['transaction_type'],
                'quantity': float(row['quantity']),
                'unit_of_measure': row['unit_of_measure'],
                'transaction_date': row['transaction_date'].strftime('%Y-%m-%d') if row['transaction_date'] else None,
                'cost': float(row['cost']) if row['cost'] else None,
                'supplier': row['supplier'],
                'notes': row['notes'],
                'created_at': row['created_at'].strftime('%Y-%m-%d %H:%M:%S') if row['created_at'] else None,
                'updated_at': row['updated_at'].strftime('%Y-%m-%d %H:%M:%S') if row['updated_at'] else None,
                'feed_name': row['feed_name'],
                'feed_type': row['feed_type'],
                'created_by_name': row['created_by_name'],
                'created_by_code': row['created_by_code'],
                'created_by_role': row['created_by_role']
            })
        
        cursor.close()
        conn.close()
        
        return jsonify({'success': True, 'transactions': transactions})
        
    except Exception as e:
        print(f"Error fetching transactions: {str(e)}")
        return jsonify({'success': False, 'message': f'Failed to fetch transactions: {str(e)}'}), 500

@app.route('/api/feed/stock/stats', methods=['GET'])
def get_feed_stock_stats():
    """Get feed stock statistics. Optional animal_type=pig|cow|chicken to filter by feed's animal."""
    if 'employee_id' not in session:
        return jsonify({'success': False, 'message': 'Unauthorized'}), 401
    
    try:
        date = request.args.get('date')
        month = request.args.get('month')
        start_date = request.args.get('start_date')
        end_date = request.args.get('end_date')
        animal_type = (request.args.get('animal_type') or '').strip().lower()
        if animal_type and animal_type not in ('pig', 'cow', 'chicken'):
            animal_type = None
        
        conn = get_db_connection()
        cursor = conn.cursor()
        farm_id = _scoped_farm_id(cursor)
        
        # Check if feed_stock table exists, create if not
        cursor.execute("""
            CREATE TABLE IF NOT EXISTS feed_stock (
                id INT AUTO_INCREMENT PRIMARY KEY,
                feed_id INT NOT NULL,
                farm_id INT NOT NULL,
                transaction_type ENUM('stock_in', 'stock_out') NOT NULL,
                quantity DECIMAL(10,2) NOT NULL,
                unit_of_measure ENUM('kg', 'g', 'ton', 'bag', 'liter', 'ml') NOT NULL,
                transaction_date DATE NOT NULL,
                cost DECIMAL(12,2) DEFAULT NULL,
                supplier VARCHAR(255),
                notes TEXT,
                created_by INT NOT NULL,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
                INDEX idx_feed_id (feed_id),
                INDEX idx_farm_id (farm_id),
                INDEX idx_transaction_type (transaction_type),
                INDEX idx_transaction_date (transaction_date)
            )
        """)
        
        # Add cost column if it doesn't exist (for existing tables)
        try:
            cursor.execute("ALTER TABLE feed_stock ADD COLUMN cost DECIMAL(12,2) DEFAULT NULL")
        except Exception as e:
            # Column might already exist, ignore error
            pass
        
        # Build WHERE clause for date, farm, and animal filtering (join feeds for animal_type)
        where_base = "fs.transaction_type = %s"
        where_extra = ""
        params_base = []
        params_extra = []
        
        if date:
            where_extra += " AND DATE(fs.transaction_date) = %s"
            params_extra.append(date)
        elif month:
            where_extra += " AND DATE_FORMAT(fs.transaction_date, '%%Y-%%m') = %s"
            params_extra.append(month)
        elif start_date and end_date:
            where_extra += " AND DATE(fs.transaction_date) BETWEEN %s AND %s"
            params_extra.extend([start_date, end_date])
        else:
            where_extra += " AND DATE(fs.transaction_date) = CURDATE()"
        
        where_extra += " AND fs.farm_id = %s"
        params_extra.append(farm_id)
        
        if animal_type:
            where_extra += " AND COALESCE(f.animal_type, 'pig') = %s"
            params_extra.append(animal_type)
        
        # Get stock in
        params_in = ['stock_in'] + params_extra
        cursor.execute(f"""
            SELECT COUNT(*) as count FROM feed_stock fs
            INNER JOIN feeds f ON fs.feed_id = f.id
            WHERE {where_base} {where_extra}
        """, params_in)
        result = cursor.fetchone()
        stock_in_today = result['count'] if result else 0
        
        # Get stock out
        params_out = ['stock_out'] + params_extra
        cursor.execute(f"""
            SELECT COUNT(*) as count FROM feed_stock fs
            INNER JOIN feeds f ON fs.feed_id = f.id
            WHERE {where_base} {where_extra}
        """, params_out)
        result = cursor.fetchone()
        stock_out_today = result['count'] if result else 0
        
        cursor.close()
        conn.close()
        
        return jsonify({
            'success': True,
            'stock_in_today': stock_in_today,
            'stock_out_today': stock_out_today
        })
        
    except Exception as e:
        print(f"Error fetching stock stats: {str(e)}")
        import traceback
        traceback.print_exc()
        return jsonify({'success': False, 'message': f'Failed to fetch stats: {str(e)}'}), 500

@app.route('/api/feed/stock/suppliers', methods=['GET'])
def get_suppliers_list():
    """Get list of all unique suppliers from feed_stock"""
    if 'employee_id' not in session:
        return jsonify({'success': False, 'message': 'Unauthorized'}), 401
    
    try:
        conn = get_db_connection()
        cursor = conn.cursor()
        
        # Check if feed_stock table exists
        cursor.execute("""
            CREATE TABLE IF NOT EXISTS feed_stock (
                id INT AUTO_INCREMENT PRIMARY KEY,
                feed_id INT NOT NULL,
                farm_id INT NOT NULL,
                transaction_type ENUM('stock_in', 'stock_out') NOT NULL,
                quantity DECIMAL(10,2) NOT NULL,
                unit_of_measure ENUM('kg', 'g', 'ton', 'bag', 'liter', 'ml') NOT NULL,
                transaction_date DATE NOT NULL,
                cost DECIMAL(12,2) DEFAULT NULL,
                supplier VARCHAR(255),
                notes TEXT,
                created_by INT NOT NULL,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
                INDEX idx_feed_id (feed_id),
                INDEX idx_farm_id (farm_id),
                INDEX idx_transaction_type (transaction_type),
                INDEX idx_transaction_date (transaction_date),
                INDEX idx_supplier (supplier)
            )
        """)
        
        # Add cost column if it doesn't exist (for existing tables)
        try:
            cursor.execute("ALTER TABLE feed_stock ADD COLUMN cost DECIMAL(12,2) DEFAULT NULL")
        except Exception as e:
            # Column might already exist, ignore error
            pass
        
        # Get unique suppliers (non-null, non-empty)
        cursor.execute("""
            SELECT DISTINCT supplier 
            FROM feed_stock 
            WHERE supplier IS NOT NULL 
            AND supplier != '' 
            AND supplier != ' '
            ORDER BY supplier ASC
        """)
        
        suppliers = []
        for row in cursor.fetchall():
            if row['supplier']:
                suppliers.append(row['supplier'].upper().strip())
        
        # Remove duplicates and sort
        suppliers = sorted(list(set(suppliers)))
        
        cursor.close()
        conn.close()
        
        return jsonify({'success': True, 'suppliers': suppliers})
        
    except Exception as e:
        print(f"Error fetching suppliers: {str(e)}")
        import traceback
        traceback.print_exc()
        return jsonify({'success': False, 'message': f'Failed to fetch suppliers: {str(e)}'}), 500

@app.route('/api/feed/stock/last-transaction', methods=['GET'])
def get_last_feed_stock_transaction():
    """Get the last stock-in transaction for a feed (and optionally farm)"""
    if 'employee_id' not in session:
        return jsonify({'success': False, 'message': 'Unauthorized'}), 401
    
    try:
        feed_id = request.args.get('feed_id', type=int)
        
        if not feed_id:
            return jsonify({'success': False, 'message': 'Feed ID is required'}), 400
        
        conn = get_db_connection()
        cursor = conn.cursor()
        farm_id = _scoped_farm_id(cursor)
        
        # Build query - get last stock_in transaction for this feed
        query = """
            SELECT 
                fs.cost,
                fs.quantity,
                fs.unit_of_measure,
                fs.supplier
            FROM feed_stock fs
            WHERE fs.feed_id = %s 
            AND fs.transaction_type = 'stock_in'
            AND fs.farm_id = %s
        """
        params = [feed_id, farm_id]
        
        query += " ORDER BY fs.transaction_date DESC, fs.created_at DESC LIMIT 1"
        
        cursor.execute(query, params)
        result = cursor.fetchone()
        
        cursor.close()
        conn.close()
        
        if result and result['cost'] and result['quantity']:
            # Calculate cost per kg
            total_cost = float(result['cost'])
            quantity = float(result['quantity'])
            unit = result['unit_of_measure']
            
            # Convert quantity to kg
            quantity_kg = quantity
            if unit == 'g':
                quantity_kg = quantity / 1000
            elif unit == 'ton':
                quantity_kg = quantity * 1000
            elif unit == 'bag':
                quantity_kg = quantity * 50  # Assuming 50kg per bag
            # liter and ml stay as is for now (assuming 1:1 with kg for feed)
            
            cost_per_kg = total_cost / quantity_kg if quantity_kg > 0 else None
            
            return jsonify({
                'success': True,
                'cost_per_kg': cost_per_kg,
                'supplier': result['supplier'] if result['supplier'] else None
            })
        else:
            return jsonify({
                'success': True,
                'cost_per_kg': None,
                'supplier': None
            })
        
    except Exception as e:
        print(f"Error fetching last transaction: {str(e)}")
        import traceback
        traceback.print_exc()
        return jsonify({'success': False, 'message': f'Failed to fetch last transaction: {str(e)}'}), 500

@app.route('/api/feed/stock/analytics', methods=['GET'])
def get_feed_stock_analytics():
    """Get feed stock analytics data for charts. Optional animal_type=pig|cow|chicken."""
    if 'employee_id' not in session:
        return jsonify({'success': False, 'message': 'Unauthorized'}), 401
    
    try:
        start_date = request.args.get('start_date')
        end_date = request.args.get('end_date')
        days = request.args.get('days', 30, type=int)  # Default to last 30 days
        animal_type = (request.args.get('animal_type') or '').strip().lower()
        if animal_type and animal_type not in ('pig', 'cow', 'chicken'):
            animal_type = None
        
        conn = get_db_connection()
        cursor = conn.cursor()
        farm_id = _scoped_farm_id(cursor)
        
        # Build date filter
        date_filter = ""
        params = []
        
        if start_date and end_date:
            date_filter = "AND DATE(fs.transaction_date) BETWEEN %s AND %s"
            params.extend([start_date, end_date])
        else:
            # Default to last N days
            date_filter = "AND DATE(fs.transaction_date) >= DATE_SUB(CURDATE(), INTERVAL %s DAY)"
            params.append(days)
        
        date_filter += " AND fs.farm_id = %s"
        params.append(farm_id)
        
        # Get feeds (optionally filtered by animal_type)
        feeds_sql = "SELECT id, feed_name, feed_type, unit_of_measure FROM feeds WHERE status = 'active'"
        feeds_params = []
        if animal_type:
            # Include feeds marked for this species and generic 'all' (and NULL legacy rows for pig)
            feeds_sql += " AND (animal_type = %s OR animal_type = 'all'"
            feeds_params.append(animal_type)
            if animal_type == 'pig':
                feeds_sql += " OR animal_type IS NULL"
            feeds_sql += ")"
        cursor.execute(feeds_sql, feeds_params or None)
        feeds = {row['id']: row for row in cursor.fetchall()}
        
        # Restrict transactions to these feeds only (so animal_type filter is applied)
        feed_ids = list(feeds.keys())
        if animal_type and not feed_ids:
            date_filter += " AND 1=0"  # no feeds for this animal
        elif feed_ids:
            placeholders = ','.join(['%s'] * len(feed_ids))
            date_filter += f" AND fs.feed_id IN ({placeholders})"
            params.extend(feed_ids)
        
        # Get stock transactions grouped by date and feed (including cost)
        query = f"""
            SELECT 
                fs.feed_id,
                DATE(fs.transaction_date) as transaction_date,
                fs.transaction_type,
                SUM(CASE 
                    WHEN fs.unit_of_measure = 'kg' THEN fs.quantity
                    WHEN fs.unit_of_measure = 'g' THEN fs.quantity / 1000
                    WHEN fs.unit_of_measure = 'ton' THEN fs.quantity * 1000
                    WHEN fs.unit_of_measure = 'bag' THEN fs.quantity * 50  -- Assuming 50kg per bag
                    ELSE fs.quantity
                END) as quantity_kg,
                SUM(COALESCE(fs.cost, 0)) as total_cost
            FROM feed_stock fs
            WHERE 1=1 {date_filter}
            GROUP BY fs.feed_id, DATE(fs.transaction_date), fs.transaction_type
            ORDER BY transaction_date ASC, fs.feed_id ASC
        """
        
        cursor.execute(query, params)
        transactions = cursor.fetchall()
        
        # Calculate running stock levels per feed
        feed_stock_levels = {}  # {feed_id: {date: stock_level_kg}}
        feed_stock_in = {}  # {feed_id: {date: stock_in_kg}}
        feed_stock_out = {}  # {feed_id: {date: stock_out_kg}}
        feed_costs = {}  # {feed_id: {date: cost}}
        feed_total_costs = {}  # {feed_id: total_cost}
        
        for trans in transactions:
            feed_id = trans['feed_id']
            date = trans['transaction_date'].strftime('%Y-%m-%d') if hasattr(trans['transaction_date'], 'strftime') else str(trans['transaction_date'])
            quantity_kg = float(trans['quantity_kg'])
            trans_type = trans['transaction_type']
            cost = float(trans['total_cost']) if trans.get('total_cost') else 0
            
            # Initialize feed data structures
            if feed_id not in feed_stock_levels:
                feed_stock_levels[feed_id] = {}
                feed_stock_in[feed_id] = {}
                feed_stock_out[feed_id] = {}
                feed_costs[feed_id] = {}
                feed_total_costs[feed_id] = 0
            
            # Track stock in/out
            if trans_type == 'stock_in':
                feed_stock_in[feed_id][date] = feed_stock_in[feed_id].get(date, 0) + quantity_kg
                # Track costs (only for stock_in)
                feed_costs[feed_id][date] = feed_costs[feed_id].get(date, 0) + cost
                feed_total_costs[feed_id] += cost
            else:
                feed_stock_out[feed_id][date] = feed_stock_out[feed_id].get(date, 0) + quantity_kg
            
            # Calculate running stock level
            prev_date_stock = 0
            if feed_stock_levels[feed_id]:
                prev_date_stock = list(feed_stock_levels[feed_id].values())[-1] if feed_stock_levels[feed_id] else 0
            
            if trans_type == 'stock_in':
                feed_stock_levels[feed_id][date] = prev_date_stock + quantity_kg
            else:
                feed_stock_levels[feed_id][date] = prev_date_stock - quantity_kg
        
        # Get all unique dates
        all_dates = set()
        for feed_data in feed_stock_levels.values():
            all_dates.update(feed_data.keys())
        for feed_data in feed_stock_in.values():
            all_dates.update(feed_data.keys())
        for feed_data in feed_stock_out.values():
            all_dates.update(feed_data.keys())
        for feed_data in feed_costs.values():
            all_dates.update(feed_data.keys())
        
        all_dates = sorted(list(all_dates))
        
        # Build response data
        analytics_data = {
            'feeds': [],
            'dates': all_dates,
            'stock_levels': {},  # {feed_id: [values per date]}
            'stock_in': {},  # {feed_id: [values per date]}
            'stock_out': {},  # {feed_id: [values per date]}
            'costs': {}  # {feed_id: [values per date]}
        }
        
        for feed_id, feed_info in feeds.items():
            feed_name = feed_info['feed_name']
            feed_type = feed_info['feed_type']
            
            analytics_data['feeds'].append({
                'id': feed_id,
                'name': feed_name,
                'type': feed_type
            })
            
            # Build time series data
            stock_levels = []
            stock_in_data = []
            stock_out_data = []
            costs_data = []
            current_stock = 0
            
            for date in all_dates:
                # Stock level (cumulative)
                if date in feed_stock_levels.get(feed_id, {}):
                    current_stock = feed_stock_levels[feed_id][date]
                stock_levels.append(round(current_stock, 2))
                
                # Stock in
                stock_in_data.append(round(feed_stock_in.get(feed_id, {}).get(date, 0), 2))
                
                # Stock out
                stock_out_data.append(round(feed_stock_out.get(feed_id, {}).get(date, 0), 2))
                
                # Costs (only for stock_in transactions)
                costs_data.append(round(feed_costs.get(feed_id, {}).get(date, 0), 2))
            
            analytics_data['stock_levels'][feed_id] = stock_levels
            analytics_data['stock_in'][feed_id] = stock_in_data
            analytics_data['stock_out'][feed_id] = stock_out_data
            analytics_data['costs'][feed_id] = costs_data
        
        # Calculate summary statistics
        total_stock_in = {}
        total_stock_out = {}
        current_stock_levels = {}
        total_costs = {}
        
        for feed_id in feeds.keys():
            total_stock_in[feed_id] = sum(feed_stock_in.get(feed_id, {}).values())
            total_stock_out[feed_id] = sum(feed_stock_out.get(feed_id, {}).values())
            total_costs[feed_id] = feed_total_costs.get(feed_id, 0)
            if feed_stock_levels.get(feed_id):
                current_stock_levels[feed_id] = list(feed_stock_levels[feed_id].values())[-1] if feed_stock_levels[feed_id] else 0
            else:
                current_stock_levels[feed_id] = 0
        
        cursor.close()
        conn.close()
        
        return jsonify({
            'success': True,
            'analytics': analytics_data,
            'summary': {
                'total_stock_in': total_stock_in,
                'total_stock_out': total_stock_out,
                'current_stock_levels': current_stock_levels,
                'total_costs': total_costs
            }
        })
        
    except Exception as e:
        print(f"Error fetching stock analytics: {str(e)}")
        import traceback
        traceback.print_exc()
        return jsonify({'success': False, 'message': f'Failed to fetch stock analytics: {str(e)}'}), 500

@app.route('/api/feed/stock/audit-trail', methods=['GET'])
def get_feed_stock_audit_trail():
    """Get detailed audit trail for feed stock transactions"""
    if 'employee_id' not in session:
        return jsonify({'success': False, 'message': 'Unauthorized'}), 401
    
    try:
        limit = request.args.get('limit', 50, type=int)
        feed_id = request.args.get('feed_id', type=int)
        transaction_type = request.args.get('transaction_type')
        
        conn = get_db_connection()
        cursor = conn.cursor()
        farm_id = _scoped_farm_id(cursor)
        
        # Build query with optional filters
        query = """
            SELECT 
                fs.id,
                fs.transaction_type,
                fs.quantity,
                fs.unit_of_measure,
                fs.transaction_date,
                fs.supplier,
                fs.notes,
                fs.created_at,
                fs.updated_at,
                f.feed_name,
                f.feed_type,
                fm.farm_name,
                fm.farm_location,
                e.full_name as created_by_name,
                e.employee_code as created_by_code,
                e.role as created_by_role
            FROM feed_stock fs
            INNER JOIN feeds f ON fs.feed_id = f.id
            INNER JOIN farms fm ON fs.farm_id = fm.id
            INNER JOIN employees e ON fs.created_by = e.id
            WHERE 1=1
        """
        params = []
        
        if feed_id:
            query += " AND fs.feed_id = %s"
            params.append(feed_id)
        
        query += " AND fs.farm_id = %s"
        params.append(farm_id)
        
        if transaction_type:
            query += " AND fs.transaction_type = %s"
            params.append(transaction_type)
        
        query += " ORDER BY fs.created_at DESC LIMIT %s"
        params.append(limit)
        
        cursor.execute(query, params)
        
        audit_trail = []
        for row in cursor.fetchall():
            audit_trail.append({
                'id': row['id'],
                'transaction_type': row['transaction_type'],
                'quantity': float(row['quantity']),
                'unit_of_measure': row['unit_of_measure'],
                'transaction_date': row['transaction_date'].strftime('%Y-%m-%d') if row['transaction_date'] else None,
                'supplier': row['supplier'],
                'notes': row['notes'],
                'created_at': row['created_at'].strftime('%Y-%m-%d %H:%M:%S') if row['created_at'] else None,
                'updated_at': row['updated_at'].strftime('%Y-%m-%d %H:%M:%S') if row['updated_at'] else None,
                'feed_name': row['feed_name'],
                'feed_type': row['feed_type'],
                'farm_name': row['farm_name'],
                'farm_location': row['farm_location'],
                'created_by_name': row['created_by_name'],
                'created_by_code': row['created_by_code'],
                'created_by_role': row['created_by_role']
            })
        
        cursor.close()
        conn.close()
        
        return jsonify({'success': True, 'audit_trail': audit_trail, 'total': len(audit_trail)})
        
    except Exception as e:
        print(f"Error fetching audit trail: {str(e)}")
        import traceback
        traceback.print_exc()
        return jsonify({'success': False, 'message': f'Failed to fetch audit trail: {str(e)}'}), 500

@app.route('/api/feed/settings/list', methods=['GET'])
def get_feed_settings_list():
    """Get list of all feed settings"""
    if 'employee_id' not in session:
        return jsonify({'success': False, 'message': 'Unauthorized'}), 401
    
    try:
        animal_type = request.args.get('animal_type', 'all')
        
        conn = get_db_connection()
        cursor = conn.cursor()
        
        # Check if feed_settings table exists
        cursor.execute("""
            CREATE TABLE IF NOT EXISTS feed_settings (
                id INT AUTO_INCREMENT PRIMARY KEY,
                animal_type ENUM('pig', 'cow', 'chicken', 'all') NOT NULL DEFAULT 'all',
                age_group_name VARCHAR(100) NOT NULL,
                start_age_days INT NOT NULL,
                end_age_days INT NOT NULL,
                feed_amount_grams DECIMAL(10,2) NOT NULL,
                feeding_times_per_day INT NOT NULL DEFAULT 2,
                feeding_times JSON,
                feed_type VARCHAR(255),
                notes TEXT,
                status ENUM('active', 'inactive') DEFAULT 'active',
                created_by INT NOT NULL,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
                FOREIGN KEY (created_by) REFERENCES employees(id),
                INDEX idx_animal_type (animal_type),
                INDEX idx_age_range (start_age_days, end_age_days),
                INDEX idx_status (status)
            )
        """)
        
        # Add feeding_times column if it doesn't exist
        try:
            cursor.execute("ALTER TABLE feed_settings ADD COLUMN feeding_times JSON")
        except Exception as e:
            # Column already exists, ignore
            pass
        
        if animal_type == 'all':
            cursor.execute("""
                SELECT fs.*, e.full_name as created_by_name
                FROM feed_settings fs
                LEFT JOIN employees e ON fs.created_by = e.id
                WHERE fs.status = 'active'
                ORDER BY fs.animal_type, fs.start_age_days ASC
            """)
        else:
            cursor.execute("""
                SELECT fs.*, e.full_name as created_by_name
                FROM feed_settings fs
                LEFT JOIN employees e ON fs.created_by = e.id
                WHERE fs.animal_type = %s AND fs.status = 'active'
                ORDER BY fs.start_age_days ASC
            """, (animal_type,))
        
        settings = []
        import json
        for row in cursor.fetchall():
            # Parse feeding_times JSON if it exists
            feeding_times = None
            if row.get('feeding_times'):
                try:
                    feeding_times = json.loads(row['feeding_times']) if isinstance(row['feeding_times'], str) else row['feeding_times']
                except:
                    feeding_times = None
            
            settings.append({
                'id': row['id'],
                'animal_type': row['animal_type'],
                'age_group_name': row['age_group_name'],
                'start_age_days': row['start_age_days'],
                'end_age_days': row['end_age_days'],
                'feed_amount_grams': float(row['feed_amount_grams']),
                'feeding_times_per_day': row['feeding_times_per_day'],
                'feeding_times': feeding_times,
                'feed_type': row['feed_type'],  # This will be the feed_id (integer) or feed name
                'notes': row['notes'],
                'status': row['status'],
                'created_by_name': row['created_by_name'],
                'created_at': row['created_at'].strftime('%Y-%m-%d %H:%M:%S') if row['created_at'] else None,
                'updated_at': row['updated_at'].strftime('%Y-%m-%d %H:%M:%S') if row['updated_at'] else None
            })
        
        cursor.close()
        conn.close()
        
        return jsonify({'success': True, 'settings': settings})
        
    except Exception as e:
        print(f"Error fetching feed settings: {str(e)}")
        import traceback
        traceback.print_exc()
        return jsonify({'success': False, 'message': f'Failed to fetch feed settings: {str(e)}'}), 500

@app.route('/api/feed/settings/create', methods=['POST'])
def create_feed_setting():
    """Create a new feed setting"""
    if 'employee_id' not in session:
        return jsonify({'success': False, 'message': 'Unauthorized'}), 401
    
    try:
        data = request.get_json()
        
        # Validate required fields
        animal_type = (data.get('animal_type') or 'pig')  # Default; JSON may send null
        # JSON null / missing: use (x or '') so .strip() is never called on None
        age_group_name = (data.get('age_group_name') or '').strip()
        start_age_days = data.get('start_age_days')
        end_age_days = data.get('end_age_days')
        feed_amount_grams = data.get('feed_amount_grams')
        feeding_times_per_day = data.get('feeding_times_per_day', 2)
        feeding_times = data.get('feeding_times', [])
        feed_type = (data.get('feed_type') or '').strip() or None
        
        # Validate feeding times
        if not feeding_times or len(feeding_times) != feeding_times_per_day:
            return jsonify({'success': False, 'message': f'Please provide {feeding_times_per_day} feeding time(s)'})
        notes = (data.get('notes') or '').strip() or None
        
        if not age_group_name or start_age_days is None or end_age_days is None or feed_amount_grams is None:
            return jsonify({'success': False, 'message': 'Age group name, age range, and feed amount are required'})
        
        if start_age_days < 0 or end_age_days < 0:
            return jsonify({'success': False, 'message': 'Age values must be non-negative'})
        
        if start_age_days >= end_age_days:
            return jsonify({'success': False, 'message': 'End age must be greater than start age'})
        
        if feed_amount_grams <= 0:
            return jsonify({'success': False, 'message': 'Feed amount must be greater than 0'})
        
        if feeding_times_per_day < 1 or feeding_times_per_day > 10:
            return jsonify({'success': False, 'message': 'Feeding times per day must be between 1 and 10'})
        
        valid_animal_types = ['pig', 'cow', 'chicken', 'all']
        if animal_type not in valid_animal_types:
            return jsonify({'success': False, 'message': 'Invalid animal type'})
        
        # Get database connection first
        conn = get_db_connection()
        cursor = conn.cursor()
        
        # If feed_type is provided, validate it's a valid feed ID
        if feed_type:
            try:
                feed_type_id = int(feed_type)
                # Verify feed exists
                cursor.execute("SELECT id FROM feeds WHERE id = %s AND status = 'active'", (feed_type_id,))
                if not cursor.fetchone():
                    cursor.close()
                    conn.close()
                    return jsonify({'success': False, 'message': 'Selected feed not found or inactive'})
                feed_type = feed_type_id  # Store as integer ID
            except (ValueError, TypeError):
                # If not a valid integer, treat as feed name (for backward compatibility)
                pass
        
        # Check for overlapping age ranges for the same animal type and feed type
        cursor.execute("""
            SELECT id FROM feed_settings 
            WHERE animal_type = %s 
            AND status = 'active'
            AND (feed_type = %s OR (feed_type IS NULL AND %s IS NULL))
            AND (
                (start_age_days <= %s AND end_age_days >= %s) OR
                (start_age_days <= %s AND end_age_days >= %s) OR
                (start_age_days >= %s AND end_age_days <= %s)
            )
        """, (animal_type, feed_type, feed_type, start_age_days, start_age_days, end_age_days, end_age_days, start_age_days, end_age_days))
        
        if cursor.fetchone():
            cursor.close()
            conn.close()
            return jsonify({'success': False, 'message': 'Age range overlaps with existing setting for this animal type and feed type'})
        
        # Insert new feed setting
        # Store feeding_times as JSON
        import json
        feeding_times_json = json.dumps(feeding_times) if feeding_times else None
        cursor.execute("""
            INSERT INTO feed_settings (animal_type, age_group_name, start_age_days, end_age_days, feed_amount_grams, feeding_times_per_day, feeding_times, feed_type, notes, created_by)
            VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s)
        """, (animal_type, age_group_name, start_age_days, end_age_days, feed_amount_grams, feeding_times_per_day, feeding_times_json, feed_type, notes, session['employee_id']))
        
        setting_id = cursor.lastrowid
        
        # Log activity
        log_activity(session['employee_id'], 'FEED_SETTING_CREATED', 
                    f'Created feed setting: {age_group_name} ({start_age_days}-{end_age_days} days) for {animal_type}')
        
        conn.commit()
        cursor.close()
        conn.close()
        
        return jsonify({
            'success': True,
            'message': 'Feed setting created successfully',
            'setting_id': setting_id
        })
        
    except Exception as e:
        print(f"Error creating feed setting: {str(e)}")
        import traceback
        traceback.print_exc()
        return jsonify({'success': False, 'message': f'Failed to create feed setting: {str(e)}'}), 500

@app.route('/api/feed/settings/update/<int:setting_id>', methods=['PUT'])
def update_feed_setting(setting_id):
    """Update an existing feed setting"""
    if 'employee_id' not in session:
        return jsonify({'success': False, 'message': 'Unauthorized'}), 401
    
    try:
        data = request.get_json()
        
        conn = get_db_connection()
        cursor = conn.cursor()
        
        # Check if setting exists
        cursor.execute("SELECT id FROM feed_settings WHERE id = %s", (setting_id,))
        if not cursor.fetchone():
            cursor.close()
            conn.close()
            return jsonify({'success': False, 'message': 'Feed setting not found'})
        
        # Build update query dynamically
        updates = []
        params = []
        
        if 'age_group_name' in data:
            updates.append("age_group_name = %s")
            params.append((data['age_group_name'] or '').strip())
        
        if 'start_age_days' in data:
            updates.append("start_age_days = %s")
            params.append(data['start_age_days'])
        
        if 'end_age_days' in data:
            updates.append("end_age_days = %s")
            params.append(data['end_age_days'])
        
        if 'feed_amount_grams' in data:
            updates.append("feed_amount_grams = %s")
            params.append(data['feed_amount_grams'])
        
        if 'feeding_times_per_day' in data:
            updates.append("feeding_times_per_day = %s")
            params.append(data['feeding_times_per_day'])
        
        if 'feeding_times' in data:
            import json
            feeding_times_json = json.dumps(data['feeding_times']) if data['feeding_times'] else None
            updates.append("feeding_times = %s")
            params.append(feeding_times_json)
        
        if 'feed_type' in data:
            updates.append("feed_type = %s")
            params.append(data['feed_type'].strip() if data['feed_type'] else None)
        
        if 'notes' in data:
            updates.append("notes = %s")
            params.append(data['notes'].strip() if data['notes'] else None)
        
        if 'status' in data:
            updates.append("status = %s")
            params.append(data['status'])
        
        if not updates:
            cursor.close()
            conn.close()
            return jsonify({'success': False, 'message': 'No fields to update'})
        
        updates.append("updated_at = CURRENT_TIMESTAMP")
        params.append(setting_id)
        
        query = f"UPDATE feed_settings SET {', '.join(updates)} WHERE id = %s"
        cursor.execute(query, params)
        
        # Log activity
        log_activity(session['employee_id'], 'FEED_SETTING_UPDATED', 
                    f'Updated feed setting ID: {setting_id}')
        
        conn.commit()
        cursor.close()
        conn.close()
        
        return jsonify({
            'success': True,
            'message': 'Feed setting updated successfully'
        })
        
    except Exception as e:
        print(f"Error updating feed setting: {str(e)}")
        import traceback
        traceback.print_exc()
        return jsonify({'success': False, 'message': f'Failed to update feed setting: {str(e)}'}), 500

