        now = datetime.now()
        current_hour = now.hour
        current_minute = now.minute
        today = now.date()

        conn = get_db_connection()
        cursor = conn.cursor()
        all_notifications = collect_all_feed_notifications(
            cursor, now, today, current_hour, current_minute
        )
        cursor.close()
