@app.route('/api/feed/process-feeding', methods=['POST'])
def process_feeding():
    """Process feeding notification - stock out feed and mark as fed"""
    if 'employee_id' not in session:
        return jsonify({'success': False, 'message': 'Unauthorized'}), 401
    
    try:
        data = request.get_json()
        feed_id = data.get('feed_id')
        
        if not feed_id:
            return jsonify({'success': False, 'message': 'Feed ID is required'}), 400
        
        from datetime import datetime
        import json
        
        conn = get_db_connection()
        cursor = conn.cursor()
        farm_id = _scoped_farm_id(cursor)
        
        # Get feed details
        cursor.execute("SELECT id, feed_name, feed_type, unit_of_measure FROM feeds WHERE id = %s AND status = 'active'", (feed_id,))
        feed = cursor.fetchone()
        
        if not feed:
            cursor.close()
            conn.close()
            return jsonify({'success': False, 'message': 'Feed not found'}), 404
        
        # Get feed settings for this feed
        cursor.execute("""
            SELECT id, age_group_name, start_age_days, end_age_days, feed_amount_grams, 
                   feeding_times_per_day, feeding_times, animal_type
            FROM feed_settings
            WHERE feed_type = %s AND status = 'active' AND animal_type = 'pig'
        """, (str(feed_id),))
        feed_settings = cursor.fetchall()
        
        if not feed_settings:
            cursor.close()
            conn.close()
            return jsonify({'success': False, 'message': 'No feed settings found for this feed'}), 404
        
        # Get animals matching the age ranges
        age_conditions = []
        for setting in feed_settings:
            age_conditions.append(f"(DATEDIFF(CURDATE(), p.birth_date) BETWEEN {setting['start_age_days']} AND {setting['end_age_days']})")
        
        age_condition = " OR ".join(age_conditions)
        
        query = f"""
            SELECT 
                p.id,
                p.tag_id,
                p.farm_id,
                f.farm_name,
                DATEDIFF(CURDATE(), p.birth_date) as age_days
            FROM pigs p
            LEFT JOIN farms f ON p.farm_id = f.id
            WHERE p.status = 'active'
            AND p.birth_date IS NOT NULL
            AND ({age_condition})
        """
        params = [farm_id]
        
        query += " AND p.farm_id = %s"
        
        cursor.execute(query, params)
        animals = cursor.fetchall()
        
        if not animals:
            cursor.close()
            conn.close()
            return jsonify({'success': False, 'message': 'No animals found matching the feed settings'}), 404
        
        # Calculate total feed required
        total_grams = 0
        for animal in animals:
            # Find matching feed setting for this animal's age
            for setting in feed_settings:
                if setting['start_age_days'] <= animal['age_days'] <= setting['end_age_days']:
                    total_grams += setting['feed_amount_grams']
                    break
        
        # Convert to feed's unit
        unit = feed['unit_of_measure']
        quantity = total_grams
        if unit == 'kg':
            quantity = total_grams / 1000
        elif unit == 'g':
            quantity = total_grams
        elif unit == 'ton':
            quantity = total_grams / 1000000
        elif unit == 'bag':
            quantity = (total_grams / 1000) / 50  # Assuming 50kg per bag
        
        # Create stock out transaction
        transaction_date = datetime.now().strftime('%Y-%m-%d')
        cursor.execute("""
            INSERT INTO feed_stock (feed_id, farm_id, transaction_type, quantity, unit_of_measure, transaction_date, notes, created_by)
            VALUES (%s, %s, 'stock_out', %s, %s, %s, %s, %s)
        """, (
            feed_id,
            farm_id,
            quantity,
            unit,
            transaction_date,
            f'Automatic stock out for feeding - {len(animals)} animals',
            session['employee_id']
        ))
        
        conn.commit()
        cursor.close()
        conn.close()
        
        return jsonify({
            'success': True,
            'message': f'Successfully stocked out {quantity:.2f} {unit} of {feed["feed_name"]} for {len(animals)} animals',
            'quantity': quantity,
            'unit': unit,
            'animal_count': len(animals)
        })
        
    except Exception as e:
        print(f"Error processing feeding: {str(e)}")
        import traceback
        traceback.print_exc()
        return jsonify({'success': False, 'message': f'Failed to process feeding: {str(e)}'}), 500

