@app.route('/api/hr/delete-employee', methods=['POST'])
def delete_employee():
    """Delete an employee from the system."""
    if 'employee_id' not in session or session.get('employee_role') not in ['administrator', 'manager']:
        return jsonify({'error': 'Unauthorized'}), 401

    try:
        data = request.get_json() or {}
        employee_id = data.get('employee_id')

        if not employee_id:
            return jsonify({'error': 'Employee id is required'}), 400

        if int(employee_id) == int(session['employee_id']):
            return jsonify({'error': 'You cannot delete your own account while logged in'}), 400

        conn = get_db_connection()
        cursor = conn.cursor()

        cursor.execute("SELECT id FROM employees WHERE id = %s LIMIT 1", (employee_id,))
        target_employee = cursor.fetchone()
        if not target_employee:
            cursor.close()
            conn.close()
            return jsonify({'error': 'Employee not found'}), 404

        cursor.execute("DELETE FROM employees WHERE id = %s", (employee_id,))
        conn.commit()

        # Log activity
        log_activity(
            session['employee_id'],
            'EMPLOYEE_DELETE',
            f'Employee {employee_id} deleted from HR management'
        )

        cursor.close()
        conn.close()

        return jsonify({'success': True, 'message': 'Employee deleted successfully'})
    except pymysql.err.IntegrityError:
        try:
            conn = get_db_connection()
            cursor = conn.cursor()

            cursor.execute("SELECT DATABASE() AS db_name")
            db_name_row = cursor.fetchone()
            db_name = db_name_row.get('db_name') if isinstance(db_name_row, dict) else None
            if not db_name:
                raise RuntimeError('Could not determine current database for cleanup')

            cursor.execute(
                """
                SELECT
                    kcu.TABLE_NAME AS table_name,
                    kcu.COLUMN_NAME AS column_name,
                    cols.IS_NULLABLE AS is_nullable
                FROM information_schema.KEY_COLUMN_USAGE kcu
                INNER JOIN information_schema.COLUMNS cols
                    ON cols.TABLE_SCHEMA = kcu.TABLE_SCHEMA
                    AND cols.TABLE_NAME = kcu.TABLE_NAME
                    AND cols.COLUMN_NAME = kcu.COLUMN_NAME
                WHERE kcu.REFERENCED_TABLE_SCHEMA = %s
                  AND kcu.REFERENCED_TABLE_NAME = 'employees'
                  AND kcu.REFERENCED_COLUMN_NAME = 'id'
                """,
                (db_name,)
            )
            references = cursor.fetchall()

            for reference in references:
                table_name = reference.get('table_name')
                column_name = reference.get('column_name')
                is_nullable = reference.get('is_nullable') == 'YES'

                # Protect dynamic identifier usage.
                if not re.match(r'^[A-Za-z0-9_]+$', table_name or '') or not re.match(r'^[A-Za-z0-9_]+$', column_name or ''):
                    continue

                if is_nullable:
                    cursor.execute(
                        f"UPDATE `{table_name}` SET `{column_name}` = NULL WHERE `{column_name}` = %s",
                        (employee_id,)
                    )
                else:
                    cursor.execute(
                        f"DELETE FROM `{table_name}` WHERE `{column_name}` = %s",
                        (employee_id,)
                    )

            cursor.execute("DELETE FROM employees WHERE id = %s", (employee_id,))
            conn.commit()

            log_activity(
                session['employee_id'],
                'EMPLOYEE_DELETE_FORCE',
                f'Employee {employee_id} force-deleted after cleaning related references'
            )

            cursor.close()
            conn.close()

            return jsonify({
                'success': True,
                'message': 'Employee and related references deleted successfully.'
            })
        except Exception as force_delete_error:
            return jsonify({
                'error': f'Could not fully delete employee: {force_delete_error}'
            }), 500
    except Exception as e:
        return jsonify({'error': str(e)}), 500

@app.route('/api/hr/update-employee', methods=['POST'])
def update_employee():
    """Update employee details"""
    if 'employee_id' not in session or session.get('employee_role') not in ['administrator', 'manager']:
        return jsonify({'error': 'Unauthorized'}), 401
    
    try:
        # Support both JSON and multipart/form-data so profile image can be uploaded.
        if request.is_json:
            data = request.get_json() or {}
            employee_id = data.get('employee_id')
            full_name = data.get('full_name')
            email = data.get('email')
            phone = data.get('phone')
            role = data.get('role')
            password = data.get('password')
            profile_image_file = None
        else:
            employee_id = request.form.get('employee_id')
            full_name = request.form.get('full_name')
            email = request.form.get('email')
            phone = request.form.get('phone')
            role = request.form.get('role')
            password = request.form.get('password')
            profile_image_file = request.files.get('profile_image')
        
        # Validate password if provided (backend validation for security)
        if password and password.strip():
            if len(password) < 6:
                return jsonify({'error': 'Password must be at least 6 characters long'}), 400
        
        conn = get_db_connection()
        cursor = conn.cursor()
        
        image_filename = None
        if profile_image_file and profile_image_file.filename:
            allowed_extensions = {'png', 'jpg', 'jpeg', 'gif', 'webp'}
            file_extension = profile_image_file.filename.rsplit('.', 1)[1].lower() if '.' in profile_image_file.filename else ''
            if file_extension not in allowed_extensions:
                return jsonify({'error': 'Invalid profile image type. Allowed: png, jpg, jpeg, gif, webp'}), 400
            upload_dir = 'static/uploads/employees'
            os.makedirs(upload_dir, exist_ok=True)
            image_filename = f"{secrets.token_hex(16)}.{file_extension}"
            profile_image_file.save(os.path.join(upload_dir, image_filename))

        # Build update query based on whether password/image are provided
        if password and password.strip():
            hashed_password = hash_password(password)
            if image_filename:
                cursor.execute("""
                    UPDATE employees 
                    SET full_name = %s, email = %s, phone = %s, role = %s, password = %s, profile_image = %s
                    WHERE id = %s
                """, (full_name, email, phone, role, hashed_password, image_filename, employee_id))
            else:
                cursor.execute("""
                    UPDATE employees 
                    SET full_name = %s, email = %s, phone = %s, role = %s, password = %s 
                    WHERE id = %s
                """, (full_name, email, phone, role, hashed_password, employee_id))
            update_message = 'Employee details and password updated successfully'
        else:
            if image_filename:
                cursor.execute("""
                    UPDATE employees 
                    SET full_name = %s, email = %s, phone = %s, role = %s, profile_image = %s
                    WHERE id = %s
                """, (full_name, email, phone, role, image_filename, employee_id))
                update_message = 'Employee details and profile image updated successfully'
            else:
                cursor.execute("""
                    UPDATE employees 
                    SET full_name = %s, email = %s, phone = %s, role = %s 
                    WHERE id = %s
                """, (full_name, email, phone, role, employee_id))
                update_message = 'Employee details updated successfully'
        
        conn.commit()
        
        # Log activity
        log_activity(session['employee_id'], 'EMPLOYEE_UPDATE', 
                    f'Employee {employee_id} details updated')
        
        cursor.close()
        conn.close()
        
        return jsonify({'success': True, 'message': update_message})
    except Exception as e:
        return jsonify({'error': str(e)}), 500

@app.route('/api/hr/update-permissions', methods=['POST'])
def update_permissions():
    """Update employee permissions"""
    if 'employee_id' not in session or session.get('employee_role') not in ['administrator', 'manager']:
        return jsonify({'error': 'Unauthorized'}), 401
    
    try:
        data = request.get_json()
        employee_id = data.get('employee_id')
        permissions = data.get('permissions', {})

        if not employee_id:
            return jsonify({'error': 'Employee id is required'}), 400

        normalized_permissions = {
            "create": bool(permissions.get("create", True)),
            "insert": bool(permissions.get("insert", True)),
            "edit": bool(permissions.get("edit", True)),
            "suspend": bool(permissions.get("suspend", True)),
            "delete": bool(permissions.get("delete", True)),
            "generate": bool(permissions.get("generate", True)),
        }

        conn = get_db_connection()
        cursor = conn.cursor()

        cursor.execute(
            """
            INSERT INTO employee_permissions
            (employee_id, can_create, can_insert, can_edit, can_suspend, can_delete, can_generate)
            VALUES (%s, %s, %s, %s, %s, %s, %s)
            ON DUPLICATE KEY UPDATE
                can_create = VALUES(can_create),
                can_insert = VALUES(can_insert),
                can_edit = VALUES(can_edit),
                can_suspend = VALUES(can_suspend),
                can_delete = VALUES(can_delete),
                can_generate = VALUES(can_generate)
            """,
            (
                employee_id,
                normalized_permissions["create"],
                normalized_permissions["insert"],
                normalized_permissions["edit"],
                normalized_permissions["suspend"],
                normalized_permissions["delete"],
                normalized_permissions["generate"],
            ),
        )

        conn.commit()

        # Log activity
        log_activity(session['employee_id'], 'PERMISSION_UPDATE', 
                    f'Employee {employee_id} permissions updated: {json.dumps(normalized_permissions)}')

        cursor.close()
        conn.close()

        return jsonify({'success': True, 'message': 'Permissions updated successfully'})
    except Exception as e:
        return jsonify({'error': str(e)}), 500


