@app.route('/api/pigs/search', methods=['GET'])
def search_pigs_for_litter():
    """Live search for sows (female) and boars (male) by tag or breed."""
    if 'employee_id' not in session:
        return jsonify({'error': 'Unauthorized'}), 401
    try:
        q = (request.args.get('q') or '').strip()
        gender = (request.args.get('gender') or '').strip().lower()
        if gender not in ('female', 'male'):
            return jsonify({'success': False, 'message': 'Query parameter gender must be female or male'}), 400
        if len(q) < 1:
            return jsonify({'success': True, 'pigs': []})
        like = f"%{q}%"
        conn = get_db_connection()
        cursor = conn.cursor()
        cursor.execute(
            """
            SELECT p.id, p.tag_id, p.breed, p.gender, p.status, f.farm_name AS farm_name
            FROM pigs p
            LEFT JOIN farms f ON p.farm_id = f.id
            WHERE p.gender = %s
              AND p.status = 'active'
              AND (p.tag_id LIKE %s OR COALESCE(p.breed, '') LIKE %s)
            ORDER BY p.tag_id ASC
            LIMIT 40
            """,
            (gender, like, like),
        )
        rows = cursor.fetchall() or []
        cursor.close()
        conn.close()
        return jsonify({'success': True, 'pigs': rows})
    except Exception as e:
        print(f"Error searching pigs: {str(e)}")
        return jsonify({'success': False, 'message': str(e)}), 500


# Litter Management API Endpoints

@app.route('/api/litter/next-id', methods=['GET'])
def get_next_litter_id():
    """Get next available litter ID"""
    if 'employee_id' not in session:
        return jsonify({'error': 'Unauthorized'}), 401
    
    try:
        conn = get_db_connection()
        cursor = conn.cursor()
        
        # Get the highest existing litter ID
        cursor.execute("""
            SELECT litter_id FROM litters 
            ORDER BY CAST(SUBSTRING(litter_id, 2) AS UNSIGNED) DESC 
            LIMIT 1
        """)
        
        result = cursor.fetchone()
        
        if result:
            # Extract number from existing ID (e.g., L001 -> 1)
            current_number = int(result['litter_id'][1:])
            next_number = current_number + 1
        else:
            # No existing litters, start with 1
            next_number = 1
        
        # Format as L001, L002, etc.
        next_litter_id = f"L{next_number:03d}"
        
        cursor.close()
        conn.close()
        
        return jsonify({
            'success': True,
            'next_litter_id': next_litter_id
        })
        
    except Exception as e:
        print(f"Error getting next litter ID: {str(e)}")
        return jsonify({'success': False, 'message': f'Failed to get next litter ID: {str(e)}'})

@app.route('/api/litter/register', methods=['POST'])
def register_litter():
    """Register a new litter (born on farm: sow/boar pig IDs + farrowing; purchased: parent breeds)."""
    if 'employee_id' not in session or session.get('employee_role') not in ['administrator', 'manager']:
        return jsonify({'error': 'Unauthorized'}), 401
    
    try:
        data = request.get_json() or {}
        litter_source = (data.get('litter_source') or 'born').strip().lower()
        if litter_source not in ('born', 'purchased'):
            litter_source = 'born'

        for key in ['litter_id', 'farrowing_date', 'total_piglets', 'alive_piglets', 'male_piglets', 'female_piglets']:
            v = data.get(key)
            if v is None or (isinstance(v, str) and not str(v).strip()):
                return jsonify({'success': False, 'message': f'{key.replace("_", " ")} is required'})

        if litter_source == 'purchased':
            for key in ['sow_breed', 'boar_breed']:
                v = (data.get(key) or '').strip() if data.get(key) is not None else ''
                if not v:
                    return jsonify({'success': False, 'message': f'{key.replace("_", " ")} is required for a purchased litter'})

        try:
            total_piglets = int(data['total_piglets'])
            alive_piglets = int(data['alive_piglets'])
            male_piglets = int(data['male_piglets'])
            female_piglets = int(data['female_piglets'])
        except (TypeError, ValueError):
            return jsonify({'success': False, 'message': 'Piglet counts must be valid numbers'})

        if any(x < 0 for x in (male_piglets, female_piglets, alive_piglets, total_piglets)):
            return jsonify({'success': False, 'message': 'Counts cannot be negative'})
        if male_piglets + female_piglets != alive_piglets:
            return jsonify({
                'success': False,
                'message': 'Male piglets + female piglets must equal alive piglets',
            })

        still_births = int(data.get('still_births') or 0)
        if alive_piglets + still_births > total_piglets:
            return jsonify({
                'success': False,
                'message': 'Alive piglets + still births cannot exceed total piglets',
            })

        conn = get_db_connection()
        cursor = conn.cursor()

        farrowing_record_id = None
        sow_id = None
        boar_id = None
        sow_breed = None
        boar_breed = None
        weaning_weight = None
        weaning_date = None

        if litter_source == 'born':
            for key in ['sow_id', 'boar_id']:
                v = data.get(key)
                if v is None or (isinstance(v, str) and not str(v).strip()):
                    return jsonify({'success': False, 'message': f'{key.replace("_", " ")} is required (select sow and boar from the list)'})
            try:
                sow_id = int(data['sow_id'])
                boar_id = int(data['boar_id'])
            except (TypeError, ValueError):
                cursor.close()
                conn.close()
                return jsonify({'success': False, 'message': 'Sow and boar must be valid animal IDs'})

            cursor.execute(
                "SELECT id, gender FROM pigs WHERE id = %s AND status = 'active'",
                (sow_id,),
            )
            sow_row = cursor.fetchone()
            if not sow_row or (sow_row.get('gender') or '').lower() != 'female':
                cursor.close()
                conn.close()
                return jsonify({'success': False, 'message': 'Sow must be an active female pig in the system'})

            cursor.execute(
                "SELECT id, gender FROM pigs WHERE id = %s AND status = 'active'",
                (boar_id,),
            )
            boar_row = cursor.fetchone()
            if not boar_row or (boar_row.get('gender') or '').lower() != 'male':
                cursor.close()
                conn.close()
                return jsonify({'success': False, 'message': 'Boar must be an active male pig in the system'})

            farrowing_record_id = data.get('farrowing_record_id')
            if farrowing_record_id is not None and str(farrowing_record_id).strip() != '':
                try:
                    farrowing_record_id = int(farrowing_record_id)
                except (TypeError, ValueError):
                    cursor.close()
                    conn.close()
                    return jsonify({'success': False, 'message': 'Farrowing record id must be a number'})
            else:
                farrowing_record_id = None
            if not farrowing_record_id and data.get('breeding_record_id'):
                cursor.execute(
                    """
                    SELECT id FROM farrowing_records
                    WHERE breeding_id = %s
                    ORDER BY id DESC
                    LIMIT 1
                    """,
                    (int(data['breeding_record_id']),),
                )
                r = cursor.fetchone()
                if r:
                    farrowing_record_id = r['id']
            if not farrowing_record_id:
                cursor.close()
                conn.close()
                return jsonify({'success': False, 'message': 'Farrowing record is required (link to breeding / farrowing cycle)'})

            cursor.execute("""
                SELECT weaning_weight, weaning_date
                FROM farrowing_activities
                WHERE farrowing_record_id = %s AND activity_name = 'Weaning' AND completed = TRUE
            """, (farrowing_record_id,))

            weaning_data = cursor.fetchone()
            if weaning_data:
                weaning_weight = weaning_data['weaning_weight']
                weaning_date = weaning_data['weaning_date']
        else:
            sow_breed = (data.get('sow_breed') or '').strip()
            boar_breed = (data.get('boar_breed') or '').strip()

        # Check if litter ID already exists
        cursor.execute("SELECT id FROM litters WHERE litter_id = %s", (data['litter_id'],))
        if cursor.fetchone():
            cursor.close()
            conn.close()
            return jsonify({'success': False, 'message': 'Litter ID already exists'})

        # Insert litter record
        cursor.execute("""
            INSERT INTO litters (
                litter_id, farrowing_record_id, sow_id, boar_id, farrowing_date,
                litter_source, sow_breed, boar_breed,
                total_piglets, alive_piglets, male_piglets, female_piglets, still_births, avg_weight,
                weaning_weight, weaning_date, notes, created_by
            ) VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s)
        """, (
            data['litter_id'], farrowing_record_id, sow_id, boar_id, data['farrowing_date'],
            litter_source, sow_breed, boar_breed,
            total_piglets, alive_piglets, male_piglets, female_piglets, still_births, data.get('avg_weight'),
            weaning_weight, weaning_date, data.get('notes'), session['employee_id']
        ))

        if litter_source == 'born' and farrowing_record_id:
            cursor.execute(
                "SELECT breeding_id FROM farrowing_records WHERE id = %s",
                (farrowing_record_id,),
            )
            breeding_record = cursor.fetchone()
            if not breeding_record:
                conn.rollback()
                cursor.close()
                conn.close()
                return jsonify({'success': False, 'message': 'Breeding record not found for this farrowing'})
        # NOTE: Do NOT flip the sow to 'available' here (born flow). Purchased litters are not tied to a farm sow record.

        if litter_source == 'born':
            log_desc = (
                f'Registered born litter {data["litter_id"]} with {alive_piglets} alive '
                f'({male_piglets}M/{female_piglets}F), sow {sow_id}, boar {boar_id}'
            )
        else:
            log_desc = (
                f'Registered purchased litter {data["litter_id"]} with {alive_piglets} alive '
                f'({male_piglets}M/{female_piglets}F), dam breed {sow_breed!r}, sire breed {boar_breed!r}'
            )
        log_activity(session['employee_id'], 'LITTER_REGISTRATION', log_desc)

        conn.commit()
        cursor.close()
        conn.close()

        return jsonify({
            'success': True,
            'message': f'Litter {data["litter_id"]} registered successfully with {alive_piglets} alive piglets',
        })
        
    except Exception as e:
        print(f"Error registering litter: {str(e)}")
        return jsonify({'success': False, 'message': f'Failed to register litter: {str(e)}'})

@app.route('/api/litter/postpone', methods=['POST'])
def postpone_litter_registration():
    """Postpone litter registration with reason"""
    if 'employee_id' not in session or session.get('employee_role') not in ['administrator', 'manager']:
        return jsonify({'error': 'Unauthorized'}), 401
    
    try:
        data = request.get_json() or {}
        
        if not data.get('reason'):
            return jsonify({'success': False, 'message': 'Reason for postponement is required'})
        
        conn = get_db_connection()
        cursor = conn.cursor()

        farrowing_record_id = data.get('farrowing_record_id')
        if not farrowing_record_id and data.get('breeding_record_id'):
            cursor.execute(
                """
                SELECT id FROM farrowing_records
                WHERE breeding_id = %s
                ORDER BY id DESC
                LIMIT 1
                """,
                (int(data['breeding_record_id']),),
            )
            r = cursor.fetchone()
            if r:
                farrowing_record_id = r['id']
        if not farrowing_record_id:
            cursor.close()
            conn.close()
            return jsonify({'success': False, 'message': 'Farrowing or breeding record is required'})
        
        # Get breeding record ID from farrowing record
        cursor.execute("""
            SELECT breeding_id FROM farrowing_records WHERE id = %s
        """, (farrowing_record_id,))
        
        breeding_record = cursor.fetchone()
        if not breeding_record:
            return jsonify({'success': False, 'message': 'Breeding record not found for this farrowing'})
        
        cursor.execute("""
            UPDATE breeding_records 
            SET notes = %s 
            WHERE id = %s
        """, (data['reason'], breeding_record['breeding_id']))
        
        # Log activity
        log_activity(session['employee_id'], 'LITTER_POSTPONED', 
                   f'Postponed litter registration for farrowing record {farrowing_record_id}. Reason: {data["reason"]}')
        
        conn.commit()
        cursor.close()
        conn.close()
        
        return jsonify({
            'success': True,
            'message': 'Litter registration postponed successfully'
        })
        
    except Exception as e:
        print(f"Error postponing litter registration: {str(e)}")
        return jsonify({'success': False, 'message': f'Failed to postpone litter registration: {str(e)}'})

# Breeding Management API Endpoints

@app.route('/api/breeding/available-sows', methods=['GET'])
def get_available_sows():
    """Get all sows available for breeding (breeding_status = 'available')"""
    if 'employee_id' not in session or session.get('employee_role') not in ['administrator', 'manager']:
        return jsonify({'error': 'Unauthorized'}), 401
    
    try:
        conn = get_db_connection()
        cursor = conn.cursor()
        
        # Get sows that are available for breeding, including breeding history metrics
        cursor.execute("""
            SELECT
                p.id,
                p.tag_id,
                p.breed,
                p.age_days,
                p.breeding_status,
                f.farm_name,
                (SELECT MAX(brm.mating_date) FROM breeding_records brm WHERE brm.sow_id = p.id) as last_breeding_date,
                (
                    SELECT
                        CASE
                            WHEN (
                                SELECT bmax.id FROM breeding_records bmax
                                WHERE bmax.sow_id = p.id
                                ORDER BY bmax.mating_date DESC, bmax.id DESC LIMIT 1
                            ) IS NULL THEN NULL
                            WHEN EXISTS (
                                SELECT 1 FROM farrowing_records fr
                                WHERE fr.breeding_id = (
                                    SELECT bmax.id FROM breeding_records bmax
                                    WHERE bmax.sow_id = p.id
                                    ORDER BY bmax.mating_date DESC, bmax.id DESC LIMIT 1
                                )
                            ) THEN 'completed'
                            WHEN EXISTS (
                                SELECT 1 FROM failed_conceptions fc
                                WHERE fc.sow_id = p.id
                                  AND fc.mating_date = (
                                    SELECT bmax.mating_date FROM breeding_records bmax
                                    WHERE bmax.sow_id = p.id
                                    ORDER BY bmax.mating_date DESC, bmax.id DESC LIMIT 1
                                  )
                                  AND fc.boar_id = (
                                    SELECT bmax.boar_id FROM breeding_records bmax
                                    WHERE bmax.sow_id = p.id
                                    ORDER BY bmax.mating_date DESC, bmax.id DESC LIMIT 1
                                  )
                            ) THEN 'failed'
                            ELSE 'unknown'
                        END
                ) as last_breeding_status,
                (SELECT COALESCE(COUNT(DISTINCT br2.id), 0) FROM breeding_records br2
                 INNER JOIN farrowing_records fr ON fr.breeding_id = br2.id
                 WHERE br2.sow_id = p.id) as successful_breedings,
                (SELECT COALESCE(COUNT(*), 0) FROM failed_conceptions fcx WHERE fcx.sow_id = p.id) as failed_breedings
            FROM pigs p
            LEFT JOIN farms f ON p.farm_id = f.id
            WHERE p.gender = 'female'
            AND p.pig_type = 'grown_pig'
            AND p.purpose = 'breeding'
            AND p.breeding_status = 'available'
            AND p.status = 'active'
            ORDER BY p.tag_id DESC
        """)
        sows = cursor.fetchall()
        
        cursor.close()
        conn.close()
        
        return jsonify({
            'success': True,
            'sows': sows
        })
        
    except Exception as e:
        print(f"Error getting available sows: {str(e)}")
        return jsonify({'error': str(e)}), 500

@app.route('/api/breeding/sow/<int:sow_id>/analytics', methods=['GET'])
def get_sow_breeding_analytics(sow_id):
    """Get breeding and litter analytics for one sow."""
    if 'employee_id' not in session or session.get('employee_role') not in ['administrator', 'manager']:
        return jsonify({'error': 'Unauthorized'}), 401

    try:
        conn = get_db_connection()
        cursor = conn.cursor()

        cursor.execute("""
            SELECT
                p.id,
                p.tag_id,
                p.breed,
                p.age_days,
                p.status as health_status,
                p.breeding_status,
                f.farm_name
            FROM pigs p
            LEFT JOIN farms f ON p.farm_id = f.id
            WHERE p.id = %s AND p.gender = 'female'
        """, (sow_id,))
        sow = cursor.fetchone()

        if not sow:
            cursor.close()
            conn.close()
            return jsonify({'success': False, 'message': 'Sow not found'})

        cursor.execute("""
            SELECT
                (SELECT COUNT(*) FROM breeding_records WHERE sow_id = %s) as total_breedings,
                (SELECT COALESCE(COUNT(DISTINCT br.id), 0)
                 FROM breeding_records br
                 INNER JOIN farrowing_records fr ON fr.breeding_id = br.id
                 WHERE br.sow_id = %s) as successful_breedings,
                (SELECT COALESCE(COUNT(*), 0) FROM failed_conceptions WHERE sow_id = %s) as failed_breedings,
                (SELECT CASE WHEN p.breeding_status IN ('served', 'pregnant') THEN 1 ELSE 0 END
                 FROM pigs p WHERE p.id = %s) as active_breedings,
                (SELECT MAX(mating_date) FROM breeding_records WHERE sow_id = %s) as last_breeding_date
        """, (sow_id, sow_id, sow_id, sow_id, sow_id))
        breeding_summary = cursor.fetchone()

        cursor.execute("""
            SELECT
                br.id,
                br.boar_id,
                br.mating_date,
                br.expected_due_date,
                br.notes,
                br.created_at,
                s.breeding_status,
                EXISTS(
                    SELECT 1 FROM farrowing_records fr
                    WHERE fr.breeding_id = br.id
                ) as has_farrowing,
                EXISTS(
                    SELECT 1 FROM failed_conceptions fc
                    WHERE fc.sow_id = br.sow_id AND fc.mating_date = br.mating_date AND fc.boar_id = br.boar_id
                ) as is_failed
            FROM breeding_records br
            JOIN pigs s ON s.id = br.sow_id
            WHERE br.sow_id = %s
            ORDER BY br.mating_date DESC, br.id DESC
        """, (sow_id,))
        breeding_records = cursor.fetchall()

        cursor.execute("""
            SELECT
                COUNT(*) as total_litters,
                COALESCE(SUM(total_piglets), 0) as total_piglets,
                COALESCE(SUM(alive_piglets), 0) as alive_piglets,
                COALESCE(SUM(still_births), 0) as still_births,
                ROUND(COALESCE(AVG(alive_piglets), 0), 2) as avg_alive_per_litter,
                MAX(farrowing_date) as last_farrowing_date
            FROM litters
            WHERE sow_id = %s
        """, (sow_id,))
        litter_summary = cursor.fetchone()

        cursor.execute("""
            SELECT
                id,
                litter_id,
                farrowing_date,
                total_piglets,
                alive_piglets,
                still_births,
                status,
                weaning_date,
                notes
            FROM litters
            WHERE sow_id = %s
            ORDER BY farrowing_date DESC, id DESC
        """, (sow_id,))
        litters = cursor.fetchall()

        cursor.close()
        conn.close()

        return jsonify({
            'success': True,
            'sow': sow,
            'breeding_summary': breeding_summary,
            'breeding_records': breeding_records,
            'litter_summary': litter_summary,
            'litters': litters
        })
    except Exception as e:
        print(f"Error getting sow breeding analytics: {str(e)}")
        return jsonify({'success': False, 'message': f'Failed to load sow analytics: {str(e)}'})

