def _coerce_sql_date(value):
    """Normalize DB date/datetime/str values to datetime.date."""
    if value is None:
        return None
    from datetime import datetime
    if isinstance(value, datetime):
        return value.date()
    if hasattr(value, 'year') and hasattr(value, 'month') and hasattr(value, 'day'):
        return value
    if isinstance(value, str) and value.strip():
        return datetime.strptime(value.split(' ')[0], '%Y-%m-%d').date()
    return None


def _breeding_record_cycle_maps(records):
    """Map each sow to its active open cycle and latest farrowed cycle."""
    latest_by_sow = {}
    for record in records or []:
        sow_id = record.get('sow_id')
        if sow_id is None:
            continue
        breeding_id = int(record['id'])
        latest_by_sow[sow_id] = max(latest_by_sow.get(sow_id, 0), breeding_id)

    active_open_by_sow = {}
    latest_farrowed_by_sow = {}
    for record in records or []:
        sow_id = record.get('sow_id')
        if sow_id is None:
            continue
        breeding_id = int(record['id'])
        if latest_by_sow.get(sow_id) != breeding_id:
            continue
        is_failed = bool(record.get('is_failed'))
        has_farrowing = bool(record.get('has_farrowing_record'))
        if not is_failed and not has_farrowing:
            active_open_by_sow[sow_id] = breeding_id
        if has_farrowing and not is_failed:
            latest_farrowed_by_sow[sow_id] = breeding_id
    return active_open_by_sow, latest_farrowed_by_sow


def _derive_breeding_record_status(record, today, active_open_by_sow, latest_farrowed_by_sow):
    """Return per-record status and whether it should appear on the active records view."""
    breeding_id = int(record['id'])
    sow_id = record.get('sow_id')
    is_failed = bool(record.get('is_failed'))
    has_farrowing = bool(record.get('has_farrowing_record'))

    if is_failed:
        return 'failed', True
    if active_open_by_sow.get(sow_id) == breeding_id:
        mating_date = _coerce_sql_date(record.get('mating_date'))
        if mating_date:
            days_since_mating = (today - mating_date).days
            return ('served' if days_since_mating <= 25 else 'pregnant'), True
        return 'served', True
    if has_farrowing and latest_farrowed_by_sow.get(sow_id) == breeding_id and not active_open_by_sow.get(sow_id):
        return 'farrowed', True
    return 'completed', False


@app.route('/api/breeding/register', methods=['POST'])
def register_breeding():
    """Register a new breeding record"""
    if 'employee_id' not in session or session.get('employee_role') not in ['administrator', 'manager']:
        return jsonify({'error': 'Unauthorized'}), 401
    
    try:
        data = request.get_json()
        sow_id = data.get('sow_id')
        boar_id = data.get('boar_id')
        mating_date = data.get('mating_date')
        notes = data.get('notes', '')
        
        # Validation
        if not all([sow_id, boar_id, mating_date]):
            return jsonify({'success': False, 'message': 'All fields are required'})
        
        conn = get_db_connection()
        cursor = conn.cursor()

        cursor.execute("""
            SELECT id, tag_id, breeding_status
            FROM pigs
            WHERE id = %s AND gender = 'female' AND pig_type = 'grown_pig'
            AND purpose = 'breeding' AND status = 'active'
            FOR UPDATE
        """, (sow_id,))
        sow = cursor.fetchone()

        if not sow:
            cursor.close()
            conn.close()
            return jsonify({'success': False, 'message': 'Selected sow was not found or is inactive'})

        if (sow.get('breeding_status') or '').lower() != 'available':
            cursor.close()
            conn.close()
            return jsonify({'success': False, 'message': 'Selected sow is not available for breeding'})

        cursor.execute("""
            SELECT br.id
            FROM breeding_records br
            WHERE br.sow_id = %s
              AND NOT EXISTS (
                  SELECT 1 FROM farrowing_records fr WHERE fr.breeding_id = br.id
              )
              AND NOT EXISTS (
                  SELECT 1 FROM failed_conceptions fc
                  WHERE fc.sow_id = br.sow_id
                    AND fc.mating_date = br.mating_date
                    AND fc.boar_id = br.boar_id
              )
            LIMIT 1
        """, (sow_id,))
        if cursor.fetchone():
            cursor.close()
            conn.close()
            return jsonify({
                'success': False,
                'message': 'This sow already has an active breeding cycle. Complete farrowing or record a failed conception before registering again.'
            })

        cursor.execute("""
            SELECT id
            FROM breeding_records
            WHERE sow_id = %s AND boar_id = %s AND mating_date = %s
            LIMIT 1
        """, (sow_id, boar_id, mating_date))
        if cursor.fetchone():
            cursor.close()
            conn.close()
            return jsonify({
                'success': False,
                'message': 'A breeding record already exists for this sow, boar, and mating date.'
            })
        
        # Verify boar exists and is male
        cursor.execute("""
            SELECT id, tag_id 
            FROM pigs 
            WHERE id = %s AND gender = 'male' AND pig_type = 'grown_pig' 
            AND purpose = 'breeding' AND status = 'active'
        """, (boar_id,))
        boar = cursor.fetchone()
        
        if not boar:
            return jsonify({'success': False, 'message': 'Selected boar is not valid'})
        
        # Calculate expected due date (114 days from mating)
        from datetime import datetime, timedelta
        mating_dt = datetime.strptime(mating_date, '%Y-%m-%d')
        expected_due_date = mating_dt + timedelta(days=114)
        
        # Insert breeding record
        cursor.execute("""
            INSERT INTO breeding_records (sow_id, boar_id, mating_date, expected_due_date, notes, created_by)
            VALUES (%s, %s, %s, %s, %s, %s)
        """, (sow_id, boar_id, mating_date, expected_due_date.date(), notes, session['employee_id']))
        
        breeding_id = cursor.lastrowid
        
        # Update sow's breeding status to 'served'
        cursor.execute("""
            UPDATE pigs 
            SET breeding_status = 'served' 
            WHERE id = %s
        """, (sow_id,))
        
        conn.commit()
        cursor.close()
        conn.close()
        
        # Log activity
        log_activity(session['employee_id'], 'BREEDING_REGISTRATION', 
                    f'Breeding record created: Sow {sow["tag_id"]} with Boar {boar["tag_id"]}')
        
        return jsonify({
            'success': True,
            'message': 'Breeding record registered successfully',
            'breeding_id': breeding_id,
            'expected_due_date': expected_due_date.date().isoformat()
        })
        
    except Exception as e:
        print(f"Breeding registration error: {str(e)}")
        import traceback
        traceback.print_exc()
        return jsonify({'success': False, 'message': f'Failed to register breeding: {str(e)}'})

@app.route('/api/breeding/list', methods=['GET'])
def get_breeding_records():
    """Get all breeding records with calculated status and days to farrowing"""
    if 'employee_id' not in session or session.get('employee_role') not in ['administrator', 'manager']:
        return jsonify({'error': 'Unauthorized'}), 401
    
    try:
        conn = get_db_connection()
        cursor = conn.cursor()

        reconcile_summary = reconcile_complete_farrowing_cycles(
            cursor, session.get('employee_id')
        )
        if reconcile_summary.get('updated'):
            conn.commit()

        # Get all breeding records with pig and farm information
        cursor.execute("""
            SELECT br.id, br.sow_id, br.boar_id, br.mating_date, br.expected_due_date, br.notes,
                   br.created_by, br.created_at, br.updated_at,
                   sow.tag_id as sow_tag_id, sow.breed as sow_breed, sow.breeding_status as sow_breeding_status,
                   boar.tag_id as boar_tag_id, boar.breed as boar_breed,
                   e.full_name as created_by_name,
                   (
                       SELECT MAX(fr.farrowing_date)
                       FROM farrowing_records fr
                       WHERE fr.breeding_id = br.id
                   ) AS last_farrowing_date,
                   EXISTS(
                       SELECT 1
                       FROM farrowing_records fr
                       WHERE fr.breeding_id = br.id
                   ) AS has_farrowing_record,
                   EXISTS(
                       SELECT 1
                       FROM farrowing_records fr
                       JOIN litters l ON l.farrowing_record_id = fr.id
                       WHERE fr.breeding_id = br.id
                   ) AS has_registered_litter,
                   (
                       SELECT l.status
                       FROM farrowing_records fr
                       JOIN litters l ON l.farrowing_record_id = fr.id
                       WHERE fr.breeding_id = br.id
                       ORDER BY fr.farrowing_date DESC, l.id DESC
                       LIMIT 1
                   ) AS current_litter_status,
                   EXISTS(
                       SELECT 1
                       FROM failed_conceptions fc
                       WHERE fc.sow_id = br.sow_id
                         AND fc.mating_date = br.mating_date
                         AND fc.boar_id = br.boar_id
                   ) AS is_failed
            FROM breeding_records br
            LEFT JOIN pigs sow ON br.sow_id = sow.id
            LEFT JOIN pigs boar ON br.boar_id = boar.id
            LEFT JOIN employees e ON br.created_by = e.id
            ORDER BY br.created_at DESC, br.id DESC
        """)
        records = cursor.fetchall()

        # Use farrowing activity settings "days" (due_day) as serving recovery window.
        # If no template is set, fallback to 21 days.
        cursor.execute("""
            SELECT COALESCE(MAX(due_day), 21) AS serving_recovery_days
            FROM farrowing_activity_templates
            WHERE is_active = 1
        """)
        recovery_cfg = cursor.fetchone() or {}
        serving_recovery_days = int(recovery_cfg.get('serving_recovery_days') or 21)
        
        from datetime import datetime, timedelta
        today = datetime.now().date()

        active_open_by_sow, latest_farrowed_by_sow = _breeding_record_cycle_maps(records)

        # Promote served -> pregnant only for each sow's active open breeding cycle.
        for record in records:
            breeding_id = int(record['id'])
            if active_open_by_sow.get(record.get('sow_id')) != breeding_id:
                continue
            st = (record.get('sow_breeding_status') or '').lower()
            mating_date = _coerce_sql_date(record.get('mating_date'))
            if not mating_date or st != 'served':
                continue
            if (today - mating_date).days > 25:
                cursor.execute("""
                    UPDATE pigs
                    SET breeding_status = 'pregnant'
                    WHERE id = %s
                """, (record['sow_id'],))
                record['sow_breeding_status'] = 'pregnant'

        conn.commit()

        processed_records = []
        for record in records:
            record_dict = dict(record)
            is_failed = bool(record.get('is_failed'))
            record_status, is_current_cycle = _derive_breeding_record_status(
                record, today, active_open_by_sow, latest_farrowed_by_sow
            )
            record_dict['breeding_status'] = record_status
            record_dict['sow_breeding_status'] = (record.get('sow_breeding_status') or '') or None
            record_dict['is_current_cycle'] = is_current_cycle
            record_dict['is_failed'] = is_failed
            record_dict['breeding_ref'] = f"BR-{int(record['id']):05d}"
            record_dict['has_farrowing_record'] = bool(record.get('has_farrowing_record'))
            record_dict['has_registered_litter'] = bool(record.get('has_registered_litter'))
            record_dict['current_litter_status'] = (record.get('current_litter_status') or '').lower() or None
            last_farrowing = _coerce_sql_date(record.get('last_farrowing_date'))
            record_dict['last_farrowing_date'] = last_farrowing.strftime('%Y-%m-%d') if last_farrowing else None
            record_dict['actual_farrowing_date'] = record_dict['last_farrowing_date']
            
            mating_date = _coerce_sql_date(record.get('mating_date'))
            if mating_date:
                record_dict['mating_date'] = mating_date.strftime('%Y-%m-%d')

                stored_due = _coerce_sql_date(record.get('expected_due_date'))
                if not stored_due:
                    stored_due = mating_date + timedelta(days=114)

                record_dict['expected_due_date'] = stored_due.strftime('%Y-%m-%d')
                days_to_farrowing = (stored_due - today).days
                
                days_since_mating = (today - mating_date).days
                if (
                    is_current_cycle
                    and record_status == 'served'
                    and not is_failed
                    and days_since_mating <= 25
                ):
                    record_dict['can_cancel'] = True
                    record_dict['days_remaining_to_cancel'] = 25 - days_since_mating
                else:
                    record_dict['can_cancel'] = False
                    record_dict['days_remaining_to_cancel'] = 0
                
                if is_current_cycle and record_status in ('served', 'pregnant') and not is_failed:
                    record_dict['days_to_farrowing'] = days_to_farrowing
                else:
                    record_dict['days_to_farrowing'] = None
            else:
                record_dict['can_cancel'] = False
                record_dict['days_to_farrowing'] = None
                record_dict['expected_due_date'] = None

            record_dict['days_left_to_serve'] = None
            if is_current_cycle and record_status == 'farrowed':
                farrowing_date = _coerce_sql_date(record.get('last_farrowing_date'))
                if not farrowing_date and record_dict.get('expected_due_date'):
                    farrowing_date = _coerce_sql_date(record_dict.get('expected_due_date'))
                if farrowing_date:
                    days_since_farrowing = (today - farrowing_date).days
                    remaining_days = serving_recovery_days - days_since_farrowing
                    record_dict['days_left_to_serve'] = remaining_days if remaining_days > 0 else 0
                else:
                    record_dict['days_left_to_serve'] = 0
            record_dict['serving_recovery_window_days'] = serving_recovery_days

            days_to_farrow = record_dict.get('days_to_farrowing')
            record_dict['can_register_farrowing'] = (
                is_current_cycle
                and not is_failed
                and record_status in ('served', 'pregnant')
                and not record_dict['has_registered_litter']
                and not record_dict['has_farrowing_record']
                and days_to_farrow is not None
                and int(days_to_farrow) <= 7
            )
            
            processed_records.append(record_dict)
        
        cursor.close()
        conn.close()
        
        return jsonify({
            'success': True,
            'records': processed_records,
            'reconcile': reconcile_summary,
        })
        
    except Exception as e:
        print(f"Error getting breeding records: {str(e)}")
        return jsonify({'error': str(e)}), 500


@app.route('/api/breeding/cancel/<int:breeding_id>', methods=['POST'])
def cancel_breeding(breeding_id):
    """Cancel a breeding record and mark it as failed (within 25 days)."""
    if 'employee_id' not in session or session.get('employee_role') not in ['administrator', 'manager']:
        return jsonify({'error': 'Unauthorized'}), 401
    
    try:
        data = request.get_json()
        reason = data.get('reason', 'No reason provided')
        
        conn = get_db_connection()
        cursor = conn.cursor()
        
        # Get breeding record
        cursor.execute("""
            SELECT br.*, sow.tag_id as sow_tag_id, sow.breeding_status
            FROM breeding_records br
            LEFT JOIN pigs sow ON br.sow_id = sow.id
            WHERE br.id = %s
        """, (breeding_id,))
        record = cursor.fetchone()
        
        if not record:
            return jsonify({'success': False, 'message': 'Breeding record not found'})
        
        # Check if within 25 days of mating
        from datetime import datetime
        mating_date = record['mating_date']
        days_since_mating = (datetime.now().date() - mating_date).days
        
        if days_since_mating > 25:  # More than 25 days since mating = pregnant
            return jsonify({'success': False, 'message': 'Cannot cancel breeding after 25 days from mating'})
        
        # Record failed conception history
        cursor.execute("""
            INSERT INTO failed_conceptions (sow_id, boar_id, mating_date, failure_date, failure_reason, notes, created_by)
            VALUES (%s, %s, %s, %s, %s, %s, %s)
        """, (record['sow_id'], record['boar_id'], record['mating_date'], datetime.now().date(), reason, record['notes'] or '', session['employee_id']))
        
        cursor.execute("""
            UPDATE breeding_records
            SET notes = CASE
                    WHEN notes IS NULL OR notes = '' THEN %s
                    ELSE CONCAT(notes, '\n', %s)
                END,
                updated_at = CURRENT_TIMESTAMP
            WHERE id = %s
        """, (f"Failure reason: {reason}", f"Failure reason: {reason}", breeding_id))
        
        # Update sow's breeding status back to available
        cursor.execute("""
            UPDATE pigs 
            SET breeding_status = 'available' 
            WHERE id = %s
        """, (record['sow_id'],))
        
        conn.commit()
        cursor.close()
        conn.close()
        
        # Log activity
        log_activity(session['employee_id'], 'BREEDING_CANCELLATION', 
                    f'Breeding cancelled: Sow {record["sow_tag_id"]} - Reason: {reason}')
        
        return jsonify({
            'success': True,
            'message': 'Breeding record cancelled and marked as failed successfully'
        })
        
    except Exception as e:
        print(f"Breeding cancellation error: {str(e)}")
        import traceback
        traceback.print_exc()
        return jsonify({'success': False, 'message': f'Failed to cancel breeding: {str(e)}'})

@app.route('/api/breeding/failed-conceptions', methods=['GET'])
def get_failed_conceptions():
    """Get all failed conceptions (failed_conceptions + matching breeding_records notes)."""
    if 'employee_id' not in session or session.get('employee_role') not in ['administrator', 'manager']:
        return jsonify({'error': 'Unauthorized'}), 401
    
    try:
        conn = get_db_connection()
        cursor = conn.cursor()
        
        cursor.execute("""
            SELECT
                br.id,
                br.sow_id,
                br.boar_id,
                br.mating_date,
                COALESCE(fc.failure_date, DATE(br.updated_at)) as failure_date,
                COALESCE(
                    NULLIF(TRIM(fc.failure_reason), ''),
                    CASE
                        WHEN br.notes LIKE '%%Failure reason:%%' THEN
                            TRIM(SUBSTRING_INDEX(br.notes, 'Failure reason:', -1))
                        ELSE 'Not conceived after serving'
                    END
                ) as failure_reason,
                br.notes,
                br.created_by,
                br.created_at,
                br.updated_at,
                sow.tag_id as sow_tag_id, sow.breed as sow_breed,
                boar.tag_id as boar_tag_id, boar.breed as boar_breed,
                e.full_name as created_by_name
            FROM failed_conceptions fc
            INNER JOIN breeding_records br
                ON br.sow_id = fc.sow_id
                AND br.mating_date = fc.mating_date
                AND br.boar_id = fc.boar_id
            LEFT JOIN pigs sow ON br.sow_id = sow.id
            LEFT JOIN pigs boar ON br.boar_id = boar.id
            LEFT JOIN employees e ON br.created_by = e.id
            ORDER BY fc.failure_date DESC, br.id DESC
        """)
        records = cursor.fetchall()
        
        cursor.close()
        conn.close()
        
        return jsonify({
            'success': True,
            'records': records
        })
        
    except Exception as e:
        print(f"Error getting failed conceptions: {str(e)}")
        return jsonify({'error': str(e)}), 500

@app.route('/api/breeding/<int:breeding_id>/edit', methods=['PUT'])
def edit_breeding_record(breeding_id):
    """Edit a breeding record"""
    if 'employee_id' not in session or session.get('employee_role') not in ['administrator', 'manager']:
        return jsonify({'error': 'Unauthorized'}), 401
    
    try:
        data = request.get_json()
        mating_date = data.get('mating_date')
        expected_due_date = data.get('expected_due_date')
        breeding_status = (data.get('breeding_status') or '').lower() or None
        actual_farrowing_date = data.get('actual_farrowing_date') or None

        if not mating_date:
            return jsonify({'success': False, 'message': 'Mating date is required'})

        # Validate actual farrowing date if provided
        if actual_farrowing_date:
            try:
                af_dt = datetime.strptime(actual_farrowing_date, '%Y-%m-%d').date()
                m_dt = datetime.strptime(mating_date, '%Y-%m-%d').date() if isinstance(mating_date, str) else mating_date
                if af_dt < m_dt:
                    return jsonify({'success': False, 'message': 'Actual farrowing date cannot be earlier than the mating date'})
                if af_dt > datetime.now().date():
                    return jsonify({'success': False, 'message': 'Actual farrowing date cannot be in the future'})
            except ValueError:
                return jsonify({'success': False, 'message': 'Invalid actual farrowing date format'})

        conn = get_db_connection()
        cursor = conn.cursor()

        cursor.execute("""
            UPDATE breeding_records
            SET mating_date = %s, expected_due_date = %s, updated_at = NOW()
            WHERE id = %s
        """, (mating_date, expected_due_date, breeding_id))

        # If user updated the actual farrowing date, sync the related
        # farrowing_records and litters rows so all UIs stay consistent.
        if actual_farrowing_date:
            cursor.execute("""
                UPDATE farrowing_records
                SET farrowing_date = %s
                WHERE breeding_id = %s
            """, (actual_farrowing_date, breeding_id))

            cursor.execute("""
                UPDATE litters l
                JOIN farrowing_records fr ON fr.id = l.farrowing_record_id
                SET l.farrowing_date = %s
                WHERE fr.breeding_id = %s
            """, (actual_farrowing_date, breeding_id))

            # Farrowing Activities UI uses farrowing_activities.due_date; keep it
            # aligned with actual farrowing date + due_day (same as at registration).
            resync_farrowing_activity_due_dates_for_breeding(cursor, breeding_id, actual_farrowing_date)
        
        # Optional: update sow (pigs.breeding_status). UI may pass legacy values
        # like "completed" from older clients. We intentionally do NOT flip the
        # sow to 'available' from this endpoint, because availability after a
        # farrowed cycle must be gated on farrowing_cycle_ready_for_sow_available
        # (all activities done AND litter weaned). Legacy "completed/cancelled/
        # failed" payloads are therefore ignored here; use the proper cancel,
        # delete, or mark-available endpoints instead.
        if breeding_status:
            if breeding_status in ('cancelled', 'failed', 'completed', 'available'):
                # Look up the sow's current status so we can decide safely.
                cursor.execute("""
                    SELECT p.id AS sow_id, p.breeding_status
                    FROM breeding_records br
                    JOIN pigs p ON p.id = br.sow_id
                    WHERE br.id = %s
                """, (breeding_id,))
                sow_row = cursor.fetchone()
                if sow_row and sow_row['breeding_status'] != 'farrowed':
                    # Safe: sow isn't in an active farrowing cycle, allow the reset.
                    cursor.execute("""
                        UPDATE pigs
                        SET breeding_status = 'available'
                        WHERE id = %s
                    """, (sow_row['sow_id'],))
                # If the sow IS 'farrowed', ignore the legacy reset; the cycle
                # must complete via maybe_mark_sow_available_after_farrowing_cycle.
            elif breeding_status in ('served', 'pregnant', 'farrowed', 'young'):
                cursor.execute("""
                    UPDATE pigs
                    SET breeding_status = %s
                    WHERE id = (SELECT sow_id FROM breeding_records WHERE id = %s)
                """, (breeding_status, breeding_id))
        
        conn.commit()
        cursor.close()
        conn.close()
        
        # Log activity
        log_activity(session['employee_id'], 'BREEDING_EDIT', 
                    f'Breeding record {breeding_id} updated')
        
        return jsonify({
            'success': True,
            'message': 'Breeding record updated successfully'
        })
        
    except Exception as e:
        print(f"Error updating breeding record: {str(e)}")
        return jsonify({'success': False, 'message': f'Failed to update breeding record: {str(e)}'})

@app.route('/api/breeding/<int:breeding_id>/delete', methods=['DELETE'])
def delete_breeding_record(breeding_id):
    """Delete a breeding record and set sow status to available"""
    if 'employee_id' not in session or session.get('employee_role') not in ['administrator', 'manager']:
        return jsonify({'error': 'Unauthorized'}), 401
    
    conn = None
    cursor = None
    try:
        conn = get_db_connection()
        cursor = conn.cursor()
        
        # Get breeding record details for logging
        cursor.execute("""
            SELECT br.sow_id, p.tag_id as sow_tag_id
            FROM breeding_records br
            LEFT JOIN pigs p ON br.sow_id = p.id
            WHERE br.id = %s
        """, (breeding_id,))
        
        record = cursor.fetchone()
        if not record:
            return jsonify({'success': False, 'message': 'Breeding record not found'})
        
        # Update sow breeding status to available
        cursor.execute("""
            UPDATE pigs 
            SET breeding_status = 'available' 
            WHERE id = %s
        """, (record['sow_id'],))
        
        # Delete related litters first (they reference farrowing_records)
        cursor.execute("""
            DELETE l FROM litters l 
            JOIN farrowing_records fr ON l.farrowing_record_id = fr.id 
            WHERE fr.breeding_id = %s
        """, (breeding_id,))
        print(f"Deleted litters for breeding record {breeding_id}")

        # Delete related farrowing activities first (they reference farrowing_records)
        cursor.execute("""
            DELETE fa FROM farrowing_activities fa
            JOIN farrowing_records fr ON fa.farrowing_record_id = fr.id
            WHERE fr.breeding_id = %s
        """, (breeding_id,))
        print(f"Deleted farrowing activities for breeding record {breeding_id}")
        
        # Delete related farrowing records (they reference breeding_records)
        cursor.execute("DELETE FROM farrowing_records WHERE breeding_id = %s", (breeding_id,))
        print(f"Deleted farrowing records for breeding record {breeding_id}")

        # Delete breeding record
        cursor.execute("DELETE FROM breeding_records WHERE id = %s", (breeding_id,))
        
        conn.commit()
        
        # Log activity
        log_activity(session['employee_id'], 'BREEDING_DELETE', 
                    f'Breeding record {breeding_id} deleted for sow {record["sow_tag_id"]}')
        
        return jsonify({
            'success': True,
            'message': 'Breeding record deleted successfully. Sow is now available for breeding.'
        })
        
    except Exception as e:
        if conn:
            conn.rollback()
        print(f"Error deleting breeding record: {str(e)}")
        return jsonify({'success': False, 'message': f'Failed to delete breeding record: {str(e)}'})
    finally:
        if cursor:
            cursor.close()
        if conn:
            conn.close()

@app.route('/api/breeding/completed-farrowings', methods=['GET'])
def get_completed_farrowings():
    """Get all completed farrowing records with unweaned litters only"""
    if 'employee_id' not in session or session.get('employee_role') not in ['administrator', 'manager']:
        return jsonify({'error': 'Unauthorized'}), 401
    
    try:
        conn = get_db_connection()
        cursor = conn.cursor()
        reconcile_summary = {
            'checked': 0, 'updated': 0,
            'litters_weaned': [], 'sows_available': [], 'messages': [],
        }
        
        # Ensure we're using the correct database
        cursor.execute(f"USE {DB_CONFIG['database']}")
        
        # Try to ensure tables exist - use a simple approach
        table_created = False
        try:
            # Try a simple query to check if table exists
            cursor.execute("SELECT 1 FROM farrowing_records LIMIT 1")
        except Exception as table_error:
            # Table doesn't exist, create it
            error_str = str(table_error).lower()
            if "doesn't exist" in error_str or "table" in error_str or "1932" in str(table_error):
                print(f"Table doesn't exist, creating it. Error: {str(table_error)}")
                try:
                    # Ensure we're in the right database
                    cursor.execute(f"USE {DB_CONFIG['database']}")
                    
                    # First, check if table already exists using SHOW TABLES
                    cursor.execute("SHOW TABLES LIKE 'farrowing_records'")
                    existing_table = cursor.fetchone()
                    if existing_table:
                        print("Table farrowing_records found in SHOW TABLES")
                        # Try to query it to see if it's actually accessible
                        try:
                            cursor.execute("SELECT 1 FROM farrowing_records LIMIT 1")
                            print("Table is accessible")
                            table_created = True
                        except Exception as access_error:
                            # Table exists in metadata but is corrupted (error 1932)
                            if "1932" in str(access_error) or "doesn't exist in engine" in str(access_error).lower():
                                print(f"Table exists but is corrupted (error 1932). Dropping and recreating...")
                                try:
                                    # Disable foreign key checks to allow dropping the corrupted table
                                    cursor.execute("SET FOREIGN_KEY_CHECKS = 0")
                                    # Drop dependent tables first
                                    cursor.execute("DROP TABLE IF EXISTS farrowing_records_edit_history")
                                    cursor.execute("DROP TABLE IF EXISTS farrowing_activities")
                                    cursor.execute("DROP TABLE IF EXISTS litters")
                                    # Now drop the corrupted table
                                    cursor.execute("DROP TABLE IF EXISTS farrowing_records")
                                    # Re-enable foreign key checks
                                    cursor.execute("SET FOREIGN_KEY_CHECKS = 1")
                                    conn.commit()
                                    print("Dropped corrupted table and dependent tables")
                                    # Fall through to create it again
                                    existing_table = None
                                    table_created = False
                                except Exception as drop_error:
                                    print(f"Error dropping corrupted table: {str(drop_error)}")
                                    # Try to re-enable foreign key checks even if drop failed
                                    try:
                                        cursor.execute("SET FOREIGN_KEY_CHECKS = 1")
                                    except:
                                        pass
                                    raise drop_error
                            else:
                                print(f"Table exists but query failed: {str(access_error)}")
                                raise access_error
                    
                    if not existing_table or not table_created:
                        # Create farrowing_records table
                        print("Attempting to create farrowing_records table...")
                        create_sql = """
                            CREATE TABLE farrowing_records (
                                id INT AUTO_INCREMENT PRIMARY KEY,
                                breeding_id INT NOT NULL,
                                farrowing_date DATE NOT NULL,
                                alive_piglets INT NOT NULL,
                                still_births INT NOT NULL,
                                dead_piglets INT DEFAULT 0,
                                weak_piglets INT DEFAULT 0,
                                avg_weight DECIMAL(5,2) NOT NULL,
                                health_notes TEXT,
                                notes TEXT,
                                created_by INT NOT NULL,
                                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                                updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
                                FOREIGN KEY (breeding_id) REFERENCES breeding_records(id),
                                FOREIGN KEY (created_by) REFERENCES employees(id),
                                UNIQUE KEY uniq_farrowing_breeding_id (breeding_id)
                            ) ENGINE=InnoDB
                        """
                        try:
                            cursor.execute(create_sql)
                            conn.commit()
                            print("CREATE TABLE executed successfully")
                        except Exception as create_exec_error:
                            print(f"CREATE TABLE failed with error: {str(create_exec_error)}")
                            raise create_exec_error
                        
                        # Verify table was created using SHOW TABLES
                        cursor.execute("SHOW TABLES LIKE 'farrowing_records'")
                        verify_result = cursor.fetchone()
                        if verify_result:
                            print("Table verified using SHOW TABLES")
                            table_created = True
                        else:
                            print("Table not found after creation using SHOW TABLES")
                            # Try without foreign keys
                            raise Exception("Table not found after creation with foreign keys")
                except Exception as create_error:
                    print(f"Error creating farrowing_records table with foreign keys: {str(create_error)}")
                    # Try without foreign keys if that's the issue
                    try:
                        cursor.execute(f"USE {DB_CONFIG['database']}")
                        print("Attempting to create table without foreign keys...")
                        
                        # If table already exists error, drop it first with FK checks disabled
                        if "1050" in str(create_error) or "already exists" in str(create_error).lower():
                            print("Table already exists, dropping it first...")
                            cursor.execute("SET FOREIGN_KEY_CHECKS = 0")
                            cursor.execute("DROP TABLE IF EXISTS farrowing_records_edit_history")
                            cursor.execute("DROP TABLE IF EXISTS farrowing_activities")
                            cursor.execute("DROP TABLE IF EXISTS litters")
                            cursor.execute("DROP TABLE IF EXISTS farrowing_records")
                            cursor.execute("SET FOREIGN_KEY_CHECKS = 1")
                            conn.commit()
                            print("Dropped existing table")
                        
                        create_sql_no_fk = """
                            CREATE TABLE farrowing_records (
                                id INT AUTO_INCREMENT PRIMARY KEY,
                                breeding_id INT NOT NULL UNIQUE,
                                farrowing_date DATE NOT NULL,
                                alive_piglets INT NOT NULL,
                                still_births INT NOT NULL,
                                dead_piglets INT DEFAULT 0,
                                weak_piglets INT DEFAULT 0,
                                avg_weight DECIMAL(5,2) NOT NULL,
                                health_notes TEXT,
                                notes TEXT,
                                created_by INT NOT NULL,
                                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                                updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
                            ) ENGINE=InnoDB
                        """
                        try:
                            cursor.execute(create_sql_no_fk)
                            conn.commit()
                            print("CREATE TABLE (no FK) executed successfully")
                        except Exception as create_exec_error2:
                            print(f"CREATE TABLE (no FK) failed: {str(create_exec_error2)}")
                            raise create_exec_error2
                        
                        # Verify using SHOW TABLES
                        cursor.execute("SHOW TABLES LIKE 'farrowing_records'")
                        verify_result2 = cursor.fetchone()
                        if verify_result2:
                            print("Table created and verified without foreign keys")
                            table_created = True
                        else:
                            print("Table still not found after creation without foreign keys")
                            # Check what database we're actually using
                            try:
                                cursor.execute("SELECT DATABASE() as current_db")
                                db_result = cursor.fetchone()
                                print(f"Current database: {db_result.get('current_db') if db_result else 'None'}")
                                # List all tables
                                cursor.execute("SHOW TABLES")
                                all_tables = cursor.fetchall()
                                print(f"All tables in database: {all_tables}")
                            except Exception as debug_error:
                                print(f"Debug query failed: {str(debug_error)}")
                    except Exception as create_error2:
                        print(f"Error creating table even without foreign keys: {str(create_error2)}")
                
                # If table was just created, close and reopen connection
                if table_created:
                    cursor.close()
                    conn.close()
                    conn = get_db_connection()
                    cursor = conn.cursor()
                    cursor.execute(f"USE {DB_CONFIG['database']}")
        
        # Check if farrowing_records_edit_history table exists
        try:
            cursor.execute("SELECT 1 FROM farrowing_records_edit_history LIMIT 1")
        except Exception as history_error:
            error_str = str(history_error).lower()
            if "doesn't exist" in error_str or "table" in error_str or "1932" in str(history_error):
                print(f"History table doesn't exist, creating it. Error: {str(history_error)}")
                try:
                    cursor.execute("""
                        CREATE TABLE IF NOT EXISTS farrowing_records_edit_history (
                            id INT AUTO_INCREMENT PRIMARY KEY,
                            record_id INT NOT NULL,
                            edited_by INT NOT NULL,
                            edited_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                            old_values TEXT,
                            new_values TEXT,
                            FOREIGN KEY (record_id) REFERENCES farrowing_records(id) ON DELETE CASCADE,
                            FOREIGN KEY (edited_by) REFERENCES employees(id)
                        )
                    """)
                    conn.commit()
                    print("Successfully created farrowing_records_edit_history table")
                except Exception as create_error:
                    print(f"Error creating history table: {str(create_error)}")
                    # Try without foreign keys
                    try:
                        cursor.execute("""
                            CREATE TABLE IF NOT EXISTS farrowing_records_edit_history (
                                id INT AUTO_INCREMENT PRIMARY KEY,
                                record_id INT NOT NULL,
                                edited_by INT NOT NULL,
                                edited_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                                old_values TEXT,
                                new_values TEXT
                            )
                        """)
                        conn.commit()
                        print("Created history table without foreign keys")
                    except Exception as create_error2:
                        print(f"Error creating history table even without foreign keys: {str(create_error2)}")
        
        # Verify table exists before querying - use SHOW TABLES
        table_verified = False
        try:
            # Ensure we're using the correct database
            cursor.execute(f"USE {DB_CONFIG['database']}")
            # Check current database
            cursor.execute("SELECT DATABASE() as current_db")
            db_check = cursor.fetchone()
            current_db = db_check.get('current_db') if db_check else None
            print(f"Verifying table in database: {current_db} (expected: {DB_CONFIG['database']})")
            
            # Check if table exists using SHOW TABLES
            cursor.execute("SHOW TABLES LIKE 'farrowing_records'")
            table_check = cursor.fetchone()
            if table_check:
                print("Table found using SHOW TABLES")
                # Try a simple query to verify it's actually accessible
                try:
                    cursor.execute("SELECT COUNT(*) as count FROM farrowing_records")
                    table_verified = True
                    print("Table verified successfully")
                except Exception as query_error:
                    # Table exists in metadata but is corrupted
                    if "1932" in str(query_error) or "doesn't exist in engine" in str(query_error).lower():
                        print(f"Table is corrupted (error 1932). Attempting to fix...")
                        try:
                            # Disable foreign key checks
                            cursor.execute("SET FOREIGN_KEY_CHECKS = 0")
                            # Drop dependent tables first
                            cursor.execute("DROP TABLE IF EXISTS farrowing_records_edit_history")
                            cursor.execute("DROP TABLE IF EXISTS farrowing_activities")
                            cursor.execute("DROP TABLE IF EXISTS litters")
                            # Drop the corrupted table
                            cursor.execute("DROP TABLE IF EXISTS farrowing_records")
                            # Re-enable foreign key checks
                            cursor.execute("SET FOREIGN_KEY_CHECKS = 1")
                            conn.commit()
                            print("Dropped corrupted table and dependent tables, will need to recreate on next request")
                            table_verified = False
                            records = []
                        except Exception as drop_error:
                            print(f"Error dropping corrupted table: {str(drop_error)}")
                            # Try to re-enable foreign key checks even if drop failed
                            try:
                                cursor.execute("SET FOREIGN_KEY_CHECKS = 1")
                            except:
                                pass
                            table_verified = False
                            records = []
                    else:
                        print(f"Query error: {str(query_error)}")
                        table_verified = False
                        records = []
            else:
                print("Table not found using SHOW TABLES")
                table_verified = False
                records = []
        except Exception as verify_error:
            print(f"Table verification failed: {str(verify_error)}")
            # Check if we're in the right database
            try:
                cursor.execute("SELECT DATABASE() as current_db")
                db_check = cursor.fetchone()
                current_db = db_check.get('current_db') if db_check else None
                print(f"Current database during error: {current_db}")
                # List all tables to see what exists
                cursor.execute("SHOW TABLES")
                all_tables = cursor.fetchall()
                print(f"All tables in database: {all_tables}")
            except Exception as debug_error:
                print(f"Debug query failed: {str(debug_error)}")
            
            # Try one more time with a fresh connection
            try:
                cursor.close()
                conn.close()
                conn = get_db_connection()
                cursor = conn.cursor()
                cursor.execute(f"USE {DB_CONFIG['database']}")
                # Double-check we're in the right database
                cursor.execute("SELECT DATABASE() as current_db")
                db_check = cursor.fetchone()
                print(f"Reconnected to database: {db_check.get('current_db') if db_check else 'None'}")
                cursor.execute("SHOW TABLES LIKE 'farrowing_records'")
                table_check = cursor.fetchone()
                if table_check:
                    cursor.execute("SELECT COUNT(*) as count FROM farrowing_records")
                    table_verified = True
                    print("Table verified after reconnection")
                else:
                    print("Table still not found after reconnection")
                    table_verified = False
                    records = []
            except Exception as retry_error:
                print(f"Table verification failed after retry: {str(retry_error)}")
                table_verified = False
                records = []
        
        # Check if litters table exists, create if missing
        try:
            cursor.execute("SELECT 1 FROM litters LIMIT 1")
        except Exception as litters_error:
            error_str = str(litters_error).lower()
            if "doesn't exist" in error_str or "table" in error_str or "1146" in str(litters_error):
                print(f"Litters table doesn't exist, creating it. Error: {str(litters_error)}")
                try:
                    cursor.execute(f"USE {DB_CONFIG['database']}")
                    cursor.execute("""
                        CREATE TABLE IF NOT EXISTS litters (
                            id INT AUTO_INCREMENT PRIMARY KEY,
                            litter_id VARCHAR(20) UNIQUE NOT NULL,
                            farrowing_record_id INT NOT NULL,
                            sow_id INT NOT NULL,
                            boar_id INT,
                            farrowing_date DATE NOT NULL,
                            total_piglets INT NOT NULL,
                            alive_piglets INT NOT NULL,
                            still_births INT DEFAULT 0,
                            avg_weight DECIMAL(5,2),
                            weaning_weight DECIMAL(5,2),
                            weaning_date DATE,
                            status ENUM('unweaned', 'weaned', 'sold', 'deceased', 'dead', 'slaughtered') DEFAULT 'unweaned',
                            notes TEXT,
                            created_by INT NOT NULL,
                            created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                            updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
                            FOREIGN KEY (farrowing_record_id) REFERENCES farrowing_records(id),
                            FOREIGN KEY (sow_id) REFERENCES pigs(id),
                            FOREIGN KEY (boar_id) REFERENCES pigs(id),
                            FOREIGN KEY (created_by) REFERENCES employees(id)
                        ) ENGINE=InnoDB
                    """)
                    conn.commit()
                    print("Successfully created litters table")
                except Exception as create_litters_error:
                    print(f"Error creating litters table: {str(create_litters_error)}")
                    # Try without foreign keys
                    try:
                        cursor.execute("""
                            CREATE TABLE IF NOT EXISTS litters (
                                id INT AUTO_INCREMENT PRIMARY KEY,
                                litter_id VARCHAR(20) UNIQUE NOT NULL,
                                farrowing_record_id INT NOT NULL,
                                sow_id INT NOT NULL,
                                boar_id INT,
                                farrowing_date DATE NOT NULL,
                                total_piglets INT NOT NULL,
                                alive_piglets INT NOT NULL,
                                still_births INT DEFAULT 0,
                                avg_weight DECIMAL(5,2),
                                weaning_weight DECIMAL(5,2),
                                weaning_date DATE,
                                status ENUM('unweaned', 'weaned', 'sold', 'deceased', 'dead', 'slaughtered') DEFAULT 'unweaned',
                                notes TEXT,
                                created_by INT NOT NULL,
                                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                                updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
                            ) ENGINE=InnoDB
                        """)
                        conn.commit()
                        print("Created litters table without foreign keys")
                    except Exception as create_litters_error2:
                        print(f"Error creating litters table even without foreign keys: {str(create_litters_error2)}")
        
        # Get completed farrowing records with unweaned litters only
        # Strict filter: only rows that already have an unweaned litter record
        if table_verified:
            try:
                # Ensure we're using the correct database
                cursor.execute(f"USE {DB_CONFIG['database']}")
                reconcile_summary = reconcile_complete_farrowing_cycles(
                    cursor, session.get('employee_id')
                )
                if reconcile_summary.get('updated'):
                    conn.commit()
                sync_unweaned_farrowing_activities_from_templates(cursor)
                conn.commit()
                cursor.execute("""
                    SELECT fr.id, fr.breeding_id, fr.farrowing_date, fr.alive_piglets, fr.still_births,
                           fr.dead_piglets, fr.weak_piglets, fr.avg_weight, fr.health_notes, fr.notes,
                           fr.created_by, fr.created_at, fr.updated_at,
                           br.mating_date,
                           sow.tag_id as sow_tag_id, sow.breed as sow_breed,
                           sow.breeding_status as sow_breeding_status, sow.status as sow_status,
                           boar.tag_id as boar_tag_id, boar.breed as boar_breed,
                           e.full_name as created_by_name,
                           l.litter_id, l.total_piglets, l.alive_piglets as litter_alive_piglets, l.still_births as litter_still_births,
                           l.avg_weight as litter_avg_weight, l.weaning_weight, l.weaning_date, l.status as litter_status,
                           l.notes as litter_notes,
                           CASE WHEN EXISTS(SELECT 1 FROM farrowing_records_edit_history WHERE record_id = fr.id) THEN 1 ELSE 0 END as is_edited
                    FROM farrowing_records fr
                    JOIN breeding_records br ON fr.breeding_id = br.id
                    LEFT JOIN pigs sow ON br.sow_id = sow.id
                    LEFT JOIN pigs boar ON br.boar_id = boar.id
                    LEFT JOIN employees e ON fr.created_by = e.id
                    LEFT JOIN litters l ON fr.id = l.farrowing_record_id
                    WHERE l.status = 'unweaned'
                    ORDER BY fr.farrowing_date DESC
                """)
                records = cursor.fetchall()
                for record in records or []:
                    _prune_non_template_incomplete_farrowing_activities(
                        cursor, record['id']
                    )
                    stats = _farrowing_activity_completion_stats(
                        cursor, record['id'], record.get('farrowing_date')
                    )
                    record.update(stats)
                print(f"Found {len(records)} completed farrowing records with unweaned litters")
                
                # Debug: Print first record if available
                if records and len(records) > 0:
                    print(f"Sample record: {dict(records[0])}")
            except Exception as query_error:
                # If query fails (e.g., no records or other issue), return empty list
                print(f"Query error (returning empty list): {str(query_error)}")
                import traceback
                traceback.print_exc()
                records = []
        else:
            print("Table not verified, returning empty records")
            records = []
            reconcile_summary = {'checked': 0, 'updated': 0, 'litters_weaned': [], 'sows_available': [], 'messages': []}
        
        cursor.close()
        conn.close()
        
        return jsonify({
            'success': True,
            'records': records,
            'reconcile': reconcile_summary,
        })
        
    except Exception as e:
        print(f"Error getting completed farrowings: {str(e)}")
        # Return empty list instead of error to prevent frontend issues
        return jsonify({
            'success': True,
            'records': [],
            'reconcile': {'checked': 0, 'updated': 0, 'litters_weaned': [], 'sows_available': [], 'messages': []},
        })

@app.route('/api/breeding/statistics', methods=['GET'])
def get_breeding_statistics():
    """Get breeding statistics including success and failure rates"""
    if 'employee_id' not in session or session.get('employee_role') not in ['administrator', 'manager']:
        return jsonify({'error': 'Unauthorized'}), 401
    
    try:
        conn = get_db_connection()
        cursor = conn.cursor()
        
        cursor.execute("""
            SELECT
                COUNT(CASE WHEN purpose = 'breeding' AND gender = 'female' AND breeding_status = 'served' THEN 1 END) as served_count,
                COUNT(CASE WHEN purpose = 'breeding' AND gender = 'female' AND breeding_status = 'pregnant' THEN 1 END) as pregnant_count,
                0 as cancelled_count
            FROM pigs
        """)
        breeding_stats = cursor.fetchone()
        
        cursor.execute("SELECT COUNT(*) as failed_count FROM failed_conceptions")
        failed_count = cursor.fetchone()['failed_count']
        
        total_attempts = (breeding_stats['served_count'] or 0) + (breeding_stats['pregnant_count'] or 0) + failed_count
        success_rate = 0
        if total_attempts > 0:
            success_rate = round(((breeding_stats['pregnant_count'] or 0) / total_attempts) * 100, 2)
        
        cursor.close()
        conn.close()
        
        return jsonify({
            'success': True,
            'statistics': {
                'served_count': breeding_stats['served_count'] or 0,
                'pregnant_count': breeding_stats['pregnant_count'] or 0,
                'cancelled_count': breeding_stats['cancelled_count'] or 0,
                'failed_count': failed_count,
                'total_attempts': total_attempts,
                'success_rate': success_rate
            }
        })
        
    except Exception as e:
        print(f"Error getting breeding statistics: {str(e)}")
        return jsonify({'error': str(e)}), 500

def update_breeding_statuses():
    """Move served sows to pregnant after the gestation-confirmation window (pigs.breeding_status)."""
    try:
        conn = get_db_connection()
        cursor = conn.cursor()
        
        cursor.execute("""
            SELECT br.id, br.sow_id, br.mating_date, sow.tag_id, sow.breeding_status
            FROM breeding_records br
            LEFT JOIN pigs sow ON br.sow_id = sow.id
            WHERE sow.breeding_status = 'served'
        """)
        records = cursor.fetchall()
        
        from datetime import datetime
        today = datetime.now().date()
        updated_count = 0
        
        for record in records:
            days_since_mating = (today - record['mating_date']).days
            
            if days_since_mating > 25:
                cursor.execute("""
                    UPDATE pigs
                    SET breeding_status = 'pregnant'
                    WHERE id = %s
                """, (record['sow_id'],))
                updated_count += 1
        
        conn.commit()
        cursor.close()
        conn.close()
        
        if updated_count > 0:
            print(f"Updated {updated_count} sows to pregnant (breeding status on pigs)")
        
    except Exception as e:
        print(f"Error updating breeding statuses: {e}")
        import traceback
        traceback.print_exc()

@app.route('/api/breeding/register-farrowing/<int:breeding_id>', methods=['POST'])
def register_farrowing(breeding_id):
    """Register farrowing for a breeding record (one farrowing record per breeding cycle)."""
    if 'employee_id' not in session or session.get('employee_role') not in ['administrator', 'manager']:
        return jsonify({'error': 'Unauthorized'}), 401
    
    try:
        from datetime import timedelta
        data = request.get_json()
        farrowing_date = data.get('farrowing_date')
        alive_piglets = data.get('alive_piglets')
        still_births = data.get('still_births')
        avg_weight = data.get('avg_weight')
        health_notes = (data.get('health_notes') or '').strip()
        # New: weigh-in / health-comparison fields parity with completed-farrowings flow.
        expected_weight = data.get('expected_weight')
        health_status   = (data.get('health_status') or 'healthy').strip().lower()

        if not all([farrowing_date, alive_piglets is not None, still_births is not None, avg_weight is not None]):
            return jsonify({'success': False, 'message': 'Missing required fields'})

        allowed_statuses = {'healthy', 'sick', 'recovering', 'quarantine', 'critical', 'injured'}
        if health_status not in allowed_statuses:
            return jsonify({'success': False, 'message': f'Invalid health status. Allowed: {", ".join(sorted(allowed_statuses))}'})
        if health_status != 'healthy' and not health_notes:
            return jsonify({'success': False, 'message': 'Health notes are required when the litter is not healthy'})

        try:
            avg_weight_value = float(avg_weight) if avg_weight not in (None, '') else None
        except (TypeError, ValueError):
            avg_weight_value = None
        try:
            expected_weight_value = float(expected_weight) if expected_weight not in (None, '') else None
            if expected_weight_value is not None and expected_weight_value <= 0:
                expected_weight_value = None
        except (TypeError, ValueError):
            expected_weight_value = None
        
        conn = get_db_connection()
        cursor = conn.cursor()
        
        # Get breeding record details
        cursor.execute("""
            SELECT br.*, p.tag_id as sow_tag_id, p.breed as sow_breed
            FROM breeding_records br
            JOIN pigs p ON br.sow_id = p.id
            WHERE br.id = %s
        """, (breeding_id,))
        
        breeding_record = cursor.fetchone()
        if not breeding_record:
            return jsonify({'success': False, 'message': 'Breeding record not found'})

        existing_farrowing = _get_farrowing_record_for_breeding(cursor, breeding_id)
        if existing_farrowing and existing_farrowing.get('has_litter'):
            cursor.close()
            conn.close()
            return jsonify({
                'success': False,
                'message': 'This breeding record already has a farrowing record with a registered litter.'
            })

        farrowing_id = None
        created_new_farrowing_record = False
        if existing_farrowing:
            farrowing_id = existing_farrowing['id']
            cursor.execute("""
                UPDATE farrowing_records
                SET farrowing_date = %s,
                    alive_piglets = %s,
                    still_births = %s,
                    avg_weight = %s,
                    health_notes = %s,
                    updated_at = CURRENT_TIMESTAMP
                WHERE id = %s
            """, (farrowing_date, alive_piglets, still_births, avg_weight, health_notes, farrowing_id))
            resync_farrowing_activity_due_dates_for_record(cursor, farrowing_id, farrowing_date)
        else:
            try:
                cursor.execute("""
                    INSERT INTO farrowing_records (
                        breeding_id, farrowing_date, alive_piglets, still_births,
                        avg_weight, health_notes, created_by
                    ) VALUES (%s, %s, %s, %s, %s, %s, %s)
                """, (
                    breeding_id, farrowing_date, alive_piglets, still_births,
                    avg_weight, health_notes, session['employee_id']
                ))
                farrowing_id = cursor.lastrowid
                created_new_farrowing_record = True
            except Exception as insert_error:
                err_text = str(insert_error)
                if '1062' not in err_text and 'Duplicate' not in err_text:
                    raise
                existing_farrowing = _get_farrowing_record_for_breeding(cursor, breeding_id)
                if not existing_farrowing:
                    raise
                if existing_farrowing.get('has_litter'):
                    cursor.close()
                    conn.close()
                    return jsonify({
                        'success': False,
                        'message': 'This breeding record already has a farrowing record with a registered litter.'
                    })
                farrowing_id = existing_farrowing['id']
                cursor.execute("""
                    UPDATE farrowing_records
                    SET farrowing_date = %s,
                        alive_piglets = %s,
                        still_births = %s,
                        avg_weight = %s,
                        health_notes = %s,
                        updated_at = CURRENT_TIMESTAMP
                    WHERE id = %s
                """, (farrowing_date, alive_piglets, still_births, avg_weight, health_notes, farrowing_id))
                resync_farrowing_activity_due_dates_for_record(cursor, farrowing_id, farrowing_date)

        cursor.execute("""
            SELECT id FROM litters WHERE farrowing_record_id = %s LIMIT 1
        """, (farrowing_id,))
        if cursor.fetchone():
            cursor.close()
            conn.close()
            return jsonify({
                'success': False,
                'message': 'A litter is already linked to this farrowing record.'
            })
        
        # Create farrowing activities with due dates from settings templates
        # for new farrowing records, or backfill if none exist.
        cursor.execute("""
            SELECT COUNT(*) AS activity_count
            FROM farrowing_activities
            WHERE farrowing_record_id = %s
        """, (farrowing_id,))
        existing_activity_count = int((cursor.fetchone() or {}).get('activity_count') or 0)
        if created_new_farrowing_record or existing_activity_count == 0:
            combine_same_day_farrowing_templates(cursor)
            cursor.execute("""
                SELECT due_day, activity_name
                FROM farrowing_activity_templates
                WHERE is_active = 1
                ORDER BY due_day ASC, id ASC
            """)
            template_rows = cursor.fetchall() or []
            activities = [(int(r['due_day']), r['activity_name']) for r in template_rows]
            
            for due_day, activity_name in activities:
                # Convert farrowing_date string to date object for timedelta calculation
                farrowing_date_obj = datetime.strptime(farrowing_date, '%Y-%m-%d').date()
                due_date = farrowing_date_obj + timedelta(days=due_day)
                cursor.execute("""
                    INSERT INTO farrowing_activities (
                        farrowing_record_id, activity_name, due_day, due_date
                    ) VALUES (%s, %s, %s, %s)
                """, (farrowing_id, activity_name, due_day, due_date))
        
        # Create litter record
        litter_id = generate_litter_id()
        total_piglets = alive_piglets + still_births
        
        cursor.execute("""
            INSERT INTO litters (
                litter_id, farrowing_record_id, sow_id, boar_id, farrowing_date,
                total_piglets, alive_piglets, still_births, avg_weight, created_by
            ) VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s)
        """, (
            litter_id, farrowing_id, breeding_record['sow_id'], breeding_record['boar_id'],
            farrowing_date, total_piglets, alive_piglets, still_births, avg_weight_value, session['employee_id']
        ))
        new_litter_db_id = cursor.lastrowid
        print(f"Created litter record: {litter_id} (id={new_litter_db_id})")

        # ---- Persist initial weigh-in + health snapshot for the new litter so it
        # shows up in Weight Assessment / Health Analytics immediately. Mirrors
        # the schema written by /api/litter/record-weigh-in and the farrowing
        # activity completion flow. ----
        weight_record_id = None
        if avg_weight_value is not None and avg_weight_value > 0:
            try:
                farrowing_date_obj = datetime.strptime(farrowing_date, '%Y-%m-%d').date()
            except Exception:
                farrowing_date_obj = None

            # If the client didn't supply expected_weight, ask the helper to
            # compute one for the litter on the farrowing date.
            computed_expected = expected_weight_value
            if computed_expected is None:
                try:
                    computed_expected = calculate_expected_weight(
                        litter_id=new_litter_db_id,
                        weighing_date=farrowing_date_obj
                    )
                except Exception as exp_e:
                    print(f"Note: could not compute expected weight for new litter {new_litter_db_id}: {exp_e}")
                    computed_expected = None

            try:
                cursor.execute("""
                    INSERT INTO weight_records
                        (litter_id, weight, expected_weight, weight_type, weighing_date, notes, created_at, updated_at)
                    VALUES (%s, %s, %s, 'actual', %s, %s, NOW(), NOW())
                """, (
                    new_litter_db_id, avg_weight_value, computed_expected,
                    farrowing_date_obj or farrowing_date,
                    health_notes or 'Initial weigh-in at farrowing registration'
                ))
                weight_record_id = cursor.lastrowid
            except Exception as wr_e:
                print(f"Note: could not insert initial weight_records row: {wr_e}")

        # Insert litter_health_records snapshot tied to the weight record (if any).
        try:
            cursor.execute("""
                INSERT INTO litter_health_records
                    (litter_id, check_date, health_status, notes, weight_record_id, recorded_by, created_at, updated_at)
                VALUES (%s, %s, %s, %s, %s, %s, NOW(), NOW())
            """, (
                new_litter_db_id, farrowing_date, health_status,
                health_notes or None, weight_record_id, session['employee_id']
            ))
        except Exception as hr_e:
            print(f"Note: could not insert initial litter_health_records row: {hr_e}")

        # Sync litters.health_status so the Litters tab and Health Analytics badges match.
        try:
            cursor.execute("""
                UPDATE litters
                SET health_status = %s, updated_at = CURRENT_TIMESTAMP
                WHERE id = %s
            """, (health_status, new_litter_db_id))
        except Exception as upd_e:
            print(f"Note: could not sync litters.health_status on registration: {upd_e}")

        # Update sow's breeding status to farrowed
        print(f"Updating sow {breeding_record['sow_id']} breeding status to 'farrowed'")
        # Note: Sows with 'farrowed' status need recovery time before being bred again
        # This status can be manually changed back to 'available' by farm managers
        # or automatically after a set recovery period (typically 2-3 months)
        cursor.execute("""
            UPDATE pigs 
            SET breeding_status = 'farrowed' 
            WHERE id = %s
        """, (breeding_record['sow_id'],))
        
        cursor.execute("SELECT breeding_status FROM pigs WHERE id = %s", (breeding_record['sow_id'],))
        updated_pig = cursor.fetchone()
        print(f"Pig breeding status after update: {updated_pig['breeding_status']}")
        
        conn.commit()
        cursor.close()
        conn.close()
        
        print(f"Farrowing registration completed successfully for breeding record {breeding_id}")
        
        return jsonify({
            'success': True,
            'message': 'Farrowing registered successfully'
        })
        
    except Exception as e:
        print(f"Farrowing registration error: {str(e)}")
        import traceback
        traceback.print_exc()
        return jsonify({'success': False, 'message': f'Failed to register farrowing: {str(e)}'})

@app.route('/api/farrowing/activities/<int:farrowing_id>', methods=['GET'])
def get_farrowing_activities(farrowing_id):
    """Get farrowing activities for a specific farrowing record"""
    if 'employee_id' not in session or session.get('employee_role') not in ['administrator', 'manager']:
        return jsonify({'error': 'Unauthorized'}), 401
    
    try:
        conn = get_db_connection()
        cursor = conn.cursor()
        cycle_on_load = None

        # Pull farrowing + sow + litter context so the front-end can compute
        # the litter's age at the chosen completion date, look up an expected
        # weight from weight_categories and auto-suggest a health status.
        cursor.execute("""
            SELECT fr.id              AS farrowing_id,
                   fr.farrowing_date  AS farrowing_date,
                   br.sow_id          AS sow_id,
                   sow.tag_id         AS sow_tag_id,
                   l.id               AS litter_id,
                   l.litter_id        AS litter_tag,
                   l.avg_weight       AS litter_avg_weight,
                   l.weaning_weight   AS litter_weaning_weight,
                   l.alive_piglets    AS alive_piglets
            FROM farrowing_records fr
            JOIN breeding_records  br  ON fr.breeding_id = br.id
            LEFT JOIN pigs         sow ON br.sow_id     = sow.id
            LEFT JOIN litters      l   ON l.farrowing_record_id = fr.id
            WHERE fr.id = %s
            ORDER BY l.id DESC
            LIMIT 1
        """, (farrowing_id,))
        ctx_row = cursor.fetchone()

        # Keep schedules aligned with Farrowing Activity Settings for active litters.
        if ctx_row and (ctx_row.get('litter_id') is not None):
            cursor.execute(
                "SELECT status FROM litters WHERE id = %s LIMIT 1",
                (ctx_row['litter_id'],),
            )
            litter_status_row = cursor.fetchone()
            if litter_status_row and litter_status_row.get('status') == 'unweaned':
                sync_farrowing_activities_from_templates(
                    cursor,
                    farrowing_id,
                    ctx_row.get('farrowing_date'),
                )
                conn.commit()

        # Get farrowing activities with completion status
        cursor.execute("""
            SELECT fa.*, e.full_name as completed_by_name
            FROM farrowing_activities fa
            LEFT JOIN employees e ON fa.completed_by = e.id
            WHERE fa.farrowing_record_id = %s
            ORDER BY fa.due_day ASC
        """, (farrowing_id,))

        activities = cursor.fetchall()

        def apply_canonical_farrowing_activity_due_dates(rows):
            """Use farrowing_date + due_day (actual farrowing), not a stale farrowing_activities.due_date."""
            base = _coerce_farrowing_date(ctx_row.get('farrowing_date')) if ctx_row else None
            if not base:
                return
            for a in rows:
                try:
                    day = int(a['due_day'])
                except (TypeError, ValueError):
                    continue
                a['due_date'] = base + timedelta(days=day)

        apply_canonical_farrowing_activity_due_dates(activities)
        today = datetime.now().date()
        farrowing_base = _coerce_farrowing_date(ctx_row.get('farrowing_date')) if ctx_row else None
        litter_age_days = (today - farrowing_base).days if farrowing_base else None
        
        # Auto-complete activities that have reached their exact due day
        auto_completed = False
        for activity in activities:
            if _activity_row_is_completed(activity):
                continue
            if activity.get('due_date') == today:
                cursor.execute("""
                    UPDATE farrowing_activities 
                    SET completed = TRUE, completed_date = %s, 
                        notes = CONCAT(COALESCE(notes, ''), ' - Auto-completed on due day ', %s)
                    WHERE id = %s
                """, (today, today, activity['id']))
                activity['completed'] = True
                activity['completed_date'] = today
                activity['notes'] = f"Auto-completed on due day {today}"
                auto_completed = True

        if auto_completed:
            conn.commit()
            cursor.execute("""
                SELECT fa.*, e.full_name as completed_by_name
                FROM farrowing_activities fa
                LEFT JOIN employees e ON fa.completed_by = e.id
                WHERE fa.farrowing_record_id = %s
                ORDER BY fa.due_day ASC
            """, (farrowing_id,))
            activities = cursor.fetchall()
            apply_canonical_farrowing_activity_due_dates(activities)

        _prune_non_template_incomplete_farrowing_activities(cursor, farrowing_id)
        cycle_on_load = finalize_farrowing_cycle_after_activity(
            cursor, farrowing_id, session.get('employee_id')
        )
        if auto_completed or cycle_on_load.get('litter_weaned') or cycle_on_load.get('sow_available'):
            conn.commit()

        # Combine same-day activities into a single row for popup display
        grouped = {}
        for activity in activities:
            day = int(activity['due_day'])
            entry = grouped.get(day)
            if not entry:
                entry = {
                    'id': activity['id'],
                    'activity_ids': [],
                    'activity_names': [],
                    'due_day': day,
                    'due_date': activity['due_date'],
                    'all_completed': True,
                    'completed_dates': [],
                    'completed_by_names': [],
                    'notes_list': [],
                    'weaning_weight': None,
                    'weaning_date': None
                }
                grouped[day] = entry

            entry['activity_ids'].append(activity['id'])
            name = (activity.get('activity_name') or '').strip()
            if name:
                for part in [p.strip() for p in name.split(';') if p.strip()]:
                    if part not in entry['activity_names']:
                        entry['activity_names'].append(part)

            is_completed = _activity_row_is_completed(activity)
            entry['all_completed'] = entry['all_completed'] and is_completed

            if activity.get('completed_date'):
                entry['completed_dates'].append(activity['completed_date'])
            if activity.get('completed_by_name'):
                if activity['completed_by_name'] not in entry['completed_by_names']:
                    entry['completed_by_names'].append(activity['completed_by_name'])
            if activity.get('notes'):
                note = str(activity.get('notes')).strip()
                if note and note not in entry['notes_list']:
                    entry['notes_list'].append(note)

            if activity.get('weaning_weight') is not None and entry['weaning_weight'] is None:
                entry['weaning_weight'] = float(activity['weaning_weight'])
            if activity.get('weaning_date') and entry['weaning_date'] is None:
                entry['weaning_date'] = activity['weaning_date']

        activities_list = []
        for day in sorted(grouped.keys()):
            entry = grouped[day]
            latest_completed_date = max(entry['completed_dates']) if entry['completed_dates'] else None
            due_day = entry['due_day']
            days_overdue = None
            days_until_due = None
            if litter_age_days is not None:
                if litter_age_days > due_day:
                    days_overdue = litter_age_days - due_day
                elif litter_age_days < due_day:
                    days_until_due = due_day - litter_age_days
            activities_list.append({
                'id': entry['id'],
                'activity_ids': entry['activity_ids'],
                'activity_name': '; '.join(entry['activity_names']),
                'due_day': due_day,
                'due_date': entry['due_date'].isoformat() if entry['due_date'] else None,
                'litter_age_days': litter_age_days,
                'days_until_due': days_until_due,
                'days_overdue': days_overdue,
                'completed': entry['all_completed'],
                'completed_date': latest_completed_date.isoformat() if latest_completed_date else None,
                'completed_by_name': ', '.join(entry['completed_by_names']) if entry['completed_by_names'] else None,
                'notes': ' | '.join(entry['notes_list']) if entry['notes_list'] else None,
                'weaning_weight': entry['weaning_weight'],
                'weaning_date': entry['weaning_date'].isoformat() if entry['weaning_date'] else None
            })

        farrowing_date_for_schedule = ctx_row.get('farrowing_date') if ctx_row else None
        scheduled_complete = _farrowing_scheduled_activities_complete(
            cursor, farrowing_id, farrowing_date_for_schedule
        )
        activity_stats = _farrowing_activity_completion_stats(
            cursor, farrowing_id, farrowing_date_for_schedule
        )

        context = None
        if ctx_row:
            farrowing_date_val = _coerce_farrowing_date(ctx_row.get('farrowing_date'))
            context = {
                'farrowing_id': ctx_row.get('farrowing_id'),
                'farrowing_date': farrowing_date_val.isoformat() if farrowing_date_val else None,
                'days_since_farrowing': litter_age_days,
                'sow_id': ctx_row.get('sow_id'),
                'sow_tag_id': ctx_row.get('sow_tag_id'),
                'litter_id': ctx_row.get('litter_id'),
                'litter_tag': ctx_row.get('litter_tag'),
                'litter_avg_weight': float(ctx_row['litter_avg_weight']) if ctx_row.get('litter_avg_weight') is not None else None,
                'litter_weaning_weight': float(ctx_row['litter_weaning_weight']) if ctx_row.get('litter_weaning_weight') is not None else None,
                'alive_piglets': ctx_row.get('alive_piglets')
            }

        cursor.close()
        conn.close()

        return jsonify({
            'success': True,
            'activities': activities_list,
            'context': context,
            'scheduled_activities_complete': scheduled_complete,
            'activities_completed': activity_stats.get('activities_completed'),
            'activities_total': activity_stats.get('activities_total'),
            'activities_percent': activity_stats.get('activities_percent'),
            'cycle': cycle_on_load if cycle_on_load else None,
        })
        
    except Exception as e:
        print(f"Error getting farrowing activities: {str(e)}")
        return jsonify({'success': False, 'message': f'Failed to get activities: {str(e)}'})

@app.route('/api/farrowing/reconcile-cycles', methods=['GET', 'POST'])
def reconcile_farrowing_cycles_api():
    """Run on farm page load: wean litters and free sows when all activities are already complete."""
    if 'employee_id' not in session or session.get('employee_role') not in ['administrator', 'manager']:
        return jsonify({'error': 'Unauthorized'}), 401
    try:
        conn = get_db_connection()
        cursor = conn.cursor()
        summary = reconcile_complete_farrowing_cycles(
            cursor, session.get('employee_id')
        )
        if summary.get('updated'):
            conn.commit()
        cursor.close()
        conn.close()
        return jsonify({'success': True, 'reconcile': summary})
    except Exception as e:
        print(f"Error reconciling farrowing cycles: {str(e)}")
        return jsonify({'success': False, 'message': str(e)}), 500


@app.route('/api/farrowing/manual-wean/<int:farrowing_id>', methods=['POST'])
def manual_wean_farrowing_cycle_api(farrowing_id):
    """Mark litter(s) weaned and sow available when all scheduled activities are already complete."""
    if 'employee_id' not in session or session.get('employee_role') not in ['administrator', 'manager']:
        return jsonify({'error': 'Unauthorized'}), 401
    try:
        data = request.get_json(silent=True) or {}
        notes = (data.get('notes') or '').strip() or None
        weaning_weight = data.get('weaning_weight')
        weaning_date_raw = (data.get('weaning_date') or '').strip()

        parsed_weight = None
        if weaning_weight not in [None, '']:
            try:
                parsed_weight = float(weaning_weight)
                if parsed_weight <= 0:
                    return jsonify({'success': False, 'message': 'Weaning weight must be greater than zero.'})
            except (TypeError, ValueError):
                return jsonify({'success': False, 'message': 'Invalid weaning weight.'})

        weaning_date = None
        if weaning_date_raw:
            try:
                if 'T' in weaning_date_raw:
                    weaning_date = datetime.fromisoformat(
                        weaning_date_raw.replace('Z', '+00:00')
                    ).date()
                else:
                    weaning_date = datetime.strptime(weaning_date_raw[:10], '%Y-%m-%d').date()
            except ValueError:
                return jsonify({'success': False, 'message': 'Invalid weaning date. Use YYYY-MM-DD.'})
            if weaning_date > datetime.now().date():
                return jsonify({'success': False, 'message': 'Weaning date cannot be in the future.'})

        conn = get_db_connection()
        cursor = conn.cursor()
        _prune_non_template_incomplete_farrowing_activities(cursor, farrowing_id)
        if not _farrowing_scheduled_activities_complete(cursor, farrowing_id):
            cursor.close()
            conn.close()
            return jsonify({
                'success': False,
                'message': 'Complete all scheduled farrowing activities before using manual wean.',
            })

        result = manual_wean_farrowing_cycle(
            cursor,
            farrowing_id,
            session.get('employee_id'),
            weaning_weight=parsed_weight,
            weaning_date=weaning_date,
            notes=notes,
        )
        if result.get('error'):
            cursor.close()
            conn.close()
            return jsonify({'success': False, 'message': result['error']})

        conn.commit()
        cursor.close()
        conn.close()
        return jsonify({'success': True, 'message': result.get('message'), 'cycle': result})
    except Exception as e:
        print(f"Error manual weaning farrowing cycle: {str(e)}")
        return jsonify({'success': False, 'message': f'Failed to manual wean: {str(e)}'})


