def _milk_analytics_date_filter(date_column='production_date'):
    """Build WHERE clause and params for milk analytics date filter. date_column is e.g. 'production_date' or 'transaction_date'."""
    filter_mode = request.args.get('filter_mode')
    date_val = request.args.get('date')
    date_from = request.args.get('date_from')
    date_to = request.args.get('date_to')
    month_val = request.args.get('month')
    year_val = request.args.get('year')
    where = ""
    params = []
    if filter_mode == 'day' and date_val:
        where = f" AND {date_column} = %s"
        params.append(date_val)
    elif filter_mode == 'range' and date_from and date_to:
        where = f" AND {date_column} BETWEEN %s AND %s"
        params.extend([date_from, date_to])
    elif filter_mode == 'month' and month_val and year_val:
        where = f" AND MONTH({date_column}) = %s AND YEAR({date_column}) = %s"
        params.extend([int(month_val), int(year_val)])
    elif filter_mode == 'year' and year_val:
        where = f" AND YEAR({date_column}) = %s"
        params.append(int(year_val))
    return where, params


@app.route('/api/milk-analytics/production', methods=['GET'])
def get_milk_production_analytics():
    """Get milk production analytics data. Supports filter_mode=day|range|month|year with date, date_from/date_to, month, year."""
    if 'employee_id' not in session or session.get('employee_role') not in ['administrator', 'manager']:
        return jsonify({'error': 'Unauthorized'}), 401
    
    date_where, date_params = _milk_analytics_date_filter('production_date')
    default_where = " WHERE MONTH(production_date) = MONTH(CURRENT_DATE()) AND YEAR(production_date) = YEAR(CURRENT_DATE())"
    trend_default = " WHERE production_date >= DATE_SUB(CURDATE(), INTERVAL 30 DAY)"
    
    try:
        conn = get_db_connection()
        cursor = conn.cursor()
        
        if date_where:
            cursor.execute("""
                SELECT 
                    SUM(milk_quantity) as total_production,
                    AVG(milk_quantity) as daily_average,
                    MAX(milk_quantity) as peak_production,
                    COUNT(DISTINCT production_date) as production_days
                FROM milk_production 
                WHERE 1=1
                """ + date_where, tuple(date_params))
        else:
            cursor.execute("""
                SELECT 
                    SUM(milk_quantity) as total_production,
                    AVG(milk_quantity) as daily_average,
                    MAX(milk_quantity) as peak_production,
                    COUNT(*) as production_days
                FROM milk_production 
                """ + default_where)
        current_month = cursor.fetchone()
        
        if date_where:
            last_month = {'last_month_production': 0}
        else:
            cursor.execute("""
                SELECT SUM(milk_quantity) as last_month_production
                FROM milk_production 
                WHERE MONTH(production_date) = MONTH(CURRENT_DATE() - INTERVAL 1 MONTH) 
                AND YEAR(production_date) = YEAR(CURRENT_DATE() - INTERVAL 1 MONTH)
            """)
            last_month = cursor.fetchone()
        
        if date_where:
            cursor.execute("""
                SELECT production_date, SUM(milk_quantity) as daily_production
                FROM milk_production 
                WHERE 1=1
                """ + date_where + """
                GROUP BY production_date
                ORDER BY production_date
            """, tuple(date_params))
        else:
            cursor.execute("""
                SELECT production_date, SUM(milk_quantity) as daily_production
                FROM milk_production 
                """ + trend_default + """
                GROUP BY production_date
                ORDER BY production_date
            """)
        trend_data = cursor.fetchall()
        
        current_total = float(current_month['total_production'] or 0)
        last_total = float(last_month['last_month_production'] or 0)
        growth_rate = ((current_total - last_total) / last_total * 100) if last_total > 0 else 0
        
        cursor.close()
        conn.close()
        
        return jsonify({
            'success': True,
            'data': {
                'total_production': current_total,
                'daily_average': float(current_month['daily_average'] or 0),
                'peak_production': float(current_month['peak_production'] or 0),
                'growth_rate': round(growth_rate, 1),
                'trend_data': [{'date': str(record['production_date']), 'production': float(record['daily_production'])} for record in trend_data]
            }
        })
        
    except Exception as e:
        print(f"Error getting milk production analytics: {str(e)}")
        return jsonify({'error': str(e)}), 500

@app.route('/api/milk-analytics/usage', methods=['GET'])
def get_milk_usage_analytics():
    """Get milk usage analytics data. Supports date filter: filter_mode, date, date_from/date_to, month, year."""
    if 'employee_id' not in session or session.get('employee_role') not in ['administrator', 'manager']:
        return jsonify({'error': 'Unauthorized'}), 401
    
    date_where, date_params = _milk_analytics_date_filter('transaction_date')
    default_where = " AND MONTH(transaction_date) = MONTH(CURRENT_DATE()) AND YEAR(transaction_date) = YEAR(CURRENT_DATE())"
    
    try:
        conn = get_db_connection()
        cursor = conn.cursor()
        
        cursor.execute("""
            SELECT purpose_of_use, SUM(quantity_used) as total_usage
            FROM milk_sales_usage 
            WHERE transaction_type = 'usage'
            """ + (date_where if date_where else default_where) + """
            GROUP BY purpose_of_use
        """, tuple(date_params) if date_params else ())
        usage_data = cursor.fetchall()
        
        # Format usage data - ensure all expected keys exist (ENUM may return as str or bytes)
        usage_stats = {
            'calf_feeding': 0.0,
            'home_consumption': 0.0,
            'processing': 0.0,
            'wastage_spoiled': 0.0
        }
        for record in usage_data:
            purpose = record.get('purpose_of_use')
            if purpose is not None:
                key = (purpose.decode('utf-8') if isinstance(purpose, bytes) else str(purpose)).strip()
                if key in usage_stats:
                    usage_stats[key] = float(record['total_usage'] or 0)
        
        cursor.close()
        conn.close()
        
        return jsonify({
            'success': True,
            'data': usage_stats
        })
        
    except Exception as e:
        print(f"Error getting milk usage analytics: {str(e)}")
        return jsonify({'error': str(e)}), 500

@app.route('/api/milk-analytics/quality', methods=['GET'])
def get_milk_quality_analytics():
    """Get milk quality analytics data. Supports date filter: filter_mode, date, date_from/date_to, month, year."""
    if 'employee_id' not in session or session.get('employee_role') not in ['administrator', 'manager']:
        return jsonify({'error': 'Unauthorized'}), 401
    
    date_where, date_params = _milk_analytics_date_filter('production_date')
    default_where = " AND MONTH(production_date) = MONTH(CURRENT_DATE()) AND YEAR(production_date) = YEAR(CURRENT_DATE())"
    
    try:
        conn = get_db_connection()
        cursor = conn.cursor()
        
        cursor.execute("""
            SELECT milk_quality_assessment, COUNT(*) as count,
                AVG(fat_percentage) as avg_fat, AVG(protein_percentage) as avg_protein
            FROM milk_production 
            WHERE 1=1
            """ + (date_where if date_where else default_where) + """
            GROUP BY milk_quality_assessment
        """, tuple(date_params) if date_params else ())
        quality_data = cursor.fetchall()
        
        total_records = sum(record['count'] for record in quality_data)
        quality_stats = {
            'good_quality': 0,
            'moderate_quality': 0,
            'poor_quality': 0,
            'avg_fat_content': 0,
            'avg_protein_content': 0
        }
        
        for record in quality_data:
            percentage = (record['count'] / total_records * 100) if total_records > 0 else 0
            quality_stats[record['milk_quality_assessment']] = round(percentage, 1)
        
        cursor.execute("""
            SELECT AVG(fat_percentage) as avg_fat, AVG(protein_percentage) as avg_protein
            FROM milk_production 
            WHERE 1=1
            """ + (date_where if date_where else default_where) + """
            AND fat_percentage IS NOT NULL AND protein_percentage IS NOT NULL
        """, tuple(date_params) if date_params else ())
        composition = cursor.fetchone()
        
        quality_stats['avg_fat_content'] = round(float(composition['avg_fat'] or 0), 1)
        quality_stats['avg_protein_content'] = round(float(composition['avg_protein'] or 0), 1)
        
        cursor.close()
        conn.close()
        
        return jsonify({
            'success': True,
            'data': quality_stats
        })
        
    except Exception as e:
        print(f"Error getting milk quality analytics: {str(e)}")
        return jsonify({'error': str(e)}), 500

@app.route('/api/milk-analytics/sales', methods=['GET'])
def get_milk_sales_analytics():
    """Get milk sales analytics data. Supports date filter: filter_mode, date, date_from/date_to, month, year."""
    if 'employee_id' not in session or session.get('employee_role') not in ['administrator', 'manager']:
        return jsonify({'error': 'Unauthorized'}), 401
    
    date_where, date_params = _milk_analytics_date_filter('transaction_date')
    default_where = " AND MONTH(transaction_date) = MONTH(CURRENT_DATE()) AND YEAR(transaction_date) = YEAR(CURRENT_DATE())"
    trend_default = " AND transaction_date >= DATE_SUB(CURDATE(), INTERVAL 30 DAY)"
    
    try:
        conn = get_db_connection()
        cursor = conn.cursor()
        
        cursor.execute("""
            SELECT SUM(quantity_sold) as total_sold, SUM(total_amount) as total_revenue,
                AVG(price_per_liter) as avg_price, COUNT(*) as sales_count
            FROM milk_sales_usage 
            WHERE transaction_type = 'sale'
            """ + (date_where if date_where else default_where), tuple(date_params) if date_params else ())
        sales_data = cursor.fetchone()
        
        cursor.execute("""
            SELECT buyer, SUM(quantity_sold) as quantity, SUM(total_amount) as revenue
            FROM milk_sales_usage 
            WHERE transaction_type = 'sale'
            """ + (date_where if date_where else default_where) + """
            GROUP BY buyer
            ORDER BY revenue DESC
        """, tuple(date_params) if date_params else ())
        buyers_data = cursor.fetchall()
        
        if date_where:
            cursor.execute("""
                SELECT transaction_date, SUM(quantity_sold) as daily_quantity, SUM(total_amount) as daily_revenue
                FROM milk_sales_usage 
                WHERE transaction_type = 'sale'
                """ + date_where + """
                GROUP BY transaction_date
                ORDER BY transaction_date
            """, tuple(date_params))
        else:
            cursor.execute("""
                SELECT transaction_date, SUM(quantity_sold) as daily_quantity, SUM(total_amount) as daily_revenue
                FROM milk_sales_usage 
                WHERE transaction_type = 'sale'
                """ + trend_default + """
                GROUP BY transaction_date
                ORDER BY transaction_date
            """)
        trend_data = cursor.fetchall()
        
        cursor.close()
        conn.close()
        
        return jsonify({
            'success': True,
            'data': {
                'total_sold': float(sales_data['total_sold'] or 0),
                'total_revenue': float(sales_data['total_revenue'] or 0),
                'avg_price': float(sales_data['avg_price'] or 0),
                'sales_count': sales_data['sales_count'] or 0,
                'buyers': [{'buyer': record['buyer'], 'quantity': float(record['quantity']), 'revenue': float(record['revenue'])} for record in buyers_data],
                'trend_data': [{'date': str(record['transaction_date']), 'quantity': float(record['daily_quantity']), 'revenue': float(record['daily_revenue'])} for record in trend_data]
            }
        })
        
    except Exception as e:
        print(f"Error getting milk sales analytics: {str(e)}")
        return jsonify({'error': str(e)}), 500

