@app.route('/api/litter/update/<int:litter_id>', methods=['PUT'])
def update_litter(litter_id):
    """Update litter details (born: sow + boar pig IDs; purchased: parent breed text)."""
    if 'employee_id' not in session or session.get('employee_role') not in ['administrator', 'manager']:
        return jsonify({'error': 'Unauthorized'}), 401
    
    try:
        data = request.get_json() or {}
        base_required = ['litter_id', 'farrowing_date', 'alive_piglets', 'male_piglets', 'female_piglets', 'status']
        for field in base_required:
            if field not in data or data[field] is None:
                return jsonify({'success': False, 'message': f'Missing required field: {field}'})

        try:
            alive_piglets = int(data['alive_piglets'])
            male_piglets = int(data['male_piglets'])
            female_piglets = int(data['female_piglets'])
        except (TypeError, ValueError):
            return jsonify({'success': False, 'message': 'Piglet counts must be valid numbers'})
        if any(x < 0 for x in (alive_piglets, male_piglets, female_piglets)):
            return jsonify({'success': False, 'message': 'Piglet counts cannot be negative'})
        if male_piglets + female_piglets != alive_piglets:
            return jsonify({
                'success': False,
                'message': 'Male piglets + female piglets must equal alive piglets',
            })

        conn = get_db_connection()
        cursor = conn.cursor()
        
        cursor.execute("SELECT * FROM litters WHERE id = %s", (litter_id,))
        existing_litter = cursor.fetchone()
        
        if not existing_litter:
            cursor.close()
            conn.close()
            return jsonify({'success': False, 'message': 'Litter not found'})

        raw_src = data.get('litter_source')
        if raw_src is None or (isinstance(raw_src, str) and not str(raw_src).strip()):
            litter_source = (existing_litter.get('litter_source') or 'born')
        else:
            litter_source = str(raw_src).strip().lower()
        if isinstance(litter_source, bytes):
            litter_source = litter_source.decode('utf-8', errors='ignore')
        if litter_source not in ('born', 'purchased'):
            litter_source = (existing_litter.get('litter_source') or 'born')
        if litter_source not in ('born', 'purchased'):
            litter_source = 'born'

        if litter_source == 'purchased':
            for key in ('sow_breed', 'boar_breed'):
                v = (data.get(key) or '').strip() if data.get(key) is not None else ''
                if not v:
                    cursor.close()
                    conn.close()
                    return jsonify({'success': False, 'message': f'{key.replace("_", " ")} is required for a purchased litter'})
        else:
            for key in ('sow_id', 'boar_id'):
                v = data.get(key)
                if v is None or (isinstance(v, str) and not str(v).strip()):
                    cursor.close()
                    conn.close()
                    return jsonify({'success': False, 'message': f'{key.replace("_", " ")} is required (select sow and boar)'})

        if litter_source == 'born':
            try:
                sow_id = int(data['sow_id'])
                boar_id = int(data['boar_id'])
            except (TypeError, ValueError):
                cursor.close()
                conn.close()
                return jsonify({'success': False, 'message': 'Sow and boar must be valid animal IDs'})

            cursor.execute(
                "SELECT id, gender FROM pigs WHERE id = %s AND status = 'active'",
                (sow_id,),
            )
            sow_row = cursor.fetchone()
            if not sow_row or (sow_row.get('gender') or '').lower() != 'female':
                cursor.close()
                conn.close()
                return jsonify({'success': False, 'message': 'Sow must be an active female pig in the system'})

            cursor.execute(
                "SELECT id, gender FROM pigs WHERE id = %s AND status = 'active'",
                (boar_id,),
            )
            boar_row = cursor.fetchone()
            if not boar_row or (boar_row.get('gender') or '').lower() != 'male':
                cursor.close()
                conn.close()
                return jsonify({'success': False, 'message': 'Boar must be an active male pig in the system'})
        else:
            sow_id = None
            boar_id = None
            sow_breed = (data.get('sow_breed') or '').strip()
            boar_breed = (data.get('boar_breed') or '').strip()
        
        # Check if new litter_id already exists (excluding current litter)
        if data['litter_id'] != existing_litter['litter_id']:
            cursor.execute("SELECT id FROM litters WHERE litter_id = %s AND id != %s", (data['litter_id'], litter_id))
            if cursor.fetchone():
                cursor.close()
                conn.close()
                return jsonify({'success': False, 'message': 'Litter ID already exists'})
        
        # Validate farrowing date is not in the future
        farrowing_date = datetime.strptime(data['farrowing_date'], '%Y-%m-%d').date()
        if farrowing_date > datetime.now().date():
            cursor.close()
            conn.close()
            return jsonify({'success': False, 'message': 'Farrowing date cannot be in the future'})
        
        # Validate weaning date if provided
        weaning_date = None
        if data.get('weaning_date'):
            weaning_date = datetime.strptime(data['weaning_date'], '%Y-%m-%d').date()
            if weaning_date < farrowing_date:
                cursor.close()
                conn.close()
                return jsonify({'success': False, 'message': 'Weaning date cannot be before farrowing date'})
        
        # Prepare the new litter ID with "E" prefix if it's being changed
        new_litter_id = data['litter_id']
        if new_litter_id != existing_litter['litter_id'] and not new_litter_id.startswith('E'):
            new_litter_id = f"E{data['litter_id']}"
        
        if litter_source == 'born':
            cursor.execute(
                """
                UPDATE litters
                SET litter_id = %s, litter_source = 'born', sow_id = %s, boar_id = %s,
                    sow_breed = NULL, boar_breed = NULL, farrowing_date = %s,
                    weaning_date = %s, alive_piglets = %s, male_piglets = %s, female_piglets = %s,
                    weaning_weight = %s, status = %s, updated_at = NOW()
                WHERE id = %s
                """,
                (
                    new_litter_id,
                    sow_id,
                    boar_id,
                    data['farrowing_date'],
                    data.get('weaning_date'),
                    alive_piglets,
                    male_piglets,
                    female_piglets,
                    data.get('weaning_weight'),
                    data['status'],
                    litter_id,
                ),
            )
            log_extra = f"sow {sow_id}, boar {boar_id}"
        else:
            cursor.execute(
                """
                UPDATE litters
                SET litter_id = %s, litter_source = 'purchased', farrowing_record_id = NULL,
                    sow_id = NULL, boar_id = NULL, sow_breed = %s, boar_breed = %s, farrowing_date = %s,
                    weaning_date = %s, alive_piglets = %s, male_piglets = %s, female_piglets = %s,
                    weaning_weight = %s, status = %s, updated_at = NOW()
                WHERE id = %s
                """,
                (
                    new_litter_id,
                    sow_breed,
                    boar_breed,
                    data['farrowing_date'],
                    data.get('weaning_date'),
                    alive_piglets,
                    male_piglets,
                    female_piglets,
                    data.get('weaning_weight'),
                    data['status'],
                    litter_id,
                ),
            )
            log_extra = f"dam breed {sow_breed!r}, sire breed {boar_breed!r}"
        
        # Log the activity
        activity_description = (
            f"Litter details updated: ID → {new_litter_id}, {log_extra}, "
            f"date {data['farrowing_date']}, alive {alive_piglets} ({male_piglets}M/{female_piglets}F), status {data['status']}"
        )
        
        cursor.execute("""
            INSERT INTO litter_activities (litter_id, activity_type, description, created_at)
            VALUES (%s, %s, %s, NOW())
        """, (litter_id, 'updated', activity_description))
        
        conn.commit()
        cursor.close()
        conn.close()
        
        return jsonify({
            'success': True,
            'message': f'Litter {new_litter_id} updated successfully',
            'litter_id': new_litter_id
        })
        
    except Exception as e:
        print(f"Error updating litter: {str(e)}")
        return jsonify({'success': False, 'message': f'Failed to update litter: {str(e)}'})

@app.route('/api/litter/delete/<int:litter_id>', methods=['DELETE'])
def delete_litter(litter_id):
    """Delete a litter record."""
    if 'employee_id' not in session or session.get('employee_role') not in ['administrator', 'manager']:
        return jsonify({'error': 'Unauthorized'}), 401

    conn = None
    cursor = None
    try:
        conn = get_db_connection()
        cursor = conn.cursor()

        cursor.execute("SELECT litter_id FROM litters WHERE id = %s", (litter_id,))
        litter = cursor.fetchone()
        if not litter:
            return jsonify({'success': False, 'message': 'Litter not found'}), 404

        cursor.execute("DELETE FROM litters WHERE id = %s", (litter_id,))
        conn.commit()

        return jsonify({'success': True, 'message': f"Litter {litter.get('litter_id') or litter_id} deleted successfully"})
    except Exception as e:
        if conn:
            conn.rollback()
        print(f"Error deleting litter: {str(e)}")
        return jsonify({'success': False, 'message': f'Failed to delete litter: {str(e)}'}), 500
    finally:
        if cursor:
            cursor.close()
        if conn:
            conn.close()

@app.route('/api/litter/<litter_id>/activities', methods=['GET'])
def get_litter_activities(litter_id):
    """Get all activities for a specific litter"""
    if 'employee_id' not in session or session.get('employee_role') not in ['administrator', 'manager']:
        return jsonify({'error': 'Unauthorized'}), 401
    
    try:
        conn = get_db_connection()
        cursor = conn.cursor()
        
        print(f"Looking for litter: {litter_id}")
        
        # First, check if the litter exists
        cursor.execute("SELECT * FROM litters WHERE litter_id = %s", (litter_id,))
        litter_check = cursor.fetchone()
        
        if not litter_check:
            print(f"Litter {litter_id} not found in litters table")
            return jsonify({'success': False, 'message': f'Litter {litter_id} not found in database'})
        
        print(f"Found litter: {litter_check}")
        
        # Check if there's a farrowing record
        if not litter_check.get('farrowing_record_id'):
            print(f"Litter {litter_id} has no farrowing_record_id")
            return jsonify({'success': False, 'message': f'Litter {litter_id} has no associated farrowing record'})
        
        # Get farrowing record details
        cursor.execute("""
            SELECT fr.*
            FROM farrowing_records fr
            WHERE fr.id = %s
        """, (litter_check['farrowing_record_id'],))
        
        farrowing_record = cursor.fetchone()
        if not farrowing_record:
            print(f"Farrowing record {litter_check['farrowing_record_id']} not found")
            return jsonify({'success': False, 'message': f'Farrowing record not found for litter {litter_id}'})
        
        print(f"Found farrowing record: {farrowing_record}")

        if litter_check.get('status') == 'unweaned':
            sync_farrowing_activities_from_templates(
                cursor,
                litter_check['farrowing_record_id'],
                farrowing_record.get('farrowing_date'),
            )
            conn.commit()

        cycle_on_load = finalize_farrowing_cycle_after_activity(
            cursor,
            litter_check['farrowing_record_id'],
            session.get('employee_id'),
        )
        if cycle_on_load.get('litter_weaned') or cycle_on_load.get('sow_available'):
            conn.commit()
            cursor.execute("SELECT * FROM litters WHERE litter_id = %s", (litter_id,))
            litter_check = cursor.fetchone() or litter_check

        litter = litter_check
        today = datetime.now().date()
        farrowing_base = _coerce_farrowing_date(farrowing_record.get('farrowing_date'))
        litter_age_days = (today - farrowing_base).days if farrowing_base else None

        cursor.execute("""
            SELECT fa.*
            FROM farrowing_activities fa
            WHERE fa.farrowing_record_id = %s
            ORDER BY fa.due_day ASC
        """, (litter['farrowing_record_id'],))

        activities = cursor.fetchall()
        if farrowing_base:
            for a in activities:
                try:
                    a['due_date'] = farrowing_base + timedelta(days=int(a['due_day']))
                except (TypeError, ValueError):
                    pass
        for a in activities:
            if a.get('completed'):
                a['status_category'] = 'Completed'
            elif litter_age_days is not None and litter_age_days > int(a['due_day']):
                a['status_category'] = 'Overdue'
            elif litter_age_days is not None and litter_age_days == int(a['due_day']):
                a['status_category'] = 'Due Today'
            elif a.get('due_date') and a['due_date'] < today:
                a['status_category'] = 'Overdue'
            elif a.get('due_date') and a['due_date'] == today:
                a['status_category'] = 'Due Today'
            else:
                a['status_category'] = 'Upcoming'
            if litter_age_days is not None:
                due_day = int(a['due_day'])
                a['litter_age_days'] = litter_age_days
                if litter_age_days > due_day:
                    a['days_overdue'] = litter_age_days - due_day
                elif litter_age_days < due_day:
                    a['days_until_due'] = due_day - litter_age_days
        
        print(f"Found {len(activities)} activities for litter {litter_id} (farrowing_record_id: {litter['farrowing_record_id']})")
        
        # Get sow information from the litter record BEFORE closing cursor
        cursor.execute("""
            SELECT p.tag_id as sow_tag_id
            FROM pigs p
            WHERE p.id = %s
        """, (litter_check['sow_id'],))
        
        sow_info = cursor.fetchone()
        sow_tag_id = sow_info['sow_tag_id'] if sow_info else 'N/A'
        
        cursor.close()
        conn.close()
        
        # Combine litter and farrowing data
        litter_data = {
            'id': litter_check['id'],
            'litter_id': litter_check['litter_id'],
            'farrowing_record_id': litter_check['farrowing_record_id'],
            'sow_id': litter_check['sow_id'],
            'farrowing_date': litter_check['farrowing_date'],
            'alive_piglets': litter_check['alive_piglets'],
            'status': litter_check['status'],
            'sow_tag_id': sow_tag_id
        }
        
        return jsonify({
            'success': True,
            'activities': activities,
            'litter': litter_data
        })
        
    except Exception as e:
        print(f"Error getting litter activities: {str(e)}")
        return jsonify({'success': False, 'message': f'Failed to get litter activities: {str(e)}'})

def _activity_name_is_weaning(activity_name):
    return 'weaning' in (activity_name or '').lower()


def _activity_row_is_completed(activity_row):
    """Normalize completed flag from MySQL (bool, int, bit)."""
    val = activity_row.get('completed') if isinstance(activity_row, dict) else activity_row
    if val is None:
        return False
    if isinstance(val, bool):
        return val
    if isinstance(val, (int, float)):
        return int(val) == 1
    if isinstance(val, (bytes, bytearray)):
        return val == b'\x01' or val == b'1'
    return str(val).strip().lower() in ('1', 'true', 'yes')


def _active_farrowing_template_days(cursor):
    combine_same_day_farrowing_templates(cursor)
    cursor.execute("""
        SELECT due_day
        FROM farrowing_activity_templates
        WHERE is_active = 1
    """)
    return {int(r['due_day']) for r in (cursor.fetchall() or [])}


def _prune_non_template_incomplete_farrowing_activities(cursor, farrowing_record_id):
    """Drop incomplete rows for days no longer on the schedule (they block auto-wean)."""
    template_days = _active_farrowing_template_days(cursor)
    if not template_days:
        return 0
    cursor.execute("""
        SELECT id, due_day, completed
        FROM farrowing_activities
        WHERE farrowing_record_id = %s
    """, (farrowing_record_id,))
    removed = 0
    for act in cursor.fetchall() or []:
        if _activity_row_is_completed(act):
            continue
        try:
            day = int(act['due_day'])
        except (TypeError, ValueError):
            continue
        if day not in template_days:
            cursor.execute(
                "DELETE FROM farrowing_activities WHERE id = %s",
                (act['id'],),
            )
            removed += 1
    return removed


def _farrowing_activity_completion_stats(cursor, farrowing_record_id, farrowing_date=None):
    """
    Completion % aligned with _farrowing_scheduled_activities_complete:
    each active template due_day counts as one step when all rows for that day are done.
    Days the litter already passed count as done when no row exists (handled via sync backfill).
    """
    litter_age_days = _farrowing_litter_age_days(
        cursor, farrowing_record_id, farrowing_date
    )
    template_days = sorted(_active_farrowing_template_days(cursor))
    cursor.execute("""
        SELECT due_day, completed
        FROM farrowing_activities
        WHERE farrowing_record_id = %s
    """, (farrowing_record_id,))
    by_day = {}
    for row in cursor.fetchall() or []:
        try:
            day = int(row['due_day'])
        except (TypeError, ValueError):
            continue
        by_day.setdefault(day, []).append(_activity_row_is_completed(row))

    if template_days:
        total = len(template_days)
        completed = 0
        for day in template_days:
            if day in by_day and by_day[day] and all(by_day[day]):
                completed += 1
            elif day not in by_day and _farrowing_template_day_waived(litter_age_days, day):
                completed += 1
        percent = int(round((completed / total) * 100)) if total else 0
        return {
            'activities_completed': completed,
            'activities_total': total,
            'activities_percent': percent,
        }

    cursor.execute("""
        SELECT COUNT(*) AS t,
               COALESCE(SUM(CASE WHEN completed IN (1, TRUE) OR completed = b'1' THEN 1 ELSE 0 END), 0) AS d
        FROM farrowing_activities
        WHERE farrowing_record_id = %s
    """, (farrowing_record_id,))
    row = cursor.fetchone() or {}
    try:
        total = int(row.get('t') or 0)
        completed = int(row.get('d') or 0)
    except (TypeError, ValueError):
        total, completed = 0, 0
    percent = int(round((completed / total) * 100)) if total else 0
    return {
        'activities_completed': completed,
        'activities_total': total,
        'activities_percent': percent,
    }


def _farrowing_scheduled_activities_complete(cursor, farrowing_record_id, farrowing_date=None):
    """True when every active template due_day is present and fully completed."""
    template_days = _active_farrowing_template_days(cursor)
    if not template_days:
        return _farrowing_all_activities_complete(cursor, farrowing_record_id)

    litter_age_days = _farrowing_litter_age_days(
        cursor, farrowing_record_id, farrowing_date
    )
    cursor.execute("""
        SELECT due_day, completed
        FROM farrowing_activities
        WHERE farrowing_record_id = %s
    """, (farrowing_record_id,))
    by_day = {}
    for row in cursor.fetchall() or []:
        try:
            day = int(row['due_day'])
        except (TypeError, ValueError):
            continue
        by_day.setdefault(day, []).append(_activity_row_is_completed(row))

    for day in template_days:
        if day not in by_day:
            if _farrowing_template_day_waived(litter_age_days, day):
                continue
            return False
        if not all(by_day[day]):
            return False
    return True


def _farrowing_all_activities_complete(cursor, farrowing_record_id):
    cursor.execute("""
        SELECT COUNT(*) AS t,
               COALESCE(SUM(CASE WHEN completed IN (1, TRUE) OR completed = b'1' THEN 1 ELSE 0 END), 0) AS d
        FROM farrowing_activities
        WHERE farrowing_record_id = %s
    """, (farrowing_record_id,))
    row = cursor.fetchone()
    if not row or not row['t']:
        return False
    try:
        return int(row['d']) >= int(row['t'])
    except (TypeError, ValueError):
        return False


def reconcile_complete_farrowing_cycles(cursor, employee_id=None):
    """On page/system load: apply weaned + sow-available for cycles already fully complete."""
    employee_id = employee_id or 1
    summary = {
        'checked': 0,
        'updated': 0,
        'litters_weaned': [],
        'sows_available': [],
        'messages': [],
    }
    cursor.execute("""
        SELECT DISTINCT fr.id AS farrowing_record_id
        FROM farrowing_records fr
        WHERE EXISTS (
            SELECT 1 FROM farrowing_activities fa
            WHERE fa.farrowing_record_id = fr.id
        )
        AND (
            EXISTS (
                SELECT 1 FROM litters l
                WHERE l.farrowing_record_id = fr.id AND l.status = 'unweaned'
            )
            OR EXISTS (
                SELECT 1 FROM breeding_records br
                JOIN pigs p ON br.sow_id = p.id
                WHERE br.id = fr.breeding_id AND p.breeding_status = 'farrowed'
            )
        )
    """)
    candidates = cursor.fetchall() or []
    for row in candidates:
        farrowing_record_id = row.get('farrowing_record_id')
        if not farrowing_record_id:
            continue
        summary['checked'] += 1
        _prune_non_template_incomplete_farrowing_activities(cursor, farrowing_record_id)
        if not _farrowing_scheduled_activities_complete(cursor, farrowing_record_id):
            continue
        result = finalize_farrowing_cycle_after_activity(
            cursor, farrowing_record_id, employee_id
        )
        if result.get('litter_weaned') or result.get('sow_available'):
            summary['updated'] += 1
            if result.get('litter_tag'):
                summary['litters_weaned'].append(result['litter_tag'])
            if result.get('sow_tag_id'):
                summary['sows_available'].append(result['sow_tag_id'])
            for msg in result.get('messages') or []:
                if msg not in summary['messages']:
                    summary['messages'].append(msg)
    return summary


def manual_wean_farrowing_cycle(cursor, farrowing_record_id, employee_id,
                                weaning_weight=None, weaning_date=None, notes=None):
    """
    Apply litter weaned + sow available using the same status fields as finalize_farrowing_cycle_after_activity.
    Caller must verify _farrowing_scheduled_activities_complete first.
    Syncs an incomplete Weaning activity row when present so activity-based modules stay aligned.
    """
    result = {
        'litter_weaned': False,
        'litter_tag': None,
        'sow_available': False,
        'sow_tag_id': None,
        'weaning_activity_updated': False,
        'messages': [],
        'message': '',
        'error': None,
    }
    employee_id = employee_id or 1
    manual_note = notes or 'Manual wean (Completed Farrowings)'

    cursor.execute("SELECT id FROM farrowing_records WHERE id = %s", (farrowing_record_id,))
    if not cursor.fetchone():
        result['error'] = 'Farrowing record not found.'
        return result

    effective_weaning_date = weaning_date or datetime.now().date()

    cursor.execute("""
        SELECT id, litter_id, status, weaning_date, weaning_weight
        FROM litters
        WHERE farrowing_record_id = %s
    """, (farrowing_record_id,))
    litters = cursor.fetchall() or []
    if not litters:
        result['error'] = 'No litter is linked to this farrowing record. Register the litter first.'
        return result

    weaned_tags = []
    newly_weaned_tags = []
    for litter in litters:
        status = (litter.get('status') or '').strip().lower()
        tag = litter.get('litter_id')
        if status == 'weaned':
            if tag:
                weaned_tags.append(tag)
            continue
        cursor.execute("""
            UPDATE litters
            SET status = 'weaned',
                weaning_date = COALESCE(%s, weaning_date, %s),
                weaning_weight = COALESCE(%s, weaning_weight),
                updated_at = CURRENT_TIMESTAMP
            WHERE id = %s
        """, (effective_weaning_date, effective_weaning_date, weaning_weight, litter['id']))
        if cursor.rowcount:
            if tag:
                weaned_tags.append(tag)
                newly_weaned_tags.append(tag)

    if newly_weaned_tags:
        tag_list = ', '.join(newly_weaned_tags)
        msg = f'Litter(s) {tag_list} marked as weaned (manual).'
        result['messages'].append(msg)
        log_activity(employee_id, 'LITTER_WEANED_MANUAL', msg)
    if weaned_tags:
        result['litter_weaned'] = True
        result['litter_tag'] = weaned_tags[0]

    cursor.execute("""
        SELECT id, activity_name, completed
        FROM farrowing_activities
        WHERE farrowing_record_id = %s
    """, (farrowing_record_id,))
    for act in cursor.fetchall() or []:
        if not _activity_name_is_weaning(act.get('activity_name')):
            continue
        if _activity_row_is_completed(act):
            continue
        cursor.execute("""
            UPDATE farrowing_activities
            SET completed = TRUE,
                completed_date = %s,
                weaning_date = COALESCE(%s, weaning_date, %s),
                weaning_weight = COALESCE(%s, weaning_weight),
                completed_by = %s,
                notes = CONCAT(
                    COALESCE(notes, ''),
                    CASE WHEN notes IS NULL OR notes = '' THEN %s ELSE CONCAT(' | ', %s) END
                ),
                updated_at = CURRENT_TIMESTAMP
            WHERE id = %s
        """, (
            effective_weaning_date,
            effective_weaning_date,
            effective_weaning_date,
            weaning_weight,
            employee_id,
            manual_note,
            manual_note,
            act['id'],
        ))
        if cursor.rowcount:
            result['weaning_activity_updated'] = True

    cursor.execute("""
        SELECT br.sow_id, p.breeding_status, p.tag_id
        FROM farrowing_records fr
        JOIN breeding_records br ON fr.breeding_id = br.id
        JOIN pigs p ON br.sow_id = p.id
        WHERE fr.id = %s
    """, (farrowing_record_id,))
    pig_row = cursor.fetchone()
    if pig_row:
        breeding_status = (pig_row.get('breeding_status') or '').strip().lower()
        if breeding_status == 'available':
            result['sow_available'] = True
            result['sow_tag_id'] = pig_row.get('tag_id')
            result['messages'].append(
                f'Sow {pig_row["tag_id"]} is already available for breeding.'
            )
        elif breeding_status == 'farrowed':
            cursor.execute("""
                UPDATE pigs
                SET breeding_status = 'available'
                WHERE id = %s AND breeding_status = 'farrowed'
            """, (pig_row['sow_id'],))
            if cursor.rowcount:
                result['sow_available'] = True
                result['sow_tag_id'] = pig_row.get('tag_id')
                sow_msg = (
                    f'Sow {pig_row["tag_id"]} is now available for breeding (manual wean).'
                )
                result['messages'].append(sow_msg)
                log_activity(employee_id, 'BREEDING_CYCLE_COMPLETED_MANUAL', sow_msg)
        else:
            result['messages'].append(
                f'Sow {pig_row.get("tag_id") or "?"} was not updated '
                f'(breeding status is {breeding_status or "unknown"}, expected farrowed).'
            )

    if not result['messages']:
        result['error'] = (
            'Nothing was updated — litter may already be weaned and the sow could not be set to available.'
        )
        return result

    result['message'] = ' '.join(result['messages'])
    return result


def finalize_farrowing_cycle_after_activity(cursor, farrowing_record_id, employee_id):
    """When every activity is done: mark litter weaned and sow available (same DB transaction)."""
    result = {
        'all_activities_completed': False,
        'litter_weaned': False,
        'litter_tag': None,
        'sow_available': False,
        'sow_tag_id': None,
        'recovery_days': None,
        'messages': [],
    }
    _prune_non_template_incomplete_farrowing_activities(cursor, farrowing_record_id)

    if not _farrowing_scheduled_activities_complete(cursor, farrowing_record_id):
        return result

    result['all_activities_completed'] = True

    cursor.execute("""
        SELECT weaning_weight, weaning_date, completed_date
        FROM farrowing_activities
        WHERE farrowing_record_id = %s
          AND (completed IN (1, TRUE) OR completed = b'1')
          AND LOWER(activity_name) LIKE %s
        ORDER BY due_day DESC
        LIMIT 1
    """, (farrowing_record_id, '%weaning%'))
    weaning_activity = cursor.fetchone()

    cursor.execute("""
        SELECT id, litter_id, status
        FROM litters
        WHERE farrowing_record_id = %s
    """, (farrowing_record_id,))
    litters = cursor.fetchall() or []

    weaning_weight = None
    weaning_date = None
    if weaning_activity:
        weaning_weight = weaning_activity.get('weaning_weight')
        weaning_date = weaning_activity.get('weaning_date') or weaning_activity.get('completed_date')

    weaned_tags = []
    for litter in litters:
        status = (litter.get('status') or '').strip().lower()
        if status == 'weaned':
            continue
        cursor.execute("""
            UPDATE litters
            SET status = 'weaned',
                weaning_date = COALESCE(%s, weaning_date, CURDATE()),
                weaning_weight = COALESCE(%s, weaning_weight),
                updated_at = CURRENT_TIMESTAMP
            WHERE id = %s
        """, (weaning_date, weaning_weight, litter['id']))
        if cursor.rowcount:
            weaned_tags.append(litter.get('litter_id'))

    if weaned_tags:
        result['litter_weaned'] = True
        result['litter_tag'] = weaned_tags[0]
        tag_list = ', '.join(weaned_tags)
        msg = f'Litter(s) {tag_list} marked as weaned — all scheduled farrowing activities are complete.'
        result['messages'].append(msg)
        log_activity(employee_id, 'LITTER_WEANED_AUTO', msg)

    cursor.execute("""
        SELECT COALESCE(MAX(due_day), 40) AS recovery_days
        FROM farrowing_activity_templates
        WHERE is_active = 1
    """)
    recovery_row = cursor.fetchone() or {}
    try:
        result['recovery_days'] = int(recovery_row.get('recovery_days') or 40)
    except (TypeError, ValueError):
        result['recovery_days'] = 40

    if farrowing_cycle_ready_for_sow_available(cursor, farrowing_record_id):
        cursor.execute("""
            SELECT br.sow_id, p.breeding_status, p.tag_id
            FROM farrowing_records fr
            JOIN breeding_records br ON fr.breeding_id = br.id
            JOIN pigs p ON br.sow_id = p.id
            WHERE fr.id = %s
        """, (farrowing_record_id,))
        pig_row = cursor.fetchone()
        if pig_row and pig_row.get('breeding_status') == 'farrowed':
            cursor.execute("""
                UPDATE pigs
                SET breeding_status = 'available'
                WHERE id = %s AND breeding_status = 'farrowed'
            """, (pig_row['sow_id'],))
            if cursor.rowcount:
                result['sow_available'] = True
                result['sow_tag_id'] = pig_row.get('tag_id')
                sow_msg = (
                    f'Sow {pig_row["tag_id"]} is now available for breeding '
                    f'(all activities done and litter weaned).'
                )
                result['messages'].append(sow_msg)
                log_activity(employee_id, 'BREEDING_CYCLE_COMPLETED', sow_msg)

    return result


def farrowing_cycle_ready_for_sow_available(cursor, farrowing_record_id):
    """True when all farrowing activities are done, Weaning is done if on the schedule, and every litter is weaned."""
    if not _farrowing_scheduled_activities_complete(cursor, farrowing_record_id):
        return False

    cursor.execute("""
        SELECT COUNT(*) AS wc FROM farrowing_activities
        WHERE farrowing_record_id = %s AND LOWER(activity_name) LIKE %s
    """, (farrowing_record_id, '%weaning%'))
    if cursor.fetchone()['wc'] > 0:
        cursor.execute("""
            SELECT completed FROM farrowing_activities
            WHERE farrowing_record_id = %s AND LOWER(activity_name) LIKE %s
            LIMIT 1
        """, (farrowing_record_id, '%weaning%'))
        wrow = cursor.fetchone()
        if not wrow or not _activity_row_is_completed(wrow):
            return False

    cursor.execute("""
        SELECT COUNT(*) AS n,
               COALESCE(SUM(CASE WHEN LOWER(status) = 'weaned' THEN 1 ELSE 0 END), 0) AS w
        FROM litters
        WHERE farrowing_record_id = %s
    """, (farrowing_record_id,))
    lit = cursor.fetchone()
    if lit['n'] == 0:
        return False
    return int(lit['w']) >= int(lit['n'])


def farrowing_cycle_availability_block_reason(cursor, farrowing_record_id):
    """None if ready; otherwise a short message for API responses."""
    template_days = _active_farrowing_template_days(cursor)
    if not template_days:
        return 'No farrowing activities are scheduled for this record.'
    if not _farrowing_scheduled_activities_complete(cursor, farrowing_record_id):
        return 'Complete all scheduled farrowing activities before the sow can be marked available.'

    cursor.execute("""
        SELECT COUNT(*) AS wc FROM farrowing_activities
        WHERE farrowing_record_id = %s AND LOWER(activity_name) LIKE %s
    """, (farrowing_record_id, '%weaning%'))
    if cursor.fetchone()['wc'] > 0:
        cursor.execute("""
            SELECT completed FROM farrowing_activities
            WHERE farrowing_record_id = %s AND LOWER(activity_name) LIKE %s
            LIMIT 1
        """, (farrowing_record_id, '%weaning%'))
        wrow = cursor.fetchone()
        if not wrow or not _activity_row_is_completed(wrow):
            return 'Complete the Weaning activity in Farrowing Activities before marking the sow available.'

    cursor.execute("""
        SELECT COUNT(*) AS n,
               COALESCE(SUM(CASE WHEN LOWER(status) = 'weaned' THEN 1 ELSE 0 END), 0) AS w
        FROM litters
        WHERE farrowing_record_id = %s
    """, (farrowing_record_id,))
    lit = cursor.fetchone()
    if lit['n'] == 0:
        return 'Register the litter for this farrowing before completing the cycle.'
    if int(lit['w']) < int(lit['n']):
        return 'All litters must be weaned (complete Weaning in Farrowing Activities) before the sow can be marked available.'
    return None


def maybe_mark_sow_available_after_farrowing_cycle(farrowing_record_id):
    """Legacy entry point — runs finalize in its own transaction."""
    try:
        conn = get_db_connection()
        cursor = conn.cursor()
        finalize_farrowing_cycle_after_activity(
            cursor,
            farrowing_record_id,
            session.get('employee_id', 1),
        )
        conn.commit()
        cursor.close()
        conn.close()
    except Exception as e:
        print(f"Error auto-marking sow available after farrowing cycle: {str(e)}")


def check_and_trigger_recovery_period(farrowing_record_id):
    """Legacy entry point — recovery logging is handled in finalize."""
    maybe_mark_sow_available_after_farrowing_cycle(farrowing_record_id)


def check_and_update_litter_status(farrowing_record_id):
    """Legacy entry point — litter weaning is handled in finalize."""
    maybe_mark_sow_available_after_farrowing_cycle(farrowing_record_id)

