@app.route('/api/cow-weight/records', methods=['GET'])
def get_cow_weight_records():
    if 'employee_id' not in session:
        return jsonify({'error': 'Unauthorized'}), 401
    try:
        cow_id = request.args.get('cow_id', type=int)
        conn = get_db_connection()
        cursor = conn.cursor()
        if cow_id:
            cursor.execute("""
                SELECT w.*, c.ear_tag, c.name as cow_name FROM cow_weight_records w
                JOIN cows c ON w.cow_id = c.id WHERE w.cow_id = %s ORDER BY w.weighing_date DESC
            """, (cow_id,))
        else:
            cursor.execute("""
                SELECT w.*, c.ear_tag, c.name as cow_name FROM cow_weight_records w
                JOIN cows c ON w.cow_id = c.id ORDER BY w.weighing_date DESC LIMIT 200
            """)
        records = cursor.fetchall()
        cursor.close()
        conn.close()
        for r in records:
            if r.get('weighing_date'):
                r['weighing_date'] = str(r['weighing_date'])
        return jsonify({'success': True, 'records': records})
    except Exception as e:
        return jsonify({'success': False, 'error': str(e)}), 500

